import spidev
import Adafruit_GPIO.MCP3208 as MCP3208
import gpiozero

MIN_CHANNEL = 0
MAX_CHANNEL = 7
SPI_PORT = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1_000_000


def read_mcp3208_gpiozero(channel: int) -> float:
    """Read analog data from MCP3208 channel using gpiozero."""
    if not (MIN_CHANNEL <= channel <= MAX_CHANNEL):
        raise ValueError(f"Channel must be {MIN_CHANNEL}..{MAX_CHANNEL}, got {channel}")

    try:
        sensor = gpiozero.MCP3208(channel=channel)
        try:
            return sensor.value
        finally:
            sensor.close()
    except Exception as exc:
        print(f"gpiozero read error on channel {channel}: {exc}")
        return -1.0


def read_mcp3208_spidev(channel: int) -> int:
    """Read analog data from MCP3208 channel using spidev."""
    if not (MIN_CHANNEL <= channel <= MAX_CHANNEL):
        raise ValueError(f"Channel must be {MIN_CHANNEL}..{MAX_CHANNEL}, got {channel}")

    spi = spidev.SpiDev()
    try:
        spi.open(SPI_PORT, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        spi.lsbfirst = False

        command = 0x18 | (channel & 0x07)  # start=1, single=1, channel bits
        data = spi.xfer2([command, 0x00, 0x00])

        if data is None or len(data) < 3:
            print("spidev: incomplete SPI transfer")
            return -1

        return ((data[1] & 0x0F) << 8) | data[2]
    except Exception as exc:
        print(f"spidev read error on channel {channel}: {exc}")
        return -1
    finally:
        try:
            spi.close()
        except Exception:
            pass


def read_mcp3208_adafruit(channel: int) -> int:
    """Read analog data from MCP3208 channel using Adafruit_GPIO."""
    if not (MIN_CHANNEL <= channel <= MAX_CHANNEL):
        raise ValueError(f"Channel must be {MIN_CHANNEL}..{MAX_CHANNEL}, got {channel}")

    mcp = None
    try:
        mcp = MCP3208.MCP3208(spi=SPI_PORT, cs=SPI_DEVICE)
        return mcp.read(channel)
    except Exception as exc:
        print(f"Adafruit_GPIO read error on channel {channel}: {exc}")
        return -1
    finally:
        if mcp is not None:
            try:
                mcp.close()
            except Exception:
                pass


if __name__ == "__main__":
    channel = 0
    gpiozero_val = read_mcp3208_gpiozero(channel)
    spidev_val = read_mcp3208_spidev(channel)
    adafruit_val = read_mcp3208_adafruit(channel)

    print(f"Channel {channel}: gpiozero={gpiozero_val}, spidev={spidev_val}, adafruit={adafruit_val}")

    if gpiozero_val == -1 or spidev_val == -1 or adafruit_val == -1:
        print("One or more ADC reads failed.")

