import RPi.GPIO as GPIO
import time
import logging
import atexit
import threading
from datetime import datetime

# Constants
MOTION_PIN = 17
LIGHT_PIN = 27
LED_PIN = 22
AMBIENT_LIGHT_THRESHOLD = 60
DEBOUNCE_MS = 200
LED_ON_DURATION = 60
LED_OFF_DELAY = 300
SAMPLING_PERIOD = 1.0
MOTION_THRESHOLD = 2

# Logging setup
log_level = logging.DEBUG if "DEBUG_MODE" in os.environ else logging.INFO
logging.basicConfig(
    level=log_level,
    format="%(asctime)s - %(levelname)s - %(message)s",
    handlers=[
        logging.FileHandler("occupancy_lights.log"),
        logging.StreamHandler(),
    ],
)


class MotionSensor:
    """Detects motion on a GPIO pin with a configurable sampling period."""

    def __init__(self, pin, sampling_period=SAMPLING_PERIOD):
        self.pin = pin
        self.sampling_period = sampling_period
        self.motion_count = 0
        self.lock = threading.Lock()
        self._setup_gpio()

    def _setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            GPIO.add_event_detect(
                self.pin, GPIO.RISING, callback=self._motion_callback, bouncetime=DEBOUNCE_MS
            )
            logging.debug(f"Motion sensor initialized on GPIO {self.pin}")
        except Exception as e:
            logging.error(f"Error setting up GPIO for motion sensor on pin {self.pin}: {e}")
            raise

    def _motion_callback(self, channel):
        try:
            with self.lock:
                self.motion_count += 1
            logging.debug(f"Motion detected on pin {self.pin} (count: {self.motion_count})")
        except Exception as e:
            logging.error(f"Error in motion callback on pin {self.pin}: {e}")

    def get_motion_count(self):
        with self.lock:
            return self.motion_count

    def reset_motion_count(self):
        with self.lock:
            self.motion_count = 0

    def check_motion_threshold(self, threshold):
        with self.lock:
            return self.motion_count > threshold


class LightingController:
    """Controls an LED based on motion and ambient light levels."""

    def __init__(self, led_pin, motion_sensor, ambient_light_threshold=AMBIENT_LIGHT_THRESHOLD):
        self.led_pin = led_pin
        self.motion_sensor = motion_sensor
        self.ambient_light_threshold = ambient_light_threshold
        self.light_on = False
        self.timer = None
        self.lock = threading.Lock()
        self._setup_gpio()

    def _setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.led_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.debug(f"Lighting controller initialized on GPIO {self.led_pin}")
        except Exception as e:
            logging.error(f"Error setting up GPIO for lighting controller on pin {self.led_pin}: {e}")
            raise

    def get_ambient_light_level(self):
        """Simulates reading ambient light level (0-100). Replace with real ADC read."""
        return 50

    def turn_light_on(self):
        try:
            GPIO.output(self.led_pin, GPIO.HIGH)
            self.light_on = True
            logging.info("Light turned ON")
        except Exception as e:
            logging.error(f"Error turning light on: {e}")

    def turn_light_off(self):
        try:
            GPIO.output(self.led_pin, GPIO.LOW)
            self.light_on = False
            logging.info("Light turned OFF")
        except Exception as e:
            logging.error(f"Error turning light off: {e}")

    def _turn_light_off_after_delay(self):
        try:
            with self.lock:
                if self.light_on:
                    self.turn_light_off()
                    logging.info("Light turned OFF after delay")
        except Exception as e:
            logging.error(f"Error in delayed light off: {e}")

    def control_light(self):
        try:
            with self.lock:
                if self.motion_sensor.check_motion_threshold(MOTION_THRESHOLD):
                    ambient_light = self.get_ambient_light_level()
                    if ambient_light >= self.ambient_light_threshold:
                        if not self.light_on:
                            self.turn_light_on()
                            self.timer = threading.Timer(LED_ON_DURATION, self._turn_light_off_after_delay)
                            self.timer.daemon = True
                            self.timer.start()
                    else:
                        logging.debug(
                            f"Ambient light {ambient_light} below threshold {self.ambient_light_threshold}; light remains OFF"
                        )
                elif self.light_on and self.timer and self.timer.is_alive():
                    self.timer.cancel()
                    self.turn_light_off()
                    logging.info("Light turned OFF due to motion timeout")
        except Exception as e:
            logging.error(f"Error controlling light: {e}")


def main():
    try:
        motion_sensor = MotionSensor(MOTION_PIN, SAMPLING_PERIOD)
        lighting_controller = LightingController(LED_PIN, motion_sensor)

        def cleanup():
            logging.info("Cleaning up GPIO...")
            GPIO.cleanup()

        atexit.register(cleanup)

        logging.info("Starting occupancy-lights system")
        while True:
            motion_sensor.reset_motion_count()
            time.sleep(SAMPLING_PERIOD)
            if motion_sensor.check_motion_threshold(MOTION_THRESHOLD):
                logging.info("Motion threshold exceeded")
                lighting_controller.control_light()
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        GPIO.cleanup()
        logging.info("Program exiting")


if __name__ == "__main__":
    main()

