                raise ValueError("gpio_pins must be provided for digital sensor")
            self.gpio_initialized = True
            GPIO.setmode(GPIO.BCM)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        elif self.sensor_type == "analog":
            if spidev is None:
                raise RuntimeError("spidev not available")
            if not self.channels:
                raise ValueError("channels must be provided for analog sensor")
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                raise RuntimeError(f"Failed to open SPI: {e}")
        else:
            raise ValueError(f"Unknown sensor_type: {self.sensor_type}")

    def read_digital(self):
        """Read digital sound sensor (KY-038 digital output)."""
        if not self.gpio_pins:
            raise RuntimeError("No GPIO pins configured")
        return [GPIO.input(pin) for pin in self.gpio_pins]

    def read_analog(self):
        """Read analog sound sensor (KY-038 analog output via MCP3008)."""
        if not self.channels:
            raise RuntimeError("No channels configured")
        if self.spi is None:
            raise RuntimeError("SPI not initialized")
        values = []
        for channel in self.channels:
            if not 0 <= channel <= 7:
                raise ValueError(f"Invalid channel {channel}")
            try:
                # MCP3008 single-ended read: start=1, mode=1 (single-ended),
                # channel bits (3 bits), then dummy byte
                r = self.spi.xfer2([1, (8 + channel) << 4, 0])
                value = ((r[1] & 3) << 8) + r[2]
                values.append(value)
            except Exception as e:
                logging.error(f"SPI read error on channel {channel}: {e}")
                values.append(0)
        return values

    def read_sound_level(self):
        """Read sound level and return (level, valid)."""
        if self.sensor_type == "digital":
            try:
                digital = self.read_digital()
                level = sum(digital)
                valid = all(d == 1 for d in digital)
                return level, valid
            except Exception as e:
                logging.error(f"Error reading digital sensor {self.sensor_id}: {e}")
                return 0, False
        elif self.sensor_type == "analog":
            try:
                analog = self.read_analog()
                level = sum(analog)
                valid = all(a >= self.threshold for a in analog)
                return level, valid
            except Exception as e:
                logging.error(f"Error reading analog sensor {self.sensor_id}: {e}")
                return 0, False
        return 0, False

    def run(self):
        """Continuously monitor sound level and log events."""
        self.running = True
        logging.info(f"SoundSensor {self.sensor_id} started (type={self.sensor_type}, rate={self.sample_rate} Hz)")
        while self.running:
            level, valid = self.read_sound_level()
            if valid:
                logging.info(f"Sound event detected by {self.sensor_id} (level={level}, valid={valid})")
                if self.log_queue:
                    try:
                        self.log_queue.put((self.sensor_id, level, valid))
                    except queue.Full:
                        logging.warning("Log queue full, dropping event")
                time.sleep(0.1)
            time.sleep(1.0 / self.sample_rate)

    def stop(self):
        """Stop the sensor thread and release resources."""
        self.running = False
        if self.sensor_type == "digital" and self.gpio_initialized:
            try:
                GPIO.cleanup()
            except Exception as e:
                logging.error(f"Error cleaning up GPIO: {e}")
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"Error closing SPI: {e}")


def main():
    parser = argparse.ArgumentParser(description="SoundSensor for Raspberry Pi")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"])
    parser.add_argument("--threshold", type=int, default=500)
    parser.add_argument("--sample_rate", type=int, default=10)
    parser.add_argument("--log_file", default="sound_sensor.log")
    parser.add_argument("--gpio_pins", nargs="+", type=int, default=[])
    parser.add_argument("--channels", nargs="+", type=int, default=[])
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", nargs="+", default=["sensor1"])
    args = parser.parse_args()

    logging.basicConfig(
        filename=args.log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Starting SoundSensor application")

    log_queue = queue.Queue(maxsize=100)
    sensors = []
    threads = []

    for sid in args.sensor_ids:
        try:
            sensor = SoundSensor(
                sensor_id=sid,
                sensor_type=args.sensor_type,
                threshold=args.threshold,
                sample_rate=args.sample_rate,
                gpio_pins=args.gpio_pins,
                channels=args.channels,
                spi_speed=args.spi_speed,
                log_queue=log_queue,
            )
            sensors.append(sensor)
            t = threading.Thread(target=sensor.run, daemon=True)
            t.start()
            threads.append(t)
        except Exception as e:
            logging.error(f"Failed to create sensor {sid}: {e}")

    def signal_handler(signum, frame):
        logging.info(f"Received signal {signum}, shutting down...")
        for sensor in sensors:
            sensor.stop()
        for t in threads:
            t.join(timeout=2)
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            try:
                sid, level, valid = log_queue.get(timeout=1)
                logging.info(f"Logged event: {sid} level={level} valid={valid}")
            except queue.Empty:
                pass
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received")
    finally:
        for sensor in sensors:
            sensor.stop()
        for t in threads:
            t.join(timeout=2)
        logging.info("SoundSensor application stopped")


if __name__ == "__main__":
    main()

