import cv2
import signal
import sys
import time
from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def cleanup(picam2=None):
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass
    cv2.destroyAllWindows()

def main():
    global running

    face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
    eye_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_eye.xml')

    if face_cascade.empty() or eye_cascade.empty():
        raise RuntimeError("Failed to load Haar cascade classifiers. Check OpenCV installation.")

    picam2 = Picamera2()
    try:
        config = picam2.create_preview_configuration(main={"format": 'BGR888', "size": (640, 480)})
        picam2.configure(config)
        picam2.start()
    except Exception as e:
        print(f"Camera initialization failed: {e}", file=sys.stderr)
        cleanup(picam2)
        sys.exit(1)

    try:
        while running:
            try:
                frame = picam2.capture_array()
            except Exception as e:
                print(f"Frame capture failed: {e}", file=sys.stderr)
                time.sleep(0.1)
                continue

            if frame is None:
                continue

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))

            for (x, y, w, h) in faces:
                roi_gray = gray[y:y+h, x:x+w]
                eyes = eye_cascade.detectMultiScale(roi_gray, scaleFactor=1.1, minNeighbors=3, minSize=(20, 20))
                for (ex, ey, ew, eh) in eyes:
                    cv2.rectangle(frame, (x+ex, y+ey), (x+ex+ew, y+ey+eh), (0, 0, 255), 2)
                cv2.rectangle(frame, (x, y), (x+w, y+h), (0, 255, 0), 2)

            cv2.imshow("Face and Eye Detection", frame)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    finally:
        cleanup(picam2)

if __name__ == "__main__":
    main()

