import cv2
import numpy as np
import signal
import sys
import logging
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

running = True

def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down gracefully...")
    running = False

def initialize_camera(camera_num):
    try:
        picam2 = Picamera2(camera_num=camera_num)
        config = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )
        picam2.configure(config)
        picam2.start()
        logger.info(f"Camera {camera_num} initialized successfully.")
        return picam2
    except Exception as e:
        logger.error(f"Failed to initialize camera {camera_num}: {e}")
        return None

def capture_and_process(picam1, picam2):
    global running
    try:
        frame1 = picam1.capture_array()
        frame2 = picam2.capture_array()
        if frame1 is None or frame2 is None:
            logger.warning("Captured null frame from one or both cameras.")
            return None
        combined_image = np.hstack((frame1, frame2))
        return combined_image
    except Exception as e:
        logger.error(f"Error during capture/processing: {e}")
        return None

def display_image(image, window_title):
    try:
        cv2.imshow(window_title, image)
        key = cv2.waitKey(30) & 0xFF
        if key == 27:
            return False
        props = cv2.getWindowProperty(window_title, cv2.WND_PROP_AUTOSIZE)
        if props < 0:
            return False
        return True
    except cv2.error as e:
        logger.error(f"OpenCV error displaying image: {e}")
        return False
    except Exception as e:
        logger.error(f"Unexpected error in display: {e}")
        return False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    picam1 = initialize_camera(0)
    picam2 = initialize_camera(1)

    if picam1 is None or picam2 is None:
        logger.error("One or both cameras failed to initialize. Exiting.")
        if picam1 is not None:
            try:
                picam1.stop()
            except Exception:
                pass
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
        cv2.destroyAllWindows()
        sys.exit(1)

    try:
        while running:
            image = capture_and_process(picam1, picam2)
            if image is None:
                continue
            if not display_image(image, 'Dual CSI Cameras'):
                running = False
    except KeyboardInterrupt:
        logger.info("KeyboardInterrupt received, exiting...")
    finally:
        logger.info("Cleaning up resources...")
        try:
            picam1.stop()
        except Exception:
            pass
        try:
            picam2.stop()
        except Exception:
            pass
        cv2.destroyAllWindows()
        logger.info("Shutdown complete.")

if __name__ == "__main__":
    main()

