import multiprocessing
import os
import signal
import time
import atexit
import threading
import traceback
import errno

from setproctitle import setproctitle

from config import config
from controlevents import CEvent, PostEvent, ConsoleEvent
from logsupport import L
from utils.utilfuncs import disptime

# Constants
FAILSAFE_INTERVAL_SECONDS = 30
KEEPALIVE_TIMEOUT_SECONDS = 60
TOMBSTONE_FILE = '/home/pi/.tombstoneW'
HISTORY_LOG_FILE = '/home/pi/Console/.HistoryBuffer/hlogW'

# Global event for keep-alive signals
KeepAlive = multiprocessing.Event()

# Watchdog process PID (set by main)
Watchdog_pid = None


def _write_history(message: str) -> None:
    """Append a message to the history log, flushing immediately after each write."""
    try:
        with open(HISTORY_LOG_FILE, 'a') as f:
            f.write(message + '\n')
            f.flush()
    except OSError as e:
        # Best-effort logging; never crash the watchdog.
        L.Logs.Log('Error writing to history log: %s', e)


def _log_debug(message: str) -> None:
    """Log a debug message with a timestamp."""
    timestamp = disptime()
    _write_history(f'{timestamp} {message}')


def _is_process_alive(pid: int) -> bool:
    """Check if a process with the given PID is still running."""
    try:
        os.kill(pid, 0)
        return True
    except OSError as e:
        if e.errno == errno.ESRCH:
            return False
        # Unexpected error; log and return False to be safe.
        L.Logs.Log(f'Unexpected error checking process {pid}: {e}')
        return False


def _terminate_console(reason: str) -> None:
    """Send SIGTERM to the console process, wait 30 seconds, then SIGKILL."""
    console_pid = getattr(config.sysStore, 'Console_pid', None)
    if console_pid is None:
        _log_debug('No Console_pid in config.sysStore; nothing to terminate.')
        return

    _log_debug(f'Terminating console (PID {console_pid}) due to {reason}')

    # Try SIGTERM first
    if _is_process_alive(console_pid):
        try:
            os.kill(console_pid, signal.SIGTERM)
        except OSError as e:
            _log_debug(f'Failed to send SIGTERM to console (PID {console_pid}): {e}')
            return

    # Wait for graceful shutdown
    deadline = time.time() + 30
    while _is_process_alive(console_pid) and time.time() < deadline:
        time.sleep(0.5)

    if _is_process_alive(console_pid):
        _log_debug(f'Console did not exit gracefully; sending SIGKILL (PID {console_pid}).')
        try:
            os.kill(console_pid, signal.SIGKILL)
        except OSError as e:
            _log_debug(f'Failed to send SIGKILL to console (PID {console_pid}): {e}')


def _failsafe_exit(signum, frame) -> None:
    """Handle SIGTERM (systemd) and SIGINT (watchdog self-termination)."""
    _log_debug('Failsafe exit triggered.')
    _terminate_console('failsafe exit')
    # Give the console a moment to exit before we exit.
    time.sleep(30)
    os._exit(0)


def _abort_exit(signum, frame) -> None:
    """Handle SIGABRT: write a tombstone and exit with code 93."""
    _log_debug('Abort exit triggered.')
    try:
        with open(TOMBSTONE_FILE, 'a') as f:
            f.write(f'{time.time()} Watchdog {os.getpid()} exiting for signal {signum}\n')
            traceback.print_stack(file=f)
    except OSError as e:
        _log_debug(f'Failed to write tombstone: {e}')
    os._exit(93)


def _hangup_exit(signum, frame) -> None:
    """Handle SIGHUP: log and ignore."""
    _log_debug('Hangup exit triggered.')


def _ignore_exit(signum, frame) -> None:
    """Handle SIGUSR1: log and ignore."""
    _log_debug('Ignore exit triggered.')


def _exit_exit(signum, frame) -> None:
    """Handle SIGINT: log and exit with code 94."""
    _log_debug('Exit exit triggered.')
    os._exit(94)


def _signal_handler(signum, frame) -> None:
    """Generic signal handler wrapper."""
    try:
        handler = {
            signal.SIGTERM: _failsafe_exit,
            signal.SIGINT: _exit_exit,
            signal.SIGUSR1: _ignore_exit,
            signal.SIGHUP: _hangup_exit,
            signal.SIGABRT: _abort_exit,
        }.get(signum)
        if handler is not None:
            handler(signum, frame)
        else:
            _log_debug(f'Unhandled signal {signum} received.')
    except Exception as e:
        _log_debug(f'Exception in signal handler for signal {signum}: {e}')


def _inject_watchdog_events() -> None:
    """Periodically inject watchdog ping events."""
    while True:
        try:
            now = time.time()
            L.Logs.Log('Inject:', 'Watchdog', CEvent.FailSafePing, inject=now)
            PostEvent(ConsoleEvent(CEvent.FailSafePing, inject=now))
            time.sleep(FAILSAFE_INTERVAL_SECONDS)
        except Exception as e:
            _log_debug(f'Exception in injector loop: {e}')
            time.sleep(FAILSAFE_INTERVAL_SECONDS)


def _check_main_thread() -> None:
    """Check if MainThread is alive; if not, terminate the console."""
    try:
        import threading as t
        main_thread = next((t.get_ident() for t in t.enumerate() if getattr(t, 'name', None) == 'MainThread'), None)
        if main_thread is None:
            _log_debug('MainThread not found; terminating console.')
            _terminate_console('MainThread disappeared')
    except Exception as e:
        _log_debug(f'Exception in MainThread check: {e}')


def _atexit_handler() -> None:
    """Handle unexpected watchdog exit."""
    _log_debug('Atexit handler triggered.')
    console_pid = getattr(config.sysStore, 'Console_pid', None)
    if console_pid is None:
        _log_debug('No Console_pid in config.sysStore; nothing to terminate.')
        return

    _log_debug(f'Atexit handler: terminating console (PID {console_pid}) due to watchdog exit.')
    _terminate_console('atexit handler')


def _watchdog_process() -> None:
    """Main entry point for the watchdog process."""
    global Watchdog_pid
    Watchdog_pid = os.getpid()
    setproctitle('Console Watchdog')

    # Register signal handlers
    for sig in (signal.SIGTERM, signal.SIGINT, signal.SIGUSR1, signal.SIGHUP, signal.SIGABRT):
        signal.signal(sig, _signal_handler)

    # Register atexit handler
    atexit.register(_atexit_handler)

    # Start injector thread
    injector = threading.Thread(target=_inject_watchdog_events, name='Injector', daemon=True)
    injector.start()

    # Main loop
    while True:
        try:
            if not KeepAlive.wait(KEEPALIVE_TIMEOUT_SECONDS):
                _log_debug('KeepAlive timeout; terminating console.')
                _terminate_console('keepalive timeout')
        except Exception as e:
            _log_debug(f'Exception in main watchdog loop: {e}')
            time.sleep(1)


def _start_watchdog() -> multiprocessing.Process:
    """Start the watchdog process."""
    process = multiprocessing.Process(target=_watchdog_process, name='Watchdog')
    process.start()
    return process


def _inject_watchdog_start() -> None:
    """Inject a watchdog start event."""
    L.Logs.Log('Inject:', 'Watchdog', CEvent.FailSafeStart, inject=time.time())
    PostEvent(ConsoleEvent(CEvent.FailSafeStart, inject=time.time()))


def _start_watchdog_if_needed() -> None:
    """Start the watchdog if it is not already running."""
    global Watchdog_pid
    if Watchdog_pid is None:
        _log_debug('Starting watchdog.')
        _inject_watchdog_start()
        Watchdog_pid = _start_watchdog().pid
        _log_debug(f'Watchdog started with PID {Watchdog_pid}')
    else:
        _log_debug(f'Watchdog already running with PID {Watchdog_pid}')


def _check_watchdog() -> None:
    """Check if the watchdog process is alive."""
    global Watchdog_pid
    if Watchdog_pid is not None and not _is_process_alive(Watchdog_pid):
        _log_debug(f'Watchdog process (PID {Watchdog_pid}) is not running.')
        Watchdog_pid = None


def _ensure_watchdog_running() -> None:
    """Ensure the watchdog is running."""
    _check_watchdog()
    if Watchdog_pid is None:
        _start_watchdog_if_needed()


def _ping_watchdog() -> None:
    """Ping the watchdog to reset the keep-alive timer."""
    _ensure_watchdog_running()
    if Watchdog_pid is not None:
        KeepAlive.set()


def _shutdown_watchdog() -> None:
    """Shut down the watchdog process."""
    global Watchdog_pid
    if Watchdog_pid is not None:
        _log_debug(f'Shutting down watchdog (PID {Watchdog_pid}).')
        try:
            os.kill(Watchdog_pid, signal.SIGTERM)
        except OSError as e:
            _log_debug(f'Failed to send SIGTERM to watchdog (PID {Watchdog_pid}): {e}')
        Watchdog_pid = None


def _restart_watchdog() -> None:
    """Restart the watchdog process."""
    _shutdown_watchdog()
    _start_watchdog_if_needed()


def _is_watchdog_alive() -> bool:
    """Check if the watchdog process is currently running."""
    _check_watchdog()
    return Watchdog_pid is not None and _is_process_alive(Watchdog_pid)


def _is_console_alive() -> bool:
    """Check if the console process is currently running."""
    console_pid = getattr(config.sysStore, 'Console_pid', None)
    if console_pid is None:
        return False
    return _is_process_alive(console_pid)


def _is_main_thread_alive() -> bool:
    """Check if the MainThread is currently running."""
    try:
        import threading as t
        main_thread = next((t.get_ident() for t in t.enumerate() if getattr(t, 'name', None) == 'MainThread'), None)
        return main_thread is not None
    except Exception:
        return False

