#!/usr/bin/env python3
"""Wildlife Camera System for Raspberry Pi using PIR motion sensor and camera."""

import os
import sys
import time
import signal
import logging
import configparser
from datetime import datetime
from pathlib import Path

try:
    from gpiozero import MotionSensor
    from picamera2 import Picamera2
    from picamera2.encoders import H264Encoder
    from picamera2.outputs import FileOutput
except ImportError as e:
    print(f"Missing required library: {e}", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Configuration defaults
# ---------------------------------------------------------------------------
DEFAULT_CONFIG = {
    'resolution': '640x480',
    'frame_rate': '20',
    'image_quality': '85',
    'video_bitrate': '1700000',
    'gpio_pin': '4',
    'motion_delay': '2',
    'storage_directory': '/home/pi/wildlife_media',
    'disk_space_threshold_mb': '500',
    'log_file': '/var/log/wildlifecam/wildlifecam.log',
    'log_level': 'INFO',
}

# ---------------------------------------------------------------------------
# Global state for cleanup
# ---------------------------------------------------------------------------
_running = True
_camera = None
_pir = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _setup_logging(log_file: str, log_level: str) -> logging.Logger:
    """Configure file logging, falling back to ./logs if the directory is not writable."""
    log_dir = Path(log_file).parent
    if log_dir.exists() and not os.access(str(log_dir), os.W_OK):
        fallback = Path('./logs')
        try:
            fallback.mkdir(parents=True, exist_ok=True)
            log_file = str(fallback / Path(log_file).name)
            print(f"Log directory not writable, falling back to {log_file}", file=sys.stderr)
        except OSError as e:
            print(f"Cannot create local log directory: {e}", file=sys.stderr)
            sys.exit(1)

    logger = logging.getLogger('wildlifecam')
    logger.setLevel(getattr(logging, log_level.upper(), logging.INFO))
    logger.propagate = False

    if not logger.handlers:
        try:
            handler = logging.FileHandler(log_file)
            handler.setFormatter(
                logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
            )
            logger.addHandler(handler)
        except OSError as e:
            print(f"Cannot open log file {log_file}: {e}", file=sys.stderr)
            sys.exit(1)

    return logger


def _load_config(config_file: str) -> configparser.ConfigParser:
    """Load config.ini, creating defaults if missing."""
    config = configparser.ConfigParser()
    if not config.read(config_file):
        print(f"Config file {config_file} not found; creating defaults.", file=sys.stderr)
        config['DEFAULT'] = DEFAULT_CONFIG
        try:
            with open(config_file, 'w', encoding='utf-8') as f:
                config.write(f)
        except OSError as e:
            print(f"Cannot write default config: {e}", file=sys.stderr)
            sys.exit(1)
    return config


def _parse_resolution(res: str):
    """Parse 'WxH' into (width, height)."""
    try:
        w, h = res.lower().split('x')
        return int(w), int(h)
    except Exception:
        return 640, 480


def _parse_bool(value: str):
    return value.strip().lower() in ('true', '1', 'yes')


def _ensure_storage_path(path: Path) -> Path:
    """Create storage directory tree; exit on failure."""
    try:
        path.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        print(f"Cannot create storage directory {path}: {e}", file=sys.stderr)
        sys.exit(1)
    return path


def _available_space(path: Path) -> int:
    """Return available disk space in bytes, or 0 on error."""
    try:
        statvfs = os.statvfs(str(path))
        return statvfs.f_frsize * statvfs.f_bavail
    except OSError:
        return 0


def _delete_oldest_files(path: Path, threshold_mb: int):
    """Delete oldest files (videos before images) until space exceeds threshold."""
    try:
        files = sorted(
            (f for f in path.iterdir() if f.is_file()),
            key=lambda p: p.stat().st_mtime,
        )
    except OSError:
        return

    total_mb = _available_space(path) // (1024 * 1024)
    if total_mb >= threshold_mb:
        return

    video_exts = ('.h264', '.mp4')
    image_exts = ('.jpg', '.jpeg', '.png')

    for f in files:
        if f.suffix in video_exts:
            try:
                f.unlink()
                logging.info(f"Deleted old video: {f}")
            except OSError as e:
                logging.error(f"Failed to delete {f}: {e}")
            total_mb = _available_space(path) // (1024 * 1024)
            if total_mb >= threshold_mb:
                break
        elif f.suffix in image_exts:
            # Images are kept; video files are deleted first.
            break


def _save_image(camera: Picamera2, path: Path, quality: int):
    """Capture a single JPEG image at the configured resolution."""
    try:
        camera.capture_file(str(path), format='jpeg', quality=quality)
        logging.info(f"Saved image: {path}")
    except Exception as e:
        logging.error(f"Failed to save image {path}: {e}")


def _save_video(camera: Picamera2, path: Path, bitrate: int):
