        self.last_frame: Optional[bytes] = None
        self.last_email_time: float = 0.0
        self.last_email_object: Optional[str] = None
        self.motion_detected = False
        self.output = None
        self._stop_event = threading.Event()

    def initialize_camera(self) -> bool:
        """Initialize picamera2 with a 640x480 JPEG stream configuration."""
        try:
            self.picam2 = Picamera2()
            # Still configuration with JPEG output at 640x480
            config_cam = self.picam2.create_still_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                transform=Picamera2.Transform(vflip=True),  # vertical flip
            )
            self.picam2.configure(config_cam)
            self.picam2.start()
            # Allow a brief warm-up so the first frame is not underexposed
            time.sleep(1)
            return True
        except Exception as exc:
            print(f"Camera initialization failed: {exc}", file=sys.stderr)
            traceback.print_exc()
            self.picam2 = None
            return False

