                img.save(buf, format="JPEG", quality=85)
                frame = buf.getvalue()
                self.last_frame = frame
                return frame
        except Exception as exc:
            print(f"Frame capture failed: {exc}", file=sys.stderr)
            traceback.print_exc()
            return None

