            traceback.print_exc()
            time.sleep(5)


def gen(camera):
    """Generate MJPEG frames for the video feed."""
    while not camera._stop_event.is_set():
        frame = camera.get_frame()
        if frame:
            yield (
                b"--frame\r\n"
                b"Content-Type: image/jpeg\r\n\r\n" + frame + b"\r\n\r\n"
            )
        else:
            time.sleep(0.1)


@app.route("/", methods=["GET", "POST"])
def index():
    if request.method == "POST":
        config.classifier_name = request.form.get("classifier", "motion_detector")
        config.send_email_notifications = "send_email_notifications" in request.form
        config.receiver_email_address = request.form.get(
            "receiver_email_address", ""
        )
        try:
            config.email_send_interval = int(
                request.form.get("email_send_interval", "5")
            )
        except ValueError:
            config.email_send_interval = 5
        print(f"Config updated: {config.classifier_name}")
    return render_template(
        "index.html",
        classifiers=["motion_detector", "person"],
        config=config,
    )


@app.route("/video_feed")
def video_feed():
    return Response(
        gen(camera),
        mimetype="multipart/x-mixed-replace; boundary=frame",
    )


def _signal_handler(signum, frame):
    print(f"Signal {signum} received, shutting down...")
    camera.stop()
    sys.exit(0)


if __name__ == "__main__":
    if not camera.initialize_camera():
        print("Failed to initialize camera. Exiting.", file=sys.stderr)
        sys.exit(1)

    # Register cleanup and signal handlers
    atexit.register(camera._cleanup)
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Start the object detection thread
    object_detection_thread = threading.Thread(
        target=check_for_objects, daemon=True
    )
    object_detection_thread.start()

    try:
        app.run(host="0.0.0.0", debug=False, threaded=True)
    finally:
        camera.stop()
        print("Camera released.")

