import json
import logging
import os
import signal
import statistics
import time
from pathlib import Path

from gpiozero import DigitalOutputDevice, DigitalInputDevice

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

running = True


def signal_handler(signum, frame):
    global running
    running = False


def load_config(path):
    try:
        with open(path, "r") as f:
            cfg = json.load(f)
        if not isinstance(cfg.get("sensors"), list) or len(cfg["sensors"]) < 1:
            raise ValueError("sensors must be a non-empty list")
        for s in cfg["sensors"]:
            if not isinstance(s, dict):
                raise ValueError("each sensor must be a dict")
            for key in ("trigger_pin", "echo_pin", "offset", "max_distance"):
                if key not in s:
                    raise ValueError(f"missing key '{key}' in sensor config")
        return cfg
    except FileNotFoundError:
        logging.warning("config.json not found; using default configuration.")
        return DEFAULT_CONFIG
    except (json.JSONDecodeError, ValueError) as e:
        logging.error(f"Invalid config.json: {e}; using default configuration.")
        return DEFAULT_CONFIG


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def measure_distance(trigger, echo, offset, max_distance):
    try:
        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        timeout = time.time() + 0.05
        while echo.value == 0:
            if time.time() > timeout:
                logging.warning(f"Echo timeout waiting for rising edge on pin {echo.pin.number}")
                return None
        start = time.time()

        timeout = time.time() + 0.05
        while echo.value == 1:
            if time.time() > timeout:
                logging.warning(f"Echo timeout waiting for falling edge on pin {echo.pin.number}")
                return None
        stop = time.time()

        pulse_duration = stop - start
        distance = (pulse_duration * 34300) / 2
        distance = max(0.0, min(distance + offset, max_distance))
        water_level = max_distance - distance
        return water_level
    except Exception as e:
        logging.error(f"Error measuring distance on trigger={trigger.pin.number}, echo={echo.pin.number}: {e}")
        return None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    setup_logging(config.get("log_file", DEFAULT_CONFIG["log_file"]))

    sensors = []
    for s in config["sensors"]:
        try:
            trig = DigitalOutputDevice(s["trigger_pin"])
            echo = DigitalInputDevice(s["echo_pin"])
            sensors.append({"trigger": trig, "echo": echo, **s})
            logging.info(f"Initialized sensor on trigger={s['trigger_pin']}, echo={s['echo_pin']}")
        except Exception as e:
            logging.error(f"Failed to initialize GPIO pins {s['trigger_pin']}/{s['echo_pin']}: {e}")
            sensors.append({"trigger": None, "echo": None, **s})

    alert_state = {"low": False, "high": False, "last_alert_time": 0.0}
    alert_repeat_delay = config.get("alert_repeat_delay", DEFAULT_CONFIG["alert_repeat_delay"])
    alert_threshold_low = config.get("alert_threshold_low", DEFAULT_CONFIG["alert_threshold_low"])
    alert_threshold_high = config.get("alert_threshold_high", DEFAULT_CONFIG["alert_threshold_high"])

    try:
        while running:
            readings = []
            for s in sensors:
                if s["trigger"] is None or s["echo"] is None:
                    readings.append(None)
                    continue
                for _ in range(3):
                    wl = measure_distance(s["trigger"], s["echo"], s["offset"], s["max_distance"])
                    if wl is not None:
                        readings.append(wl)
                        break
                if len(readings) < 3:
                    logging.warning(f"Sensor on trigger={s['trigger_pin']} failed after 3 attempts; skipping.")
                    readings.append(None)

            if all(r is None for r in readings):
                logging.warning("All sensors failed; skipping this cycle.")
            else:
                valid = [r for r in readings if r is not None]
                if valid:
                    avg = statistics.mean(valid)
                    logging.info(f"Average water level: {avg:.2f} cm")
                    if avg < alert_threshold_low and not alert_state["low"]:
                        now = time.time()
                        if now - alert_state["last_alert_time"] >= alert_repeat_delay:
                            logging.warning(f"Water level LOW: {avg:.2f} cm")
                            alert_state["low"] = True
                            alert_state["last_alert_time"] = now
                    elif avg >= alert_threshold_low:
                        alert_state["low"] = False
                    if avg > alert_threshold_high and not alert_state["high"]:
                        now = time.time()
                        if now - alert_state["last_alert_time"] >= alert_repeat_delay:
                            logging.warning(f"Water level HIGH: {avg:.2f} cm")
                            alert_state["high"] = True
                            alert_state["last_alert_time"] = now
                    elif avg <= alert_threshold_high:
                        alert_state["high"] = False
                else:
                    logging.warning("No valid readings from any sensor.")

            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        for s in sensors:
            if s["trigger"] is not None:
                s["trigger"].close()
            if s["echo"] is not None:
                s["echo"].close()
        logging.info("GPIO cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

