import RPi.GPIO as GPIO
import time
import datetime
import signal
import sys
import random

try:
    import speech_recognition as sr
except ImportError:
    print("Warning: speech_recognition library not found. Voice commands will be simulated.")
    sr = None

try:
    from picamera2 import Picamera2
except ImportError:
    print("Warning: picamera2 library not found. Camera functionality will be simulated.")
    Picamera2 = None

try:
    import adafruit_dht
    import board
    DHT_AVAILABLE = True
except ImportError:
    print("Warning: adafruit_dht or board library not found. DHT11 sensor will be simulated.")
    DHT_AVAILABLE = False

# Constants
LIGHTS_PIN = 17
DHT_PIN = 4
WAKE_WORD = "Greenhouse"

# Global state
gpio_available = False
camera = None
dht_device = None

def log_message(message):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp}: {message}")

def init_gpio():
    global gpio_available
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHTS_PIN, GPIO.OUT, initial=GPIO.LOW)
        gpio_available = True
        log_message("GPIO initialized successfully.")
    except Exception as e:
        log_message(f"GPIO initialization failed: {e}. Running in simulation mode.")
        gpio_available = False

def cleanup_gpio():
    if gpio_available:
        try:
            GPIO.output(LIGHTS_PIN, GPIO.LOW)
            GPIO.cleanup()
            log_message("GPIO cleaned up.")
        except Exception as e:
            log_message(f"GPIO cleanup error: {e}")

def turn_lights_on():
    if gpio_available:
        try:
            GPIO.output(LIGHTS_PIN, GPIO.HIGH)
            log_message("Lights turned ON.")
        except Exception as e:
            log_message(f"Error turning lights on: {e}")
    else:
        log_message("(Simulated) Lights turned ON.")

def turn_lights_off():
    if gpio_available:
        try:
            GPIO.output(LIGHTS_PIN, GPIO.LOW)
            log_message("Lights turned OFF.")
        except Exception as e:
            log_message(f"Error turning lights off: {e}")
    else:
        log_message("(Simulated) Lights turned OFF.")

def read_temperature():
    if DHT_AVAILABLE and dht_device is not None:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                log_message(f"Temperature: {temperature:.1f}°C")
                return temperature
            else:
                log_message("DHT11 returned None temperature.")
        except RuntimeError as e:
            log_message(f"DHT11 read error (checksum/timeout): {e}")
        except Exception as e:
            log_message(f"Unexpected DHT11 error: {e}")
    log_message(f"Temperature: {random.uniform(15, 35):.1f}°C (simulated)")
    return random.uniform(15, 35)

def capture_image():
    global camera
    if Picamera2 is not None and camera is not None:
        try:
            camera.start()
            time.sleep(0.5)
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture(filename)
            camera.stop()
            log_message(f"Image captured: {filename}")
        except Exception as e:
            log_message(f"Error capturing image: {e}")
    else:
        log_message("(Simulated) Image captured.")

def signal_handler(sig, frame):
    log_message("Signal received, cleaning up...")
    cleanup_gpio()
    if camera is not None:
        try:
            camera.close()
        except Exception:
            pass
    sys.exit(0)

def main():
    global camera, dht_device
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_gpio()

    if Picamera2 is not None:
        try:
            camera = Picamera2()
            camera.configure(camera.create_still_configuration(main={"size": (640, 480)}))
            log_message("Camera initialized.")
        except Exception as e:
            log_message(f"Camera initialization failed: {e}. Running without camera.")
            camera = None
    else:
        log_message("Camera not available. Running without camera.")

    if DHT_AVAILABLE:
        try:
            dht_device = adafruit_dht.DHT11(board.D4)
            log_message("DHT11 sensor initialized.")
        except Exception as e:
            log_message(f"DHT11 initialization failed: {e}. Running with simulated temperature.")
            dht_device = None
    else:
        log_message("DHT11 not available. Running with simulated temperature.")

    if sr is not None:
        r = sr.Recognizer()
        try:
            with sr.Microphone() as source:
                print("Say 'Greenhouse' followed by a command...")
                r.adjust_for_ambient_noise(source, duration=0.5)
                audio = r.listen(source, timeout=5)
            try:
                text = r.recognize_google(audio)
                print(f"You said: {text}")
                command = text.lower()

                if WAKE_WORD in command:
                    command = command.replace(WAKE_WORD, "").strip()
                    if "turn on the lights" in command:
                        turn_lights_on()
                    elif "turn off the lights" in command:
                        turn_lights_off()
                    elif "what is the temperature" in command:
                        read_temperature()
                    elif "take a picture" in command:
                        capture_image()
                    else:
                        log_message("Unknown command.")
                else:
                    log_message("Wake word not detected.")
            except sr.UnknownValueError:
                log_message("Could not understand audio.")
            except sr.RequestError as e:
                log_message(f"Speech recognition service error: {e}")
        except sr.WaitTimeoutError:
            log_message("No speech detected within timeout.")
    else:
        log_message("Voice recognition not available. Simulating commands.")
        turn_lights_on()
        read_temperature()
        capture_image()

    cleanup_gpio()
    if camera is not None:
        try:
            camera.close()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

