import signal
import sys
import time

try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05  # seconds

# --- Globals for cleanup -----------------------------------------------------
_inputs = []
_outputs = []
_running = True


def _cleanup():
    """Close every gpiozero device we opened so the kernel releases the lines."""
    for dev in _inputs + _outputs:
        try:
            dev.close()
        except Exception:
            pass
    _inputs.clear()
    _outputs.clear()


def _handle_signal(signum, frame):
    """Flag the main loop to exit cleanly on SIGINT / SIGTERM."""
    global _running
    _running = False


def _init_gpio():
    """Create Button inputs with pull-up and OutputDevice outputs.

    Returns True on success, False on failure.
    """
    global _inputs, _outputs

    for pin in INPUT_PINS:
        try:
            dev = Button(pin, pull_up=True, bounce_time=None)
            _inputs.append(dev)
        except (GPIODeviceError, GPIOZeroError) as exc:
            print(f"Error: failed to initialize input GPIO {pin}: {exc}", file=sys.stderr)
            _cleanup()
            return False
        except Exception as exc:
            print(f"Unexpected error initializing input GPIO {pin}: {exc}", file=sys.stderr)
            _cleanup()
            return False

    for pin in OUTPUT_PINS:
        try:
            dev = OutputDevice(pin, active_high=True, initial_value=False)
            _outputs.append(dev)
        except (GPIODeviceError, GPIOZeroError) as exc:
            print(f"Error: failed to initialize output GPIO {pin}: {exc}", file=sys.stderr)
            _cleanup()
            return False
        except Exception as exc:
            print(f"Unexpected error initializing output GPIO {pin}: {exc}", file=sys.stderr)
            _cleanup()
            return False

    return True


def main():
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    if not _init_gpio():
        sys.exit(1)

    # State tracking for GPIO 24: True = HIGH, False = LOW
    output_24_state = False

    try:
        while _running:
            # GPIO 4 -> GPIO 23
            if _inputs[0].is_active:  # LOW when button pressed (pull-up + pull_up=True)
                _outputs[0].on()
            else:
                _outputs[0].off()

            # GPIO 5 -> GPIO 23
            if _inputs[1].is_active:
                _outputs[0].off()

            # GPIO 6 -> GPIO 24 (toggle on each new LOW transition)
            if _inputs[2].is_active:
                if not output_24_state:
                    _outputs[1].on()
                    output_24_state = True
            else:
                if output_24_state:
                    _outputs[1].off()
                    output_24_state = False

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

