import sys
import configparser
from picamera2 import Picamera2
from gpiozero import CPUTemperature

# Global state for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    print("\nShutdown signal received. Cleaning up...")
    running = False

def load_config(config_file="config.txt"):
    config = configparser.ConfigParser()
    try:
        config.read(config_file)
        return config
    except Exception as e:
        print(f"Error loading config file: {e}")
        return None

def detect_motion(frame1, frame2, motion_threshold):
    """Detect motion between two numpy arrays using a simple pixel difference metric."""
    if frame1 is None or frame2 is None:
        return False
    try:
        import numpy as np
        diff = np.abs(frame1.astype(np.int16) - frame2.astype(np.int16))
        changed_pixels = np.sum(diff > 10)
        total_pixels = frame1.shape[0] * frame1.shape[1]
        return (changed_pixels / total_pixels) * 100 > motion_threshold
    except Exception as e:
        print(f"Error in motion detection: {e}")
        return False

def send_alert(message):
    print(f"ALERT: {message}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config()
    if config is None:
        sys.exit(1)

    try:
        resolution_x = config.getint("camera", "resolution_x")
        resolution_y = config.getint("camera", "resolution_y")
        roi_x1 = config.getint("camera", "roi_x1")
        roi_y1 = config.getint("camera", "roi_y1")
        roi_x2 = config.getint("camera", "roi_x2")
        roi_y2 = config.getint("camera", "roi_y2")
        motion_threshold = config.getfloat("camera", "motion_threshold")
        confirmation_delay = config.getint("camera", "confirmation_delay")
        snapshot_dir = config.get("camera", "snapshot_dir")
        simulated_temperature = config.getboolean("temperature", "simulated_temperature")
        temperature_threshold = config.getfloat("temperature", "temperature_threshold")
    except (configparser.Error, ValueError) as e:
        print(f"Error parsing configuration: {e}")
        sys.exit(1)

    try:
        os.makedirs(snapshot_dir, exist_ok=True)
    except OSError as e:
        print(f"Error creating snapshot directory: {e}")
        sys.exit(1)

    # Initialize Picamera2
    try:
        picam2 = Picamera2()
        config_cam = picam2.create_preview_configuration(
            main={"format": 'RGB888', "size": (resolution_x, resolution_y)}
        )
        picam2.configure(config_cam)
        picam2.start()
        time.sleep(2)  # Allow camera to warm up
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

    # Initialize temperature sensor
    try:
        if simulated_temperature:
            cpu = CPUTemperature()
        else:
            cpu = CPUTemperature()
    except Exception as e:
        print(f"Error initializing temperature sensor: {e}")
        sys.exit(1)

    last_motion_time = None
    last_frame = None

    try:
        while running:
            try:
                # Capture frame
                frame = picam2.capture_array()
                if frame is None:
                    print("Warning: Captured empty frame")
                    time.sleep(0.1)
                    continue

                # Extract region of interest
                roi = frame[roi_y1:roi_y2, roi_x1:roi_x2]

                # Motion detection
                if last_frame is not None:
                    if detect_motion(last_frame, roi, motion_threshold):
                        if last_motion_time is None:
                            last_motion_time = time.time()
                        elif time.time() - last_motion_time > confirmation_delay:
                            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                            filename = os.path.join(snapshot_dir, f"motion_{timestamp}.jpg")
                            try:
                                picam2.capture_file(filename)
                                send_alert("Motion detected!")
                            except Exception as e:
                                print(f"Error saving snapshot: {e}")
                            last_motion_time = None

                last_frame = roi

                # Temperature monitoring
                if simulated_temperature:
                    temperature = 37.0
                else:
                    temperature = cpu.temperature

                if temperature > temperature_threshold:
                    send_alert("High temperature detected!")

                time.sleep(0.1)

            except Exception as e:
                print(f"Error in main loop: {e}")
                time.sleep(1)

    finally:
        print("Cleaning up resources...")
        try:
            picam2.stop()
            picam2.close()
        except Exception as e:
            print(f"Error closing camera: {e}")
        try:
            cpu.close()
        except Exception:
            pass
        print("Shutdown complete.")

if __name__ == "__main__":
    main()

