import serial
import sys
import signal

BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_bluetooth(port, baudrate):
    try:
        conn = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
            timeout=None,
        )
        if not conn.is_open:
            raise serial.SerialException(f"Port {port} did not open")
        print(f"Bluetooth connection established on {port} at {baudrate} baud.")
        return conn
    except serial.SerialException as e:
        print(f"Error initializing Bluetooth connection: {e}", file=sys.stderr)
        return None

def send_data(conn, data):
    try:
        payload = f"X{data}".encode("utf-8")
        bytes_written = conn.write(payload)
        conn.flush()
        print(f"Sent data ({bytes_written} bytes): {payload.decode('utf-8', errors='replace')}")
    except serial.SerialException as e:
        print(f"Error sending data: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bluetooth_connection = initialize_bluetooth(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)
    if bluetooth_connection is None:
        sys.exit(1)

    try:
        while _running:
            try:
                user_input = input("Enter data (or 'q' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == 'q':
                print("Quit signal received.")
                break

            if user_input:
                send_data(bluetooth_connection, user_input)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if bluetooth_connection is not None and bluetooth_connection.is_open:
            bluetooth_connection.close()
            print("Bluetooth connection closed.")

if __name__ == "__main__":
    main()

