"""
Manufacturing quality control: motion detection on a conveyor-belt camera feed.
Uses picamera2 for camera access, background subtraction for part counting,
and robust resource management.
"""

import signal
import sys
import time
import numpy as np
import cv2
from picamera2 import Picamera2


class ConveyorCounter:
    """Background-subtraction motion detector for conveyor-belt parts."""

    def __init__(self, learning_rate: float = 0.05, threshold: float = 8.0):
        self.background_model = None
        self.learning_rate = learning_rate
        self.threshold = threshold

    def update_background(self, frame_image: np.ndarray) -> None:
        """Update the running background model from a new camera frame."""
        if self.background_model is None:
            self.background_model = frame_image.astype("float32")
        else:
            self.background_model = (
                self.background_model * (1.0 - self.learning_rate)
                + frame_image.astype("float32") * self.learning_rate
            )

    def detect_motion(self, frame_image: np.ndarray) -> bool:
        """Return True when the ROI mean exceeds the threshold."""
        if self.background_model is None:
            return False
        roi = frame_image[
            frame_image.shape[0] // 3 : 2 * frame_image.shape[0] // 3, :
        ]
        mean_intensity = float(np.mean(roi))
        return mean_intensity > self.threshold


