import cv2
import os
import time
import signal
import sys
from picamera2 import Picamera2

# Constants
IMAGE_DIR = "images"
MAX_ATTEMPTS = 3
RETRY_DELAY = 1  # seconds
CASCADE_PATH = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera(attempt=1):
    """Initialize the camera with retry logic."""
    try:
        picam2 = Picamera2(camera_num=0)
        # Configure for a reasonable preview resolution
        config = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "BGR888"}
        )
        picam2.configure(config)
        picam2.start()
        # Allow a brief warm-up period for the sensor
        time.sleep(1)
        return picam2
    except Exception as e:
        if attempt < MAX_ATTEMPTS:
            print(f"Camera init attempt {attempt}/{MAX_ATTEMPTS} failed: {e}")
            time.sleep(RETRY_DELAY)
            return initialize_camera(attempt + 1)
        else:
            print(f"Camera initialization failed after {MAX_ATTEMPTS} attempts: {e}")
            return None

def capture_frame(picam2):
    """Capture a single frame from the camera."""
    try:
        return picam2.capture_array()
    except Exception as e:
        print(f"Frame capture failed: {e}")
        return None

def detect_faces(frame, face_cascade):
    """Detect faces in a frame using Haar cascades."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        return face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
    except Exception as e:
        print(f"Face detection failed: {e}")
        return []

def save_image(image, count, name):
    """Save a single image to disk."""
    filename = os.path.join(IMAGE_DIR, f"{name}_{count}.jpg")
    try:
        success = cv2.imwrite(filename, image)
        if success:
            print(f"Saved {filename}")
        else:
            print(f"cv2.imwrite returned False for {filename}")
    except Exception as e:
        print(f"Error saving image: {e}")

def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Create image directory if it doesn't exist
    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except OSError as e:
        print(f"Cannot create image directory '{IMAGE_DIR}': {e}")
        sys.exit(1)

    # Load Haar cascade classifier
    face_cascade = cv2.CascadeClassifier(CASCADE_PATH)
    if face_cascade.empty():
        print(f"Failed to load Haar cascade from {CASCADE_PATH}")
        sys.exit(1)

    # Get user's name
    name = input("What's your name? ").strip()
    if not name:
        print("Name cannot be empty.")
        sys.exit(1)

    # Initialize camera
    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    count = 0
    try:
        while _running and count < 5:
            frame = capture_frame(picam2)
            if frame is None:
                print("Failed to capture frame. Retrying...")
                time.sleep(0.5)
                continue

            faces = detect_faces(frame, face_cascade)

            for (x, y, w, h) in faces:
                cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)

            cv2.imshow("Face Detection", frame)
            key = cv2.waitKey(1) & 0xFF

            if key == ord('y'):
                if len(faces) > 0:
                    # Use the largest face as the crop region
                    (x, y, w, h) = max(faces, key=lambda f: f[2] * f[3])
                    cropped = frame[y:y + h, x:x + w]
                    save_image(cropped, count, name)
                    count += 1
                else:
                    print("No face detected. Cannot save image.")
            elif key == ord('q'):
                print("Exiting program.")
                break

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Clean up resources
        try:
            picam2.stop()
        except Exception:
            pass
        cv2.destroyAllWindows()
        print("Program finished.")

if __name__ == "__main__":
    main()

