import cv2
import pyzbar.pyzbar as pyzbar
import datetime
import csv
import os
import sys
import time

CAMERA_INDEX = 0
LOG_FILE = 'inventory_log.csv'
ERROR_LOG = 'error_log.txt'
CAPTURE_INTERVAL = 0.2


def log_error(message: str) -> None:
    """Append a timestamped error message to error_log.txt."""
    timestamp = datetime.datetime.now().isoformat(timespec='seconds')
    try:
        with open(ERROR_LOG, 'a', encoding='utf-8') as f:
            f.write(f"{timestamp} - {message}\n")
    except OSError as e:
        print(f"CRITICAL: Cannot write to error log: {e}", file=sys.stderr)


def init_camera(index: int) -> cv2.VideoCapture | None:
    """Open the USB camera at the given index; return None on failure."""
    cap = cv2.VideoCapture(index)
    if not cap.isOpened():
        log_error(f"Camera {index} did not open.")
        return None
    # Brief warm-up to let auto-exposure settle
    time.sleep(0.5)
    return cap


def decode_qr_code(frame: cv2.Mat) -> str | None:
    """Decode the first QR code in the frame; return decoded text or None."""
    try:
        decoded_objects = pyzbar.decode(frame)
    except Exception as e:
        log_error(f"pyzbar decode exception: {e}")
        return None
    if not decoded_objects:
        return None
    try:
        return decoded_objects[0].data.decode('utf-8')
    except Exception as e:
        log_error(f"Failed to decode QR data: {e}")
        return None


def validate_item_id(item_id: str) -> bool:
    """Return True if the string is a non-empty alphanumeric string."""
    if not item_id:
        return False
    if not item_id.isalnum():
        return False
    return True


def log_item(camera_id: str, item_id: str) -> None:
    """Append a timestamped record to inventory_log.csv."""
    capture_time = datetime.datetime.now().isoformat(timespec='seconds')
    try:
        with open(LOG_FILE, 'a', newline='', encoding='utf-8') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([camera_id, item_id, capture_time])
    except OSError as e:
        log_error(f"Failed to write to log file: {e}")


def main() -> None:
    camera = init_camera(CAMERA_INDEX)
    if camera is None:
        print("Camera initialization failed. Check error_log.txt.", file=sys.stderr)
        sys.exit(1)

    # Write header only if the file is empty
    if os.path.getsize(LOG_FILE) == 0:
        try:
            with open(LOG_FILE, 'a', newline='', encoding='utf-8') as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow(['camera_id', 'item_id', 'capture_time'])
        except OSError as e:
            log_error(f"Failed to write header to log file: {e}")

    try:
        while True:
            ret, frame = camera.read()
            if not ret:
                log_error("Failed to capture frame from camera.")
                time.sleep(CAPTURE_INTERVAL)
                continue

            item_id = decode_qr_code(frame)
            if item_id is not None and validate_item_id(item_id):
                log_item('Camera 1', item_id)
                print(f"Logged: Camera 1, Item ID: {item_id}")

            time.sleep(CAPTURE_INTERVAL)
    except KeyboardInterrupt:
        print("\nShutting down gracefully...")
    finally:
        if camera is not None:
            camera.release()
        cv2.destroyAllWindows()


if __name__ == '__main__':
    main()

