import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Thread-safe WebSocket broadcast dispatcher."""

    def __init__(self):
        self._connections: list = []
        self._lock = threading.Lock()

    def connect(self, connection_id: str) -> None:
        with self._lock:
            if connection_id not in self._connections:
                self._connections.append(connection_id)
                logger.info(f"Client connected: {connection_id}")

    def disconnect(self, connection_id: str) -> None:
        with self._lock:
            if connection_id in self._connections:
                self._connections.remove(connection_id)
                logger.info(f"Client disconnected: {connection_id}")

    def has_connections(self) -> bool:
        with self._lock:
            return bool(self._connections)

    def broadcast(self, data: bytes) -> None:
        with self._lock:
            connections = list(self._connections)
        for connection_id in connections:
            try:
                logger.debug(f"Broadcasting to {connection_id}")
            except Exception as e:
                logger.error(f"Error broadcasting to {connection_id}: {e}")


class CameraFeed:
    """Manages picamera2 capture and motion detection, broadcasting JPEG frames."""

    def __init__(
        self,
        detect_motion_function: Callable[[np.ndarray, np.ndarray], None],
        loop: Optional[object] = None,
    ):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.loop = loop
        self.camera: Optional[Picamera2] = None
        self.prev_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None
        self.frame_buffer = io.BytesIO()
        self.buffer_lock = threading.Lock()
        self.web_socket_handler = WebSocketHandler()
        self.running = False
        self.camera_thread: Optional[threading.Thread] = None

    def _init_camera(self) -> None:
        """Initialize and configure the picamera2 instance."""
        try:
            self.camera = Picamera2()
            config = self.camera.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                lores={"size": (320, 240), "format": "RGB888"},
                encode="lores",
            )
            self.camera.configure(config)
            self.camera.start()
            logger.info("Camera initialized successfully.")
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            self.camera = None
            raise

    def _capture_loop(self) -> None:
        """Background thread: capture JPEG frames and dispatch them."""
        if self.camera is None:
            logger.error("Camera not initialized in capture loop.")
            return

        try:
            while self.running:
                try:
                    request = self.camera.capture_request()
                    try:
                        lores_array = request.get_array("lores")
                        if lores_array is None:
                            logger.warning("Captured lores frame is None.")
                            continue

                        # Encode to JPEG bytes
                        ok, encoded = cv2.imencode(".jpg", lores_array)
                        if not ok:
                            logger.warning("JPEG encoding failed.")
                            continue

                        with self.buffer_lock:
                            self.frame_buffer.seek(0)
                            self.frame_buffer.truncate()
                            self.frame_buffer.write(encoded.tobytes())

                        with self.buffer_lock:
                            data = self.frame_buffer.getvalue()

                        if self.web_socket_handler.has_connections():
                            if self.loop:
                                self.loop.call_soon_threadsafe(
                                    self.web_socket_handler.broadcast, data
                                )
                            else:
                                self.web_socket_handler.broadcast(data)

                    finally:
                        request.release()
                except Exception as e:
                    logger.error(f"Error capturing frame: {e}")
                    time.sleep(0.1)
        finally:
            logger.info("Camera capture loop stopped.")

    def _detect_motion(self) -> None:
        """Background thread: compare consecutive frames for motion."""
        if self.camera is None:
            logger.error("Camera not initialized in motion detection.")
            return

        try:
            while self.running:
                try:
                    request = self.camera.capture_request()
                    try:
                        main_array = request.get_array("main")
                        if main_array is None:
                            logger.warning("Captured main frame is None.")
                            continue

                        with self.buffer_lock:
                            self.current_frame = main_array.copy()

                        if self.prev_frame is not None:
                            try:
                                self.detect_motion_function(self.prev_frame, self.current_frame)
                            except Exception as e:
                                logger.error(f"Error in motion detection callback: {e}")

                        with self.buffer_lock:
                            self.prev_frame = self.current_frame.copy()
                    finally:
                        request.release()
                except Exception as e:
                    logger.error(f"Error capturing frame for motion detection: {e}")
                    time.sleep(0.1)
        finally:
            logger.info("Motion detection loop stopped.")

    def start(self) -> None:
        """Start the camera and background threads."""
        if self.running:
            logger.warning("CameraFeed already running.")
            return

        self.running = True
        try:
            self._init_camera()
        except Exception:
            self.running = False
            return

        self.camera_thread = threading.Thread(target=self._capture_loop, daemon=True)
        motion_thread = threading.Thread(target=self._detect_motion, daemon=True)

        self.camera_thread.start()
        motion_thread.start()
        logger.info("CameraFeed started.")

    def stop(self) -> None:
        """Stop the camera and background threads."""
        if not self.running:
            logger.warning("CameraFeed not running.")
            return

        self.running = False
        if self.camera_thread and self.camera_thread.is_alive():
            self.camera_thread.join(timeout=5)
        if self.camera:
            try:
                self.camera.stop()
                logger.info("Camera stopped.")
            except Exception as e:
                logger.error(f"Error stopping camera: {e}")
        logger.info("CameraFeed stopped.")


def _signal_handler(signum, frame, camera_feed: Optional[CameraFeed] = None) -> None:
    logger.info(f"Signal {signum} received, shutting down.")
    if camera_feed:
        camera_feed.stop()


def main() -> None:
    camera_feed = CameraFeed(
        detect_motion_function=lambda prev, curr: None,
        loop=None,
    )

    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, camera_feed))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, camera_feed))

    camera_feed.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        camera_feed.stop()


if __name__ == "__main__":
    main()

