import sys
import time
import signal
import cv2
import pygame.mixer
from gpiozero import Button, OutputDevice
from picamera2 import Picamera2

import config
import face


class Door:
    """Controls a door lock via an active-high GPIO line."""

    def __init__(self, lock_pin=18, button_pin=17):
        self.lock = OutputDevice(lock_pin, active_high=True, initial_value=True)
        self.button = Button(button_pin, pull_up=True)
        self.is_locked = True

    def lock_door(self):
        self.lock.on()
        self.is_locked = True

    def unlock_door(self):
        self.lock.off()
        self.is_locked = False

    def is_button_up(self):
        return self.button.is_pressed

    def cleanup(self):
        self.lock.close()
        self.button.close()


def play_sound(sound, channel):
    if channel.get_busy():
        channel.stop()
    channel.play(sound)


def init_sounds(sounds):
    pygame.mixer.init(48000, -16, 1, 1024)
    channels = [pygame.mixer.Channel(i) for i in range(4)]
    return {name: (pygame.mixer.Sound(path), channels[i])
            for i, (name, path) in enumerate(sounds.items())}


def init_model():
    try:
        return cv2.face.EigenFaceRecognizer_create()
    except AttributeError:
        return cv2.face.EigenFaceRecognizer_create()
    except Exception as e:
        print(f"Error initializing face model: {e}", file=sys.stderr)
        return None


def init_camera():
    try:
        cam = Picamera2()
        cam.configure(cam.create_preview_configuration(
            main={"format": "RGB888", "size": (640, 480)}))
        cam.start()
        return cam
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None


def main():
    door = None
    model = None
    camera = None
    try:
        door = Door()
        door.lock_door()

        sounds = {
            "welcome": config.WELCOME_SOUND_PATH,
            "wait": config.WAIT_SOUND_PATH,
            "later": config.LATER_SOUND_PATH,
        }
        snds = init_sounds(sounds)
        if not snds:
            print("Error initializing sounds.", file=sys.stderr)
            return

        model = init_model()
        if model is None:
            print("Error initializing face model.", file=sys.stderr)
            return

        camera = init_camera()
        if camera is None:
            print("Error initializing camera.", file=sys.stderr)
            return

        print("Running...")
        print("Press button to trigger face recognition.")
        print("Press Ctrl-C to quit.")

        while True:
            if door.is_button_up():
                print("Button pressed, looking for face...")
                try:
                    if camera is not None:
                        frame = camera.capture_array()
                    else:
                        frame = face.get_image()

                    if frame is None:
                        print("Could not capture image.", file=sys.stderr)
                        play_sound(snds["later"][0], snds["later"][1])
                        time.sleep(1)
                        continue

                    gray = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
                    face_coords = face.detect_single(gray)

                    if face_coords is None:
                        print("No face detected.")
                        play_sound(snds["later"][0], snds["later"][1])
                        time.sleep(1)
                        continue

                    x, y, w, h = face_coords
                    cropped = face.crop(gray, x, y, w, h)
                    resized = face.resize(cropped)

                    label, confidence = model.predict(resized)
                    print(f"Predicted label: {label}, Confidence: {confidence}")

                    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                        print("Recognized face! Unlocking Door...")
                        door.unlock_door()
                        play_sound(snds["welcome"][0], snds["welcome"][1])
                    else:
                        print("Face not recognized.")
                        play_sound(snds["wait"][0], snds["wait"][1])

                except Exception as e:
                    print(f"Error during face recognition: {e}", file=sys.stderr)
                    play_sound(snds["later"][0], snds["later"][1])
                    time.sleep(1)
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        if door is not None:
            door.cleanup()
        if camera is not None:
            camera.stop()
        pygame.mixer.quit()


if __name__ == "__main__":
    main()

