IMAGE_FILENAME = "captured_image.jpg"
CAPTURE_COMMAND = "capture"
SAMPLE_RATE = 44100
CHUNK_SIZE = 1024

# Global state
running = True

def signal_handler(sig, frame):
    global running
    logging.info("Signal received, shutting down...")
    running = False

def cleanup_resources(camera=None, recognizer=None, lora_node=None, ser=None):
    logging.info("Cleaning up resources...")
    if camera:
        try:
            camera.stop()
            camera.close()
        except Exception as e:
            logging.error(f"Error closing camera: {e}")
    if recognizer:
        try:
            recognizer.stop_listening()
        except Exception as e:
            logging.error(f"Error stopping recognizer: {e}")
