        try:
            ser.close()
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")
    try:
        termios.tcsetattr(sys.stdin, termios.TCSADRAIN, old_settings)
    except Exception:
        pass

def initialize_lora_node(serial_port, frequency, address, power, air_speed):
