        time.sleep(0.1)
        ser.flush()
        logging.info("Serial port opened successfully.")
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
        return None

    try:
        lora_node = SX1262(ser, freq=frequency, addr=address, power=power, rssi=True, air_speed=air_speed, relay=False)
        logging.info("LoRa node initialized successfully.")
        return lora_node
    except Exception as e:
        logging.error(f"Failed to initialize LoRa node: {e}")
        if ser.is_open:
            ser.close()
        return None

