        picam2.configure(picam2.create_still_configuration(transform=Transform(vflip=True, hflip=True)))
        picam2.start()
        time.sleep(2)
        picam2.capture_file(image_path)
        picam2.stop()
        picam2.close()
        logging.info(f"Image captured and saved to: {image_path}")
        return True
    except Exception as e:
        logging.error(f"Failed to capture image: {e}")
        return False

