                logging.warning("Could not understand audio")
            except sr.RequestError as e:
                logging.error(f"Could not request results from Google Speech Recognition service; {e}")
            except Exception as e:
                logging.error(f"An unexpected error occurred during voice command processing: {e}")

        except sr.WaitTimeoutError:
            logging.warning("Listening timed out; no speech detected.")
        except Exception as e:
            logging.error(f"An unexpected error occurred in voice control loop: {e}")
            time.sleep(1)

def main():
    global old_settings
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        os.makedirs(DESKTOP_PATH, exist_ok=True)
    except OSError as e:
        logging.error(f"Failed to create directory {DESKTOP_PATH}: {e}")
        return

    try:
        old_settings = termios.tcgetattr(sys.stdin)
        tty.setcbreak(sys.stdin.fileno())
    except Exception as e:
        logging.error(f"Failed to set terminal settings: {e}")

    recognizer = sr.Recognizer()
    microphone = sr.Microphone(sample_rate=SAMPLE_RATE, chunk_size=CHUNK_SIZE)

    lora_node = initialize_lora_node(SERIAL_PORT, LORA_FREQUENCY, LORA_ADDRESS, LORA_POWER, LORA_AIR_SPEED)
    if not lora_node:
        logging.error("LoRa node initialization failed. Exiting.")
        cleanup_resources(camera=None, recognizer=recognizer, lora_node=None, ser=None)
        return

    camera = None
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration(transform=Transform(vflip=True, hflip=True)))
        camera.start()
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        cleanup_resources(camera=None, recognizer=recognizer, lora_node=lora_node, ser=None)
        return

    try:
        voice_control_loop(lora_node, recognizer, camera)
    except Exception as e:
        logging.error(f"Fatal error in main loop: {e}")
    finally:
        cleanup_resources(camera, recognizer, lora_node, None)

if __name__ == "__main__":
    main()

