import time
import threading
import signal
import sys
import os

try:
    import smbus2
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2")
    sys.exit(1)

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. This script must run on a Raspberry Pi.")
    sys.exit(1)

# --- Configuration ---
LED_PINS = [17, 18, 23, 27, 22]
I2C_BUS = 1
I2C_ADDR = 0x27
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
ENABLE = 0x04
BACKLIGHT = 0x08

# --- Globals ---
running = True
cpu_thread = None
lcd_thread = None

# --- Hardware Abstraction ---
class LCD:
    def __init__(self, bus_num, addr):
        self.bus = smbus2.SMBus(bus_num)
        self.addr = addr
        self._init_lcd()

    def _write_byte(self, byte):
        self.bus.write_byte(self.addr, byte)

    def _toggle_enable(self, bits):
        self._write_byte(bits | ENABLE)
        time.sleep(0.0005)
        self._write_byte(bits & ~ENABLE)
        time.sleep(0.0005)

    def _send_nibble(self, nibble):
        self._toggle_enable(nibble)

    def _send_byte(self, byte, mode):
        high = byte & 0xF0
        low = (byte << 4) & 0xF0
        self._send_nibble(high | mode)
        self._send_nibble(low | mode)

    def _init_lcd(self):
        self._write_byte(0x03 << 4)
        time.sleep(0.005)
        self._write_byte(0x03 << 4)
        time.sleep(0.001)
        self._write_byte(0x03 << 4)
        time.sleep(0.001)
        self._write_byte(0x02 << 4)
        time.sleep(0.001)
        self._send_byte(0x28, LCD_CMD)
        self._send_byte(0x0C, LCD_CMD)
        self._send_byte(0x06, LCD_CMD)
        self._send_byte(0x01, LCD_CMD)

    def display_string(self, message, line):
        message = message.ljust(LCD_WIDTH, " ")
        self._send_byte(line, LCD_CMD)
        for i in range(LCD_WIDTH):
            self._send_byte(ord(message[i]), LCD_CHR)

    def clear(self):
        self._send_byte(0x01, LCD_CMD)
        time.sleep(0.002)

    def close(self):
        try:
            self.clear()
        except Exception:
            pass
        try:
            self._write_byte(0x08 | BACKLIGHT)
        except Exception:
            pass
        try:
            self.bus.close()
        except Exception:
            pass

def get_cpu_temp():
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            return float(f.read().strip()) / 1000.0
    except Exception:
        return 0.0

def get_cpu_usage():
    try:
        with open("/proc/stat", "r") as f:
            lines = f.readlines()
        if len(lines) < 2:
            return 0.0
        cpu_stats = lines[0].split()
        if len(cpu_stats) < 9:
            return 0.0
        user, nice, system, idle, iowait, irq, softirq, steal = map(int, cpu_stats[1:8])
        total = user + nice + system + idle + iowait + irq + softirq + steal
        idle_time = idle + iowait
        if total == 0:
            return 0.0
        return max(0.0, 100.0 - (idle_time / total) * 100.0)
    except Exception:
        return 0.0

def display_cpu_usage(lcd):
    global running
    while running:
        try:
            cpu_usage = get_cpu_usage()
            cpu_temp = get_cpu_temp()
            lcd.display_string(f"CPU  : {cpu_usage:5.1f}%", LCD_LINE_1)
            lcd.display_string(f"Temp : {cpu_temp:5.1f}C", LCD_LINE_2)
        except Exception as e:
            print(f"Error displaying CPU usage: {e}")
        time.sleep(1)

def activate_led(cls):
    global running
    if not running:
        return
    if not 0 <= cls <= 4:
        print(f"Invalid class index: {cls}. Must be between 0 and 4.")
        return
    try:
        GPIO.output(LED_PINS[cls], GPIO.HIGH)
        time.sleep(1)
        GPIO.output(LED_PINS[cls], GPIO.LOW)
    except Exception as e:
        print(f"Error activating LED for class {cls}: {e}")

def signal_handler(sig, frame):
    global running, cpu_thread, lcd_thread
    print("\nCtrl+C pressed. Cleaning up...")
    running = False
    if cpu_thread and cpu_thread.is_alive():
        cpu_thread.join(timeout=2)
    if lcd_thread and lcd_thread.is_alive():
        lcd_thread.join(timeout=2)
    GPIO.cleanup()
    print("GPIO cleaned up. Exiting.")
    sys.exit(0)

def main():
    global running, cpu_thread, lcd_thread
    signal.signal(signal.SIGINT, signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in LED_PINS:
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

    try:
        lcd = LCD(I2C_BUS, I2C_ADDR)
    except Exception as e:
        print(f"Error initializing LCD: {e}")
        GPIO.cleanup()
        sys.exit(1)

    cpu_thread = threading.Thread(target=display_cpu_usage, args=(lcd,), daemon=True)
    cpu_thread.start()

    try:
        while running:
            cls = int(input("Enter class (0-4): "))
            activate_led(cls)
    except ValueError:
        print("Invalid input. Please enter an integer between 0 and 4.")
    except EOFError:
        pass
    finally:
        running = False
        if cpu_thread and cpu_thread.is_alive():
            cpu_thread.join(timeout=2)
        if lcd_thread and lcd_thread.is_alive():
            lcd_thread.join(timeout=2)
        lcd.close()
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

