    global running
    if not running:
        return
    if not 0 <= cls <= 4:
        print(f"Invalid class index: {cls}. Must be between 0 and 4.")
        return
    try:
        GPIO.output(LED_PINS[cls], GPIO.HIGH)
        time.sleep(1)
        GPIO.output(LED_PINS[cls], GPIO.LOW)
    except Exception as e:
        print(f"Error activating LED for class {cls}: {e}")

def signal_handler(sig, frame):
    global running, cpu_thread, lcd_thread
    print("\nCtrl+C pressed. Cleaning up...")
    running = False
    if cpu_thread and cpu_thread.is_alive():
        cpu_thread.join(timeout=2)
    if lcd_thread and lcd_thread.is_alive():
        lcd_thread.join(timeout=2)
    GPIO.cleanup()
    print("GPIO cleaned up. Exiting.")
    sys.exit(0)

def main():
    global running, cpu_thread, lcd_thread
    signal.signal(signal.SIGINT, signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in LED_PINS:
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

    try:
        lcd = LCD(I2C_BUS, I2C_ADDR)
    except Exception as e:
        print(f"Error initializing LCD: {e}")
        GPIO.cleanup()
        sys.exit(1)

    cpu_thread = threading.Thread(target=display_cpu_usage, args=(lcd,), daemon=True)
    cpu_thread.start()

    try:
        while running:
            cls = int(input("Enter class (0-4): "))
            activate_led(cls)
    except ValueError:
        print("Invalid input. Please enter an integer between 0 and 4.")
    except EOFError:
        pass
    finally:
        running = False
        if cpu_thread and cpu_thread.is_alive():
            cpu_thread.join(timeout=2)
        if lcd_thread and lcd_thread.is_alive():
            lcd_thread.join(timeout=2)
        lcd.close()
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

