"""
Reads CPU temperature from /sys/class/thermal/thermal_zone0/temp and prints it.
Uses smbus2 for I2C bus 1 access.  No OLED is written to.
"""

import time
import signal
import sys

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2")
    sys.exit(1)

# I2C address of an SSD1306 OLED commonly wired to bus 1 on the Raspberry Pi 5
OLED_ADDRESS = 0x3C

# Global bus handle so the signal handler can release it
_bus = None


def _cleanup(signum=None, frame=None):
    """Release the I2C bus on exit or signal."""
    global _bus
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None
    if signum is not None:
        sys.exit(0)


def read_cpu_temp():
    """Read CPU temperature in degrees Celsius from the thermal sysfs node."""
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            raw = f.read().strip()
        millideg = int(raw)
        return millideg / 1000.0
    except FileNotFoundError:
        print("Error: thermal sysfs node not found. Is this running on a Raspberry Pi?")
        raise
    except PermissionError:
        print("Error: permission denied reading thermal sysfs node. Run with appropriate privileges.")
        raise
    except (ValueError, OSError) as e:
        print(f"Error reading CPU temperature: {e}")
        raise


def main():
    global _bus

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Initialize I2C bus 1
    try:
        _bus = SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.")
        sys.exit(1)
    except PermissionError:
        print("Error: permission denied opening I2C bus 1. Run with appropriate privileges.")
        sys.exit(1)
    except OSError as e:
        print(f"Error initializing I2C bus 1: {e}")
        sys.exit(1)

    try:
        while True:
            try:
                temp_c = read_cpu_temp()
                print(f"CPU Temperature: {temp_c:.1f} °C")
            except Exception:
                # Transient read failure: log and continue
                pass
            time.sleep(2)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

