import time
import signal
import sys
import board
import busio
import adafruit_ssd1306
import adafruit_bme280
import adafruit_tsl2561

# Global resources for cleanup
i2c_bus = None
display = None
bme280 = None
tsl2561 = None
running = True


def cleanup():
    """Clear the display and release I2C resources."""
    global i2c_bus, display
    if display is not None:
        try:
            display.fill(0)
            display.show()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass


def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    running = False


def init_i2c():
    """Initialize the I2C bus on GPIO3 (SCL) and GPIO2 (SDA)."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return True
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False


def init_display():
    """Initialize the 128x64 SSD1306 OLED display at address 0x3C."""
    global display
    try:
        display = adafruit_ssd1306.SSD1306_I2C(128, 64, i2c_bus, addr=0x3C)
        display.fill(0)
        display.show()
        return True
    except Exception as e:
        print(f"Error initializing OLED display: {e}")
        return False


def init_bme280():
    """Initialize the BME280 sensor at address 0x76."""
    global bme280
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=0x76)
        return True
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return False


def init_tsl2561():
    """Initialize the TSL2561 sensor at address 0x39."""
    global tsl2561
    try:
        tsl2561 = adafruit_tsl2561.TSL2561(i2c_bus, address=0x39)
        return True
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return False


def read_sensor_data():
    """Read temperature, humidity, pressure, and light intensity.

    Returns:
        tuple: (temperature_c, humidity_pct, pressure_hpa, light_lux)
    """
    temp = hum = press = light = None

    if bme280 is not None:
        try:
            temp = bme280.temperature
            hum = bme280.humidity
            press = bme280.pressure
        except Exception as e:
            print(f"Error reading BME280: {e}")

    if tsl2561 is not None:
        try:
            light = tsl2561.lux
        except Exception as e:
            print(f"Error reading TSL2561: {e}")

    return temp, hum, press, light


def update_display(temp, hum, press, light):
    """Update the OLED display with sensor data."""
    if display is None:
        return
    try:
        display.fill(0)
        display.text(f"Temp: {temp:.1f} C", 0, 0, 1)
        display.text(f"Humidity: {hum:.1f} %", 0, 16, 1)
        display.text(f"Pressure: {press:.1f} hPa", 0, 32, 1)
        display.text(f"Light: {light:.1f} lux", 0, 48, 1)
        display.show()
    except Exception as e:
        print(f"Error updating display: {e}")


def main():
    """Main loop: read sensors and update display every 1 second."""
    global running

    signal.signal(signal.SIGINT, signal_handler)

    if not init_i2c():
        cleanup()
        sys.exit(1)

    if not init_display():
        cleanup()
        sys.exit(1)

    if not init_bme280():
        print("Warning: BME280 not found. Temperature/humidity/pressure will be None.")

    if not init_tsl2561():
        print("Warning: TSL2561 not found. Light intensity will be None.")

    print("Sensors initialized. Press Ctrl+C to exit.")

    while running:
        temp, hum, press, light = read_sensor_data()
        update_display(temp, hum, press, light)
        time.sleep(1)

    cleanup()
    print("Program terminated.")


if __name__ == "__main__":
    main()

