import sys
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

# Configuration
LCD_COLUMNS = 16
LCD_ROWS = 2
LCD_I2C_ADDR = 0x27
DHT_PIN = board.D4
UPDATE_INTERVAL = 2.0

# Global resources for cleanup
lcd = None
dht_device = None
i2c_bus = None
running = True


def cleanup():
    """Clear the LCD and release resources on exit."""
    global lcd, dht_device, i2c_bus
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None


def init_lcd(i2c_bus):
    """Initialize the I2C LCD; return the LCD object or None on failure."""
    try:
        return character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS, LCD_I2C_ADDR)
    except Exception as e:
        print(f"Error initializing LCD at 0x{LCD_I2C_ADDR:02X}: {e}", file=sys.stderr)
        return None


def init_dht22():
    """Initialize the DHT22 sensor; return the device object or None on failure."""
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Error initializing DHT22 on GPIO4: {e}", file=sys.stderr)
        return None


def read_dht22(device):
    """Read temperature and humidity from the DHT22.

    Returns (temperature, humidity) or (None, None) on error.
    DHT22 checksum errors and read failures are common; we handle them here.
    """
    try:
        temperature = device.temperature
        humidity = device.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 commonly throws RuntimeError on checksum or timing failures
        print(f"DHT22 read error (checksum/timing): {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}", file=sys.stderr)
        return None, None


def update_lcd(lcd_display, temperature, humidity):
    """Update the LCD with the latest temperature and humidity readings."""
    try:
        lcd_display.clear()
        lcd_display.set_cursor(0, 0)
        lcd_display.message = f"Temp: {temperature:.1f} C"
        lcd_display.set_cursor(0, 1)
        lcd_display.message = f"Humidity: {humidity:.1f}%"
    except Exception as e:
        print(f"Error updating LCD: {e}", file=sys.stderr)


def main():
    global lcd, dht_device, i2c_bus

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize I2C bus
    i2c_bus = init_i2c()
    if i2c_bus is None:
        sys.exit(1)

    # Initialize LCD
    lcd = init_lcd(i2c_bus)
    if lcd is None:
        cleanup()
        sys.exit(1)

    # Initialize DHT22 sensor
    dht_device = init_dht22()
    if dht_device is None:
        print("Warning: DHT22 sensor not detected. Continuing without temperature data.", file=sys.stderr)

    # Main loop
    try:
        while running:
            temperature, humidity = read_dht22(dht_device) if dht_device else (None, None)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f}%")
            else:
                print("Temperature/Humidity: [sensor read failed]")

            update_lcd(lcd, temperature if temperature is not None else 0.0,
                       humidity if humidity is not None else 0.0)

            # Sleep in small increments so signals are caught promptly
            elapsed = 0.0
            while running and elapsed < UPDATE_INTERVAL:
                time.sleep(0.1)
                elapsed += 0.1

    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

