import os
import time
import signal
import logging
from PIL import Image, ImageOps
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

I2C_ADDRESS = 0x3C
I2C_PORT = 1
FRAME_WIDTH = 128
FRAME_HEIGHT = 64

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received.")

def load_gif_files(folder):
    if not os.path.isdir(folder):
        logging.error(f"Folder not found: {folder}")
        return []
    return [os.path.join(folder, f) for f in os.listdir(folder) if f.lower().endswith('.gif')]

def display_gif(device, gif_file, loop_count=0):
    try:
        with Image.open(gif_file) as img:
            if getattr(img, 'n_frames', 1) == 1:
                logging.warning(f"{gif_file} is not an animated GIF.")
                return
            for frame_index in range(img.n_frames):
                if not running:
                    return
                img.seek(frame_index)
                frame = ImageOps.pad(img.convert('RGB'), (FRAME_WIDTH, FRAME_HEIGHT), method='constant', color=(0, 0, 0))
                duration = img.info.get('duration', 100)
                device.display(frame)
                time.sleep(duration / 1000.0)
    except FileNotFoundError:
        logging.error(f"File not found: {gif_file}")
    except (IOError, OSError) as e:
        logging.error(f"Error reading GIF file {gif_file}: {e}")
    except Exception as e:
        logging.error(f"Unexpected error displaying GIF {gif_file}: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    try:
        serial = i2c(port=I2C_PORT, address=I2C_ADDRESS)
        device = ssd1306(serial, width=FRAME_WIDTH, height=FRAME_HEIGHT)
    except Exception as e:
        logging.error(f"Failed to initialize I2C or SSD1306 display: {e}")
        return
    gif_files = load_gif_files('./gifs')
    if not gif_files:
        logging.warning("No GIF files found in ./gifs folder.")
        return
    try:
        while running:
            for gif_file in gif_files:
                if not running:
                    break
                logging.info(f"Displaying: {gif_file}")
                display_gif(device, gif_file)
    finally:
        try:
            device.cleanup()
        except Exception:
            pass
        logging.info("Display closed. Exiting.")

if __name__ == "__main__":
    main()

