import time
import sys
import board
import adafruit_dht

# DHT11 sensor on GPIO4 (BCM) = board.D4 (physical pin 7)
SENSOR_PIN = board.D4
MAX_RETRIES = 5
RETRY_DELAY = 2.0  # seconds between retries (DHT11 needs >= 1 s between reads)


def read_dht11():
    """Attempt to read temperature and humidity from the DHT11 sensor.

    Returns:
        tuple[float, float] on success, or None on failure.
    """
    try:
        sensor = adafruit_dht.DHT11(SENSOR_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Error: Failed to initialize DHT11 on GPIO4: {exc}")
        return None

    try:
        for attempt in range(1, MAX_RETRIES + 1):
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                if temperature is not None and humidity is not None:
                    return temperature, humidity

                print(f"Warning: DHT11 returned None on attempt {attempt}/{MAX_RETRIES}.")

            except RuntimeError as exc:
                # DHT11 checksum errors, timing glitches, or missing sensor
                # are common and retriable.
                print(f"Warning: DHT11 read error on attempt {attempt}/{MAX_RETRIES}: {exc}")

            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)

        print("Error: DHT11 sensor read failed after all retries.")
        return None

    finally:
        # Release the GPIO resource on every exit path.
        try:
            sensor.exit()
        except Exception:
            pass


def main():
    result = read_dht11()
    if result is not None:
        temperature, humidity = result
        print(f"Temperature: {temperature:.1f} C")
        sys.exit(0)
    else:
        print("Failed to read DHT11 sensor.")
        sys.exit(1)


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
        sys.exit(130)

