import time
import logging
import signal
import sys
from typing import Tuple, Optional

try:
    from smbus2 import SMBus
except ImportError:
    logging.error("smbus2 library not found. Install with: pip install smbus2")
    sys.exit(1)


class DHT20:
    """Driver for the Aosong DHT20 I2C temperature/humidity sensor."""

    I2C_BUS = 1
    I2C_ADDR = 0x38
    REG_STATUS = 0x71
    REG_MEASURE = 0xAC
    MEASURE_CMD = [0x33, 0x00]
    TEMPERATURE_COEFFICIENT = 5242.88
    HUMIDITY_COEFFICIENT = 1048576.0
    MAX_RETRIES = 5
    RETRY_DELAY = 2.0
    POWER_STABILIZE_DELAY = 0.5
    CRC_INIT = 0xFF
    CRC_POLY = 0x31
    CRC_TIMEOUT = 0.1

    def __init__(self, bus: int = I2C_BUS, address: int = I2C_ADDR) -> None:
        self.address = address
        self._bus: Optional[SMBus] = None
        try:
            self._bus = SMBus(bus)
        except FileNotFoundError:
            logging.error(f"I2C bus {bus} not found. Enable I2C and check /dev/i2c-{bus}.")
            raise
        except PermissionError:
            logging.error(f"Permission denied on /dev/i2c-{bus}. Run as root or add user to i2c group.")
            raise
        except OSError as e:
            logging.error(f"Failed to open I2C bus {bus}: {e}")
            raise

        time.sleep(self.POWER_STABILIZE_DELAY)

        if not self._verify_sensor():
            self.close()
            raise RuntimeError("DHT20 sensor not detected or communication failed.")

        logging.info(f"DHT20 initialized on bus {bus} at address 0x{address:02X}.")

    def _verify_sensor(self) -> bool:
        """Verify sensor presence by reading status and checking bits 3 and 4."""
        try:
            status = self._read_register(self.REG_STATUS, 1)[0]
            if (status & 0x18) != 0x18:
                logging.error(f"DHT20 status check failed: status byte 0x{status:02X} (expected bits 3 and 4 set).")
                return False
            return True
        except OSError as e:
            logging.error(f"I2C error reading status register: {e}")
            return False

    def _read_register(self, register: int, length: int) -> bytes:
        """Read `length` bytes starting at `register`."""
        if self._bus is None:
            raise RuntimeError("I2C bus is not open.")
        return self._bus.read_i2c_block_data(self.address, register, length)

    def _write_register(self, register: int, data: list) -> None:
        """Write `data` bytes to `register`."""
        if self._bus is None:
            raise RuntimeError("I2C bus is not open.")
        self._bus.write_i2c_block_data(self.address, register, data)

    @staticmethod
    def _calculate_crc8(data: bytes) -> int:
        """Calculate CRC8 with polynomial 0x31, init 0xFF."""
        crc = DHT20.CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20.CRC_POLY) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def get_temperature_and_humidity(self) -> Tuple[Optional[float], Optional[float], bool]:
        """
        Trigger a measurement and return (temperature, humidity, crc_error).

        Retries up to MAX_RETRIES times with RETRY_DELAY between attempts.
        """
        for attempt in range(1, self.MAX_RETRIES + 1):
            try:
                self._trigger_measurement()
                temperature, humidity, crc_error = self._read_measurement()
                if not crc_error:
                    return temperature, humidity, False
                logging.warning(f"CRC error on attempt {attempt}/{self.MAX_RETRIES}. Retrying...")
                if attempt < self.MAX_RETRIES:
                    time.sleep(self.RETRY_DELAY)
            except OSError as e:
                logging.error(f"I2C bus error on attempt {attempt}/{self.MAX_RETRIES}: {e}")
                if attempt < self.MAX_RETRIES:
                    time.sleep(self.RETRY_DELAY)

        logging.error(f"Failed to obtain valid data after {self.MAX_RETRIES} attempts.")
        return None, None, True

    def _trigger_measurement(self) -> None:
        """Send measurement command to DHT20."""
        self._write_register(self.REG_MEASURE, self.MEASURE_CMD)

    def _read_measurement(self) -> Tuple[Optional[float], Optional[float], bool]:
        """
        Read 7 bytes from register 0x71 and convert to (temperature, humidity, crc_error).

        Polls status register until bit 7 clears or CRC_TIMEOUT expires.
        """
        data = self._read_register(self.REG_STATUS, 7)
        if len(data) < 7:
            logging.error(f"Incomplete data read: got {len(data)} bytes, expected 7.")
            return None, None, True

        status = data[0]
        if status & 0x80:
            logging.warning("DHT20 busy bit set; measurement may be incomplete.")

        if (status & 0x01) == 0:
            logging.warning("DHT20 measurement not ready; status byte 0x%02X", status)
            return None, None, True

        raw_bytes = data[1:7]
        crc_error = self._calculate_crc8(raw_bytes) != data[6]
        if crc_error:
            logging.warning("CRC mismatch: calculated 0x%02X, received 0x%02X",
                            self._calculate_crc8(raw_bytes), data[6])
            return None, None, True

        # Humidity: 20-bit value spread across bytes 1-3
        humidity_raw = ((raw_bytes[1] << 12) | (raw_bytes[2] << 4) | (raw_bytes[3] >> 4)) & 0xFFFFF
        # Temperature: 20-bit value spread across bytes 3-5 (byte 3 shared)
        temp_raw = (((raw_bytes[3] & 0x0F) << 16) | (raw_bytes[4] << 8) | raw_bytes[5]) & 0xFFFFF

        temperature = float(temp_raw) / self.TEMPERATURE_COEFFICIENT - 50.0
        humidity = float(humidity_raw) / self.HUMIDITY_COEFFICIENT * 100.0

        return temperature, humidity, False

    def close(self) -> None:
        """Close the I2C bus."""
        if self._bus is not None:
            try:
                self._bus.close()
