import asyncio
import json
import logging
import logging.handlers
import signal
import sys
import time
from datetime import datetime

import RPi.GPIO as GPIO
import adafruit_dht
import board

CONFIG_FILE = "greenhouse_config.json"
DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"system_code": "10101", "unit_code": "1"},
        {"system_code": "10101", "unit_code": "2"},
        {"system_code": "10101", "unit_code": "3"},
    ],
}

_shutdown = asyncio.Event()


def _signal_handler(signum, frame):
    logging.info(f"Received signal {signum}; initiating shutdown.")
    _shutdown.set()


def _load_config(path):
    try:
        with open(path, "r") as f:
            cfg = json.load(f)
        if not isinstance(cfg, dict):
            raise ValueError("Config root must be an object.")
        return cfg
    except FileNotFoundError:
        logging.warning(f"Config file '{path}' not found; using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Config JSON parse error: {e}; using defaults.")
        return DEFAULT_CONFIG.copy()
    except Exception as e:
        logging.error(f"Unexpected config error: {e}; using defaults.")
        return DEFAULT_CONFIG.copy()


def _setup_logging(log_file):
    logger = logging.getLogger()
    logger.setLevel(logging.INFO)
    logger.handlers.clear()
    handler = logging.handlers.RotatingFileHandler(
        log_file, maxBytes=1024 * 1024, backupCount=5
    )
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    return logger


def _encode_code(system_code, unit_code, state):
    code = "10101"
    for ch in system_code:
        code += "0" if ch == '1' else "10101"
    for ch in unit_code:
        code += "0" if ch == '1' else "10101"
    code += "01010"
    for ch in state:
        code += "10101" if ch == '1' else "01010"
    code += "10101"
    return code


def _send_code(transmitter_pin, code, retries=3, delay=0.1):
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(transmitter_pin, GPIO.OUT, initial=GPIO.LOW)
    short = 0.0003
    long = short * 3
    for attempt in range(retries):
        try:
            for bit in code:
                if bit == '1':
                    GPIO.output(transmitter_pin, GPIO.HIGH)
                    time.sleep(long)
                    GPIO.output(transmitter_pin, GPIO.LOW)
                    time.sleep(short)
                else:
                    GPIO.output(transmitter_pin, GPIO.HIGH)
                    time.sleep(short)
                    GPIO.output(transmitter_pin, GPIO.LOW)
                    time.sleep(long)
            return True
        except Exception as e:
            logging.error(f"Transmit error (attempt {attempt + 1}/{retries}): {e}")
            if attempt < retries - 1:
                time.sleep(delay)
    return False


def transmit_code(system_code, unit_code, state, transmitter_pin):
    code = _encode_code(system_code, unit_code, state)
    return _send_code(transmitter_pin, code)


async def read_dht22(dht_device, pin, interval):
    while not _shutdown.is_set():
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                logging.info(f"DHT22 reading: {temperature:.1f}C, {humidity:.1f}%")
            else:
                logging.warning("DHT22 returned None; retrying next cycle.")
        except RuntimeError as e:
            logging.warning(f"DHT22 read error (transient): {e}")
        except OSError as e:
            logging.error(f"DHT22 bus error (sensor absent?): {e}")
        except Exception as e:
            logging.error(f"DHT22 unexpected error: {e}")
        try:
            await asyncio.wait_for(_shutdown.wait(), timeout=interval)
        except asyncio.TimeoutError:
            pass


async def handle_command(cmd, outlet_configs, dht_device, transmitter_pin):
    parts = cmd.split()
    if len(parts) < 2:
        print("Usage: on <outlet> | off <outlet> | status <outlet>")
        return
    action, outlet = parts[:2]
    if outlet not in (c["unit_code"] for c in outlet_configs):
        print(f"Unknown outlet: {outlet}")
        return
    cfg = next(c for c in outlet_configs if c["unit_code"] == outlet)
    system_code = cfg["system_code"]
    unit_code = cfg["unit_code"]
    if action == "on":
        state = "1"
    elif action == "off":
        state = "0"
    else:
        print("Usage: on <outlet> | off <outlet> | status <outlet>")
        return
    logging.info(f"Command: {action} {outlet} -> {system_code} {unit_code} {state}")
    if not _send_code(transmitter_pin, _encode_code(system_code, unit_code, state)):
        print(f"Failed to transmit {action} {outlet}.")
    else:
        print(f"{action} {outlet} sent.")


async def main():
    cfg = _load_config(CONFIG_FILE)
    log_file = cfg.get("log_file", DEFAULT_CONFIG["log_file"])
    logger = _setup_logging(log_file)
    logger.info("Greenhouse controller starting.")
    GPIO.setwarnings(False)
    GPIO.setmode(GPIO.BCM)
    transmitter_pin = cfg.get("gpio_transmitter_pin", DEFAULT_CONFIG["gpio_transmitter_pin"])
    dht_pin = cfg.get("gpio_dht22_pin", DEFAULT_CONFIG["gpio_dht22_pin"])
    interval = cfg.get("dht22_read_interval", DEFAULT_CONFIG["dht22_read_interval"])
    outlet_configs = cfg.get("outlet_configurations", DEFAULT_CONFIG["outlet_configurations"])
    if not outlet_configs:
        logger.error("No outlet_configurations in config.")
        return
    dht_device = None
    try:
        dht_device = adafruit_dht.DHT22(board.D4 if dht_pin == 4 else board.D17 if dht_pin == 17 else getattr(board, f"D{dht_pin}"))
    except Exception as e:
        logger.error(f"Failed to init DHT22 on BCM{dht_pin}: {e}")
    tasks = []
    if dht_device is not None:
        tasks.append(asyncio.create_task(read_dht22(dht_device, dht_pin, interval)))
    loop = asyncio.get_running_loop()
    stop_event = asyncio.Event()
    last_transmit = {}
    async def _handle_command_loop():
        while not stop_event.is_set():
            try:
                line = await asyncio.wait_for(loop.run_in_executor(None, input, ""), timeout=1.0)
                await handle_command(line.strip(), outlet_configs, dht_device, transmitter_pin)
            except asyncio.TimeoutError:
                pass
            except Exception as e:
                logging.error(f"Command loop error: {e}")
    tasks.append(asyncio.create_task(_handle_command_loop()))
    try:
        await _shutdown.wait()
    finally:
        stop_event.set()
        for t in tasks:
            t.cancel()
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass
        GPIO.cleanup()
        logging.info("Greenhouse controller stopped.")


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass
    finally:
        GPIO.cleanup()

