import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Fatal: Failed to initialize I2C bus: {e}")
    raise SystemExit(1)

# Initialize TCA9548A multiplexer at default address 0x70
try:
    i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=0x70)
except ValueError as e:
    print(f"Fatal: TCA9548A multiplexer not found at address 0x70: {e}")
    raise SystemExit(1)
except Exception as e:
    print(f"Fatal: Failed to initialize TCA9548A: {e}")
    raise SystemExit(1)

# Initialize BME280 sensor on multiplexer channel 0 (default address 0x76)
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_multiplexer[0], address=0x76)
except ValueError as e:
    print(f"Fatal: BME280 sensor not found on multiplexer channel 0: {e}")
    raise SystemExit(1)
except Exception as e:
    print(f"Fatal: Failed to initialize BME280: {e}")
    raise SystemExit(1)

# Initialize TSL2591 sensor on multiplexer channel 1 (default address 0x29)
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer[1], address=0x29)
except ValueError as e:
    print(f"Fatal: TSL2591 sensor not found on multiplexer channel 1: {e}")
