import time
import signal
import sys
import board
import adafruit_dht
import RPi.GPIO as GPIO

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4          # DHT11 data line on GPIO4 (BCM)
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22
PWM_FREQ = 100             # Hz
SAMPLE_INTERVAL = 1.0      # seconds
DHT_RETRY_DELAY = 2.0      # seconds between retries on read failure

# --- Globals for cleanup -----------------------------------------------------
_running = True
_pwm_red = None
_pwm_green = None
_pwm_blue = None
_dht = None

def _cleanup(signum=None, frame=None):
    """Release all hardware resources on exit."""
    global _running, _pwm_red, _pwm_green, _pwm_blue, _dht
    _running = False
    try:
        if _pwm_red is not None:
            _pwm_red.stop()
    except Exception:
        pass
    try:
        if _pwm_green is not None:
            _pwm_green.stop()
    except Exception:
        pass
    try:
        if _pwm_blue is not None:
            _pwm_blue.stop()
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if _dht is not None:
        try:
            _dht.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def _set_color(red_on, green_on, blue_on):
    """Drive PWM duty cycles for the requested color channels."""
    if _pwm_red is not None:
        _pwm_red.ChangeDutyCycle(100 if red_on else 0)
    if _pwm_green is not None:
        _pwm_green.ChangeDutyCycle(100 if green_on else 0)
    if _pwm_blue is not None:
        _pwm_blue.ChangeDutyCycle(100 if blue_on else 0)

def _read_temperature():
    """Return temperature in °C, or None on failure (with backoff)."""
    global _dht
    if _dht is None:
        return None
    for attempt in range(3):
        try:
            temp = _dht.temperature
            if temp is not None:
                return temp
        except RuntimeError as e:
            # DHT11 checksum / timing errors are common; retry
            print(f"DHT11 read error (attempt {attempt + 1}/3): {e}")
        except Exception as e:
            print(f"Unexpected DHT11 error: {e}")
            break
        time.sleep(DHT_RETRY_DELAY)
    return None

def main():
    global _pwm_red, _pwm_green, _pwm_blue, _dht

    # --- GPIO setup ----------------------------------------------------------
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in (RED_PIN, GREEN_PIN, BLUE_PIN):
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)

    _pwm_red = GPIO.PWM(RED_PIN, PWM_FREQ)
    _pwm_green = GPIO.PWM(GREEN_PIN, PWM_FREQ)
    _pwm_blue = GPIO.PWM(BLUE_PIN, PWM_FREQ)
    _pwm_red.start(0)
    _pwm_green.start(0)
    _pwm_blue.start(0)

    # --- DHT11 setup ---------------------------------------------------------
    try:
        _dht = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11: {e}")
        _cleanup()
        sys.exit(1)

    # --- Signal handlers -----------------------------------------------------
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    last_red = False
    last_green = False
    last_blue = False

    # --- Main loop -----------------------------------------------------------
    while _running:
        temp = _read_temperature()
        if temp is None:
            print("Temperature read failed; keeping last LED state.")
        else:
            print(f"Temperature: {temp:.1f} °C")
            if temp < 20:
                _set_color(False, False, True)   # Blue
            elif temp <= 25:
                _set_color(False, True, False)   # Green
            else:
                _set_color(True, False, False)   # Red
            last_red = temp > 25
            last_green = 20 <= temp <= 25
            last_blue = temp < 20

        time.sleep(SAMPLE_INTERVAL)

if __name__ == "__main__":
    main()

