#!/usr/bin/env python3
"""
Read and print the CPU temperature on a Raspberry Pi 4 Model B every 5 seconds.

Uses gpiozero.CPUTemperature (libgpiod-based) so that the kernel sysfs
thermal_zone0 file is opened lazily, allowing the program to start even when
the thermal sensor is not present (e.g., Pi Zero W or a mocked kernel).

Errors are reported per-read and do not crash the loop; Ctrl-C is caught so
the program exits cleanly with code 0.
"""

import time
import sys

try:
    from gpiozero import CPUTemperature
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


def read_cpu_temperature():
    """
    Read the CPU temperature from the thermal zone sysfs file.

    Returns:
        float: Temperature in degrees Celsius.

    Raises:
        FileNotFoundError: If the thermal zone file is missing.
        PermissionError: If the file cannot be read (e.g., permission denied).
        OSError: For any other I/O error reading the file.
        RuntimeError: If the sensor object is not initialized.
    """
    try:
        cpu = CPUTemperature()
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize CPUTemperature: {exc}") from exc

    if cpu is None:
        raise RuntimeError("CPUTemperature object is None")

    return cpu.temperature


def main():
    """Main loop: read and print CPU temperature every 5 seconds."""
    print("Starting CPU temperature monitoring...")
    while True:
        try:
            temperature = read_cpu_temperature()
            print(f"CPU Temperature: {temperature:.2f} °C")
        except FileNotFoundError as exc:
            print(f"Error: thermal zone file not found: {exc}")
        except PermissionError as exc:
            print(f"Error: permission denied reading thermal zone: {exc}")
        except OSError as exc:
            print(f"Error: I/O error reading thermal zone: {exc}")
        except RuntimeError as exc:
            print(f"Error: {exc}")
        except Exception as exc:
            print(f"An unexpected error occurred: {exc}")

        time.sleep(5)


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nProgram terminated")
        sys.exit(0)
    except Exception as exc:
        print(f"Fatal error: {exc}")
        sys.exit(1)

