import serial
import serial.tools.list_ports
import time
import csv
import sys
import os

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 5  # seconds
LOG_FILE = 'temperature_log.csv'


def open_serial_port():
    """Open the serial port with robust error handling."""
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        print("Hint: is the device connected and not already in use?", file=sys.stderr)
        return None


def ensure_log_header():
    """Write the CSV header row if the file does not already exist."""
    if not os.path.exists(LOG_FILE):
        try:
            with open(LOG_FILE, 'w', newline='') as fh:
                csv.writer(fh).writerow(['timestamp', 'celsius', 'fahrenheit'])
        except OSError as exc:
            print(f"Error: cannot initialise log file {LOG_FILE}: {exc}", file=sys.stderr)
            return False
    return True


def log_reading(timestamp, celsius, fahrenheit):
    """Append a single reading to the CSV log."""
    try:
        with open(LOG_FILE, 'a', newline='') as fh:
            csv.writer(fh).writerow([timestamp, f"{celsius:.2f}", f"{fahrenheit:.2f}"])
    except OSError as exc:
        print(f"Error: cannot write to log file {LOG_FILE}: {exc}", file=sys.stderr)


def main():
    if not ensure_log_header():
        sys.exit(1)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.")

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}", file=sys.stderr)
                break

            if not raw:
                # Timeout elapsed with no data
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                celsius = float(line)
            except ValueError:
                print(f"Warning: malformed data received: {line!r}", file=sys.stderr)
                continue

            fahrenheit = celsius * 9.0 / 5.0 + 32.0
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            log_reading(timestamp, celsius, fahrenheit)
            print(f"{timestamp}  {celsius:.2f}C / {fahrenheit:.2f}F")

    except KeyboardInterrupt:
        print("\nInterrupted by user. Exiting...")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == '__main__':
    main()

