import RPi.GPIO as GPIO
import time
import sys

DHT_PIN = 4
MAX_RETRIES = 3
RETRY_DELAY = 2
SUCCESS_DELAY = 5

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.OUT, initial=GPIO.HIGH)

def read_dht22():
    GPIO.output(DHT_PIN, GPIO.LOW)
    time.sleep(0.018)
    GPIO.output(DHT_PIN, GPIO.HIGH)
    time.sleep(0.00004)
    GPIO.setup(DHT_PIN, GPIO.IN)
    data = []
    for _ in range(5):
        bits = 0
        for _ in range(8):
            start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                if time.time() - start > 0.0001:
                    raise TimeoutError("Low timeout")
            start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() - start > 0.0001:
                    raise TimeoutError("High timeout")
            bits = (bits << 1) | (1 if time.time() - start > 0.00005 else 0)
        data.append(bits)
    if len(data) != 5:
        raise ValueError("Incomplete data")
    humidity_int = data[0]
    humidity_dec = data[1]
    temp_int = data[2]
    temp_dec = data[3]
    checksum = data[4]
    if (humidity_int + humidity_dec + temp_int + temp_dec) % 256 != checksum:
        raise ValueError("Checksum mismatch")
    return (temp_int + temp_dec / 10.0, humidity_int + humidity_dec / 10.0)

def cleanup():
    GPIO.cleanup()

def main():
    setup_gpio()
    try:
        while True:
            for attempt in range(1, MAX_RETRIES + 1):
                try:
                    temp, hum = read_dht22()
                    print(f"Temperature: {temp:.1f}°C, Humidity: {hum:.1f}%")
                    time.sleep(SUCCESS_DELAY)
                    break
                except Exception as e:
                    print(f"Attempt {attempt}/{MAX_RETRIES} failed: {e}")
                    if attempt < MAX_RETRIES:
                        time.sleep(RETRY_DELAY)
            else:
                print("Failed after 3 retries. Waiting 5 seconds before next attempt.")
                time.sleep(5)
    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

