import time
import datetime
import json
import logging
import random
import signal
import sys
import urllib.request
import urllib.error
import board
import adafruit_dht

CONFIG_FILE = "config.json"
LOG_FILE = "greenhouse.log"

DEFAULT_CONFIG = {
    "webhook_url": "http://example.com/webhook",
    "dht_pin": 4,
    "temperature_threshold": 30,
    "humidity_threshold": 80,
    "vent_fan_pin": 17,
    "water_pump_pin": 27,
    "heater_pin": 22,
    "moving_average_window": 5,
    "max_retries": 3,
    "retry_delay": [1, 3, 9],
    "sensor_failure_threshold": 3,
    "sensor_failure_pause": 300,
    "log_level": "INFO"
}

config = {}
dht_device = None
running = True
sensor_failure_count = 0
last_successful_read = None

logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def load_config():
    global config
    try:
        with open(CONFIG_FILE, "r") as f:
            config = json.load(f)
        logging.info("Configuration loaded from config.json")
    except FileNotFoundError:
        logging.warning("config.json not found. Using default configuration.")
        config = DEFAULT_CONFIG.copy()
    except json.JSONDecodeError:
        logging.error("Invalid JSON in config.json. Using default configuration.")
        config = DEFAULT_CONFIG.copy()

def simulate_sensor_data():
    temperature = round(random.uniform(20, 30), 1)
    humidity = round(random.uniform(60, 80), 1)
    return temperature, humidity

def read_dht22_sensor():
    global dht_device
    if dht_device is None:
        logging.error("DHT22 device not initialized.")
        return None, None
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            logging.warning("DHT22 returned None values.")
            return None, None
        return round(temperature, 1), round(humidity, 1)
    except RuntimeError as e:
        logging.warning(f"DHT22 read error (RuntimeError): {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected DHT22 error: {e}")
        return None, None

def validate_data(temperature, humidity):
    if not (-40 <= temperature <= 80):
        logging.warning(f"Temperature out of range: {temperature}°C")
        return False
    if not (0 <= humidity <= 100):
        logging.warning(f"Humidity out of range: {humidity}%")
        return False
    return True

def send_webhook(temperature, humidity, average_temperature, average_humidity):
    data = {
        "temperature": temperature,
        "humidity": humidity,
        "average_temperature": average_temperature,
        "average_humidity": average_humidity
    }
    json_data = json.dumps(data).encode('utf-8')
    for attempt in range(config["max_retries"]):
        try:
            req = urllib.request.Request(
                config["webhook_url"],
                data=json_data,
                headers={'Content-Type': 'application/json'},
                method='POST'
            )
            with urllib.request.urlopen(req, timeout=10) as response:
                if 200 <= response.status < 300:
                    logging.info("Webhook sent successfully.")
                    return
                else:
                    logging.error(f"Webhook failed with status code: {response.status}")
        except urllib.error.URLError as e:
            logging.error(f"Webhook URL error: {e}")
        except Exception as e:
            logging.error(f"Webhook error: {e}")
        if attempt < config["max_retries"] - 1:
            time.sleep(config["retry_delay"][attempt])
    logging.error("Webhook failed after all retries.")

def control_actuators(average_temperature, average_humidity):
    try:
        if average_temperature > config["temperature_threshold"]:
            logging.info("Activating vent fan.")
        else:
            logging.info("Deactivating vent fan.")
        if average_humidity < config["humidity_threshold"]:
            logging.info("Activating water pump.")
        else:
            logging.info("Deactivating water pump.")
        if average_temperature < 15:
            logging.info("Activating heater.")
        else:
            logging.info("Deactivating heater.")
    except Exception as e:
        logging.error(f"Actuator control error: {e}")

def signal_handler(sig, frame):
    global running
    logging.info(f"Received signal {sig}. Shutting down gracefully...")
    running = False

def cleanup():
    global dht_device
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
        dht_device = None
    logging.info("Cleanup complete.")

def main():
    global dht_device, running, sensor_failure_count, last_successful_read

    load_config()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dht_device = adafruit_dht.DHT22(board.D4)
        logging.info("DHT22 sensor initialized on GPIO4.")
    except Exception as e:
        logging.error(f"Failed to initialize DHT22 sensor: {e}")
        dht_device = None

    temperature_readings = []
    humidity_readings = []

    try:
        while running:
            if dht_device is None:
                temperature, humidity = simulate_sensor_data()
                logging.info(f"Simulated sensor data: Temperature={temperature}°C, Humidity={humidity}%")
            else:
                temperature, humidity = read_dht22_sensor()
                if temperature is not None and humidity is not None:
                    sensor_failure_count = 0
                    last_successful_read = datetime.datetime.now()
                else:
                    sensor_failure_count += 1
                    logging.warning(f"Sensor failure count: {sensor_failure_count}/{config['sensor_failure_threshold']}")
                    if sensor_failure_count >= config["sensor_failure_threshold"]:
                        logging.warning("Too many consecutive sensor failures. Pausing data acquisition.")
                        time.sleep(config["sensor_failure_pause"])
                        sensor_failure_count = 0
                    temperature, humidity = simulate_sensor_data()
                    logging.info(f"Simulated sensor data (sensor failure): Temperature={temperature}°C, Humidity={humidity}%")

            if temperature is not None and humidity is not None and validate_data(temperature, humidity):
                temperature_readings.append(temperature)
                humidity_readings.append(humidity)
                if len(temperature_readings) > config["moving_average_window"]:
                    temperature_readings.pop(0)
                    humidity_readings.pop(0)

                if len(temperature_readings) == config["moving_average_window"]:
                    average_temperature = sum(temperature_readings) / config["moving_average_window"]
                    average_humidity = sum(humidity_readings) / config["moving_average_window"]

                    logging.info(f"Average Temperature: {average_temperature:.1f}°C, Average Humidity: {average_humidity:.1f}%")

                    if average_temperature > config["temperature_threshold"] or average_humidity > config["humidity_threshold"]:
                        logging.warning("Threshold exceeded!")
                        send_webhook(temperature, humidity, average_temperature, average_humidity)
                        control_actuators(average_temperature, average_humidity)
            else:
                logging.warning("Invalid sensor data. Skipping average calculation.")

            time.sleep(60)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

