        return
    try:
        full_topic = f'homie/{config.homieclientid}/{topic}'
        info = mqtt_client.publish(full_topic, str(payload), qos=1)
        info.wait_for_publish(timeout=5)
    except Exception as e:
        print(f'MQTT publish error on {topic}: {e}')


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print('Connected to MQTT broker.')
    else:
        print(f'MQTT connection failed with reason code {reason_code}.')


def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f'Disconnected from MQTT broker (reason code {reason_code}).')


def setup_mqtt():
    global mqtt_client
    try:
        mqtt_client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
        )
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.will_set(
            f'homie/{config.homieclientid}/$state', 'lost',
            retain=config.mqttretainmessage, qos=1,
        )
        mqtt_client.connect(config.mqttbroker, config.mqttport, keepalive=30)
        mqtt_client.loop_start()
        time.sleep(1)
        if not mqtt_client.is_connected():
            raise RuntimeError('MQTT connection timed out.')
    except Exception as e:
        print(f'MQTT setup error: {e}')
        raise


def setup_dht22():
    global dht_device
    try:
        pin = getattr(board, f'D{config.dhtgpiopin}')
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        time.sleep(2)
    except Exception as e:
        print(f'DHT22 setup error: {e}')
        raise


def publish_homie_discovery():
    publish('$state', 'init')
    publish('$homie', '4.0')
    publish('$name', config.homieclientname)
    publish('$nodes', config.homienodes)
    publish(f'{config.homienodes}/$name', 'DHT22 Sensor')
    publish(f'{config.homienodes}/$properties', 'temperature,humidity')
    publish(f'{config.homienodes}/temperature/$name', 'Temperature')
    publish(f'{config.homienodes}/temperature/$unit', DEGREE_CELSIUS)
    publish(f'{config.homienodes}/temperature/$datatype', 'float')
    publish(f'{config.homienodes}/temperature/$settable', 'false')
    publish(f'{config.homienodes}/humidity/$name', 'Humidity')
    publish(f'{config.homienodes}/humidity/$unit', '%')
    publish(f'{config.homienodes}/humidity/$datatype', 'float')
    publish(f'{config.homienodes}/humidity/$settable', 'false')
    publish('$state', 'ready')


def read_dht22():
    if dht_device is None:
        return None, None
    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            print(f'DHT22 read error (attempt {attempt + 1}/3): {e}')
        except Exception as e:
            print(f'Unexpected DHT22 error (attempt {attempt + 1}/3): {e}')
        time.sleep(2)
    return None, None


def cleanup():
    global dht_device, mqtt_client
    print('Cleaning up resources...')
    if mqtt_client is not None:
        try:
            publish('$state', 'lost')
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    print('Cleanup complete.')


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        setup_dht22()
        setup_mqtt()
        publish_homie_discovery()
        while running:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                print(f'Temperature = {temperature:.1f} {DEGREE_CELSIUS}')
                print(f'Humidity = {humidity:.1f} %')
                publish(f'{config.homienodes}/temperature', f'{temperature:.1f}')
                publish(f'{config.homienodes}/humidity', f'{humidity:.1f}')
            else:
                print('Failed to read DHT22 after retries.')
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f'Fatal error: {e}')
    finally:
        cleanup()


if __name__ == '__main__':
    main()

