    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.StreamHandler(),
        logging.FileHandler('wildlife_monitoring.log')
    ]
)

# GPIO pin assignments (BCM numbering)
DHT22_PIN_1 = board.D4
DHT22_PIN_2 = board.D17

# Anomaly thresholds
TEMPERATURE_THRESHOLD_HIGH = 35.0
TEMPERATURE_THRESHOLD_LOW = 5.0
HUMIDITY_THRESHOLD_HIGH = 90.0

# Retry settings
MAX_RETRIES = 3
RETRY_DELAY = 2  # seconds

# Global sensor objects
dht22_1 = None
dht22_2 = None


def read_dht22(pin, sensor_name):
    """Read temperature and humidity from a DHT22 sensor with retries.

    Args:
        pin: A board pin object (e.g., board.D4).
        sensor_name: Human-readable name for logging.

    Returns:
        (temperature, humidity) as floats, or (None, None) on failure.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = adafruit_dht.DHT22(pin).temperature
            humidity = adafruit_dht.DHT22(pin).humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logging.error(
                    f"{sensor_name} returned None values (attempt {attempt}/{MAX_RETRIES})"
                )
        except RuntimeError as e:
            logging.error(
                f"{sensor_name} read error (attempt {attempt}/{MAX_RETRIES}): {e}"
            )
        except Exception as e:
            logging.error(
                f"{sensor_name} unexpected error (attempt {attempt}/{MAX_RETRIES}): {e}"
            )
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)
    logging.error(f"{sensor_name} failed after {MAX_RETRIES} attempts.")
    return None, None


def check_anomalies(sensor_name, temperature, humidity, pin):
    """Log anomalies to console and file."""
    timestamp = datetime.datetime.now().isoformat()
    if temperature is not None and temperature > TEMPERATURE_THRESHOLD_HIGH:
        logging.error(
            f"{sensor_name} Anomaly: Temperature {temperature:.1f}°C exceeds "
            f"{TEMPERATURE_THRESHOLD_HIGH}°C at pin {pin} at {timestamp}"
        )
    if temperature is not None and temperature < TEMPERATURE_THRESHOLD_LOW:
        logging.error(
            f"{sensor_name} Anomaly: Temperature {temperature:.1f}°C below "
            f"{TEMPERATURE_THRESHOLD_LOW}°C at pin {pin} at {timestamp}"
        )
    if humidity is not None and humidity > HUMIDITY_THRESHOLD_HIGH:
        logging.error(
            f"{sensor_name} Anomaly: Humidity {humidity:.1f}% exceeds "
            f"{HUMIDITY_THRESHOLD_HIGH}% at pin {pin} at {timestamp}"
        )


def cleanup():
    """Release GPIO resources."""
    global dht22_1, dht22_2
    if dht22_1 is not None:
        try:
            dht22_1.exit()
        except Exception:
            pass
        dht22_1 = None
    if dht22_2 is not None:
        try:
            dht22_2.exit()
        except Exception:
            pass
        dht22_2 = None


def main():
    """Main monitoring loop."""
    global dht22_1, dht22_2

    # Initialize sensors
    try:
        dht22_1 = adafruit_dht.DHT22(DHT22_PIN_1)
    except Exception as e:
        logging.error(f"Failed to initialize DHT22 on pin D4: {e}")
        dht22_1 = None

    try:
        dht22_2 = adafruit_dht.DHT22(DHT22_PIN_2)
    except Exception as e:
        logging.error(f"Failed to initialize DHT22 on pin D17: {e}")
        dht22_2 = None

    try:
        while True:
            # Read sensor 1
            if dht22_1 is not None:
                temp1, hum1 = read_dht22(DHT22_PIN_1, "Sensor 1 (DHT22 on D4)")
                check_anomalies("Sensor 1", temp1, hum1, 4)
            else:
                logging.error("Sensor 1 (DHT22 on D4) not initialized; skipping.")

            # Read sensor 2
            if dht22_2 is not None:
                temp2, hum2 = read_dht22(DHT22_PIN_2, "Sensor 2 (DHT22 on D17)")
                check_anomalies("Sensor 2", temp2, hum2, 17)
            else:
                logging.error("Sensor 2 (DHT22 on D17) not initialized; skipping.")

            time.sleep(60)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

