# aht20_production_rpi.py
# Production-ready AHT20 temperature/humidity reader for Raspberry Pi 5.
# Uses adafruit_ahtx0 (CircuitPython) on I2C (board.SCL / board.SDA, address 0x38).
# Retries on missing sensor, I2C errors, and mid-run disconnection.
# Exit cleanly on KeyboardInterrupt.

import time
import board
import busio
import adafruit_ahtx0

I2C_ADDR = 0x38
RETRY_DELAY = 5  # seconds between retries
READ_INTERVAL = 5  # seconds between readings


def init_sensor():
    """Initialize I2C bus and AHT20 sensor. Returns (i2c, sensor) or (None, None)."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus: {exc}")
        return None, None

    # Probe for device presence before constructing the driver.
    try:
        while not i2c.try_lock():
            pass
        try:
            found = I2C_ADDR in i2c.scan()
        finally:
            i2c.unlock()
    except Exception as exc:
        print(f"[ERROR] I2C scan failed: {exc}")
        i2c.deinit()
        return None, None

    if not found:
        print(f"[ERROR] AHT20 not found at 0x{I2C_ADDR:02X}. Retrying in {RETRY_DELAY}s...")
        i2c.deinit()
        return None, None

    try:
        sensor = adafruit_ahtx0.AHTx0(i2c, address=I2C_ADDR)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize AHT20 sensor: {exc}")
        i2c.deinit()
        return None, None

    return i2c, sensor


def read_sensor(sensor):
    """Trigger a measurement and return (temperature, humidity) or (None, None)."""
    try:
        sensor.measure()
    except OSError as exc:
        print(f"[ERROR] I2C bus error during measurement: {exc}")
        return None, None
    except Exception as exc:
        print(f"[ERROR] Unexpected error during measurement: {exc}")
        return None, None

    temperature = sensor.temperature
    humidity = sensor.relative_humidity

    if temperature is None or humidity is None:
        print("[ERROR] Sensor returned None for temperature or humidity.")
        return None, None

    if not (-40.0 <= temperature <= 85.0):
        print(f"[ERROR] Temperature out of range: {temperature} C")
        return None, None

    if not (0.0 <= humidity <= 100.0):
        print(f"[ERROR] Humidity out of range: {humidity} %")
        return None, None

    return temperature, humidity


def main():
    i2c = None
    sensor = None

    while True:
        if sensor is None:
            i2c, sensor = init_sensor()
            if sensor is None:
                time.sleep(RETRY_DELAY)
                continue

        temperature, humidity = read_sensor(sensor)

        if temperature is not None and humidity is not None:
            ts = time.strftime("%Y-%m-%d %H:%M:%S")
            print(f"{ts} Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")

        time.sleep(READ_INTERVAL)


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\n[INFO] Shutdown requested by user.")
    finally:
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass

