import signal
import sys
import time

import serial
import board
import adafruit_dht

# Configuration
SERIAL_PORT = "/dev/ttyS0"
BAUD_RATE = 9600
READ_INTERVAL_SECONDS = 1
DHT_PIN = board.D4

# Global handles for cleanup
_serial_port = None
_dht_sensor = None
_running = True


def _cleanup():
    """Release hardware resources on exit."""
    global _serial_port, _dht_sensor
    if _dht_sensor is not None:
        try:
            _dht_sensor.exit()
        except Exception:
            pass
        _dht_sensor = None
    if _serial_port is not None:
        try:
            _serial_port.close()
        except Exception:
            pass
        _serial_port = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_serial():
    """Open the serial port; return the Serial object or None on failure."""
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        return None


def _init_dht():
    """Initialize the DHT22 sensor; return the sensor object or None on failure."""
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Error initializing DHT22 on GPIO4: {e}", file=sys.stderr)
        return None


def _read_temperature(sensor):
    """Read temperature from the DHT22; return float or None on failure."""
    try:
        return sensor.temperature
    except RuntimeError as e:
        # DHT sensors frequently throw RuntimeError on transient read failures
        print(f"DHT read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected DHT error: {e}", file=sys.stderr)
        return None


def _send_temperature(serial_port, temperature):
    """Send a temperature reading over UART; return True on success."""
    payload = f"Temperature: {temperature:.2f}C\n".encode("utf-8")
    try:
        bytes_written = serial_port.write(payload)
        serial_port.flush()
        if bytes_written == len(payload):
            print(f"Transmitted: {payload.decode('utf-8').strip()}")
            return True
        print(f"Incomplete write: {bytes_written}/{len(payload)} bytes", file=sys.stderr)
        return False
    except serial.SerialException as e:
        print(f"Serial write error: {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Unexpected send error: {e}", file=sys.stderr)
        return False


def main():
    """Main loop: read temperature every 1 s and transmit it over UART."""
    global _serial_port, _dht_sensor

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _serial_port = _init_serial()
    if _serial_port is None:
        print("Failed to initialize serial port. Exiting.", file=sys.stderr)
        sys.exit(1)

    _dht_sensor = _init_dht()
    if _dht_sensor is None:
        print("Failed to initialize DHT22 sensor. Exiting.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            temperature = _read_temperature(_dht_sensor)
            if temperature is not None:
                _send_temperature(_serial_port, temperature)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        _cleanup()
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

