import time
import signal
import sys
from smbus2 import SMBus

I2C_BUS = 1
I2C_ADDR = 0x38

running = True

def signal_handler(sig, frame):
    global running
    running = False

def crc8(data: bytes, init: int = 0xFF, poly: int = 0x31) -> int:
    crc = init
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ poly) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def init_sensor(bus: SMBus):
    try:
        bus.write_i2c_block_data(I2C_ADDR, 0xBA, [])
        time.sleep(0.02)
        status = bus.read_byte_data(I2C_ADDR, 0x71)
        if not (status & 0x08):
            bus.write_i2c_block_data(I2C_ADDR, 0xBE, [0x08, 0x00])
            time.sleep(0.01)
        return True
    except IOError:
        return False

def read_sensor(bus: SMBus):
    try:
        bus.write_i2c_block_data(I2C_ADDR, 0xAC, [0x33, 0x00])
        time.sleep(0.08)
        data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 7)
        if len(data) != 7:
            return None
        status = data[0]
        if status & 0x80:
            return None
        if crc8(data[:6]) != data[6]:
            return None
        raw_temp = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        raw_hum = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
        temp_c = (raw_temp / 0x100000) * 200.0 - 50.0
        humidity = (raw_hum / 0x100000) * 100.0
        temp_f = temp_c * 9.0 / 5.0 + 32.0
        return temp_c, temp_f, humidity
    except IOError:
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    try:
        bus = SMBus(I2C_BUS)
    except IOError as e:
        print(f"Error: Cannot open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)
    try:
        if not init_sensor(bus):
            print("Error: AHT20/DHT20 not detected or failed init.")
            sys.exit(1)
        print("AHT20/DHT20 initialised successfully.")
        while running:
            result = read_sensor(bus)
            if result is None:
                print("Warning: Sensor read failed (busy, CRC, or I/O error).")
            else:
                temp_c, temp_f, humidity = result
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                print(f"[{timestamp}] Temperature: {temp_c:.2f}°C / {temp_f:.2f}°F, Humidity: {humidity:.2f}%")
            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

