import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
ALERT_PIN = 17
TEMP_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
LOG_FILE = '/home/pi/sensor_log.txt'
ALERT_DURATION = 5

running = True
serial_port = None

def log_message(message):
    timestamp = datetime.now().isoformat(timespec='seconds')
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f"{timestamp} - {message}\n")
    except OSError as e:
        print(f"Log write error: {e}", file=sys.stderr)

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global serial_port
    if serial_port is not None and serial_port.is_open:
        try:
            serial_port.close()
            log_message("Serial port closed.")
        except Exception as e:
            log_message(f"Error closing serial port: {e}")
    try:
        GPIO.cleanup()
        log_message("GPIO cleaned up.")
    except Exception as e:
        log_message(f"Error cleaning GPIO: {e}")

def main():
    global serial_port
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(ALERT_PIN, GPIO.OUT, initial=GPIO.LOW)
        log_message("GPIO initialized.")
    except Exception as e:
        print(f"GPIO init error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        log_message(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        log_message(f"Failed to open serial port: {e}")
        print(f"Serial port error: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                raw = serial_port.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                parts = line.split(',')
                if len(parts) != 2:
                    log_message(f"Malformed line (expected 2 fields): {line!r}")
                    continue
                try:
                    temperature = float(parts[0])
                    humidity = float(parts[1])
                except ValueError:
                    log_message(f"Non-numeric data: {line!r}")
                    continue
                log_message(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                    log_message("ALERT: Threshold exceeded!")
                    try:
                        GPIO.output(ALERT_PIN, GPIO.HIGH)
                        time.sleep(ALERT_DURATION)
                        GPIO.output(ALERT_PIN, GPIO.LOW)
                    except Exception as e:
                        log_message(f"GPIO output error: {e}")
            except serial.SerialException as e:
                log_message(f"Serial read error: {e}")
                time.sleep(1)
            except OSError as e:
                log_message(f"I/O error: {e}")
                time.sleep(1)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

