import time
import signal
import sys
import numpy as np
import matplotlib.pyplot as plt

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1.0
FRAME_ROWS = 24
FRAME_COLS = 32
EXPECTED_VALUES = FRAME_ROWS * FRAME_COLS
REFRESH_INTERVAL = 0.1

running = True

def signal_handler(signum, frame):
    global running
    running = False

def open_serial_port(port, baud, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout
        )
        if not ser.is_open:
            print(f"Error: serial port {port} did not open.")
            return None
        print(f"Serial port {port} opened at {baud} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening {port}: {e}")
        return None

def read_thermal_frame(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        tokens = [t.strip() for t in line.split(',')]
        if len(tokens) != EXPECTED_VALUES:
            print(f"Warning: expected {EXPECTED_VALUES} values, got {len(tokens)}.")
            return None
        values = []
        for t in tokens:
            try:
                values.append(int(t))
            except ValueError:
                print(f"Warning: non-integer token '{t}'.")
                return None
        return np.array(values, dtype=np.int16).reshape((FRAME_ROWS, FRAME_COLS))
    except serial.SerialException as e:
        print(f"Serial I/O error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}")
        return None

def display_thermal_map(frame):
    try:
        plt.clf()
        plt.imshow(frame, cmap='inferno', interpolation='nearest')
        plt.colorbar(label='Temperature (°C)')
        plt.pause(REFRESH_INTERVAL)
    except Exception as e:
        print(f"Display update error: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = open_serial_port(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if ser is None:
        print("Failed to initialize serial communication. Exiting.")
        sys.exit(1)

    plt.ion()
    plt.figure('Thermal Camera Feed')
    plt.title('Thermal Camera - Live Feed')
    plt.axis('off')

    last_frame = None

    try:
        while running:
            frame = read_thermal_frame(ser)
            if frame is not None:
                last_frame = frame
            if last_frame is not None:
                display_thermal_map(last_frame)
            time.sleep(REFRESH_INTERVAL)
    except Exception as e:
        print(f"Fatal error in main loop: {e}")
    finally:
        print("Cleaning up resources...")
        try:
            if ser and ser.is_open:
                ser.close()
                print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
        try:
            plt.ioff()
            plt.close('all')
            print("Matplotlib closed.")
        except Exception as e:
            print(f"Error closing matplotlib: {e}")
        print("Program terminated.")

if __name__ == '__main__':
    main()

