from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 100
TEMP_THRESHOLD = 40.0
LOW_POWER_DUTY = 0.20
HIGH_POWER_DUTY = 1.0
READ_INTERVAL = 5

fan = None
running = True


def cleanup(signum=None, frame=None):
    global running, fan
    running = False
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global fan
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    while running:
        try:
            cpu_temp = float(open('/sys/class/thermal/thermal_zone0/temp').read().strip()) / 1000.0
        except (OSError, ValueError) as e:
            print(f"Temperature read failed: {e}", file=sys.stderr)
            time.sleep(READ_INTERVAL)
            continue

        if cpu_temp > TEMP_THRESHOLD:
            fan.value = HIGH_POWER_DUTY
        else:
            fan.value = LOW_POWER_DUTY

        time.sleep(READ_INTERVAL)

    cleanup()


