SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_sensor_data(data):
    if not data:
        return None, None
    parts = data.split(',')
    if len(parts) != 2:
        return None, None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
    except ValueError:
        return None, None
    return temperature, humidity

def check_thresholds(temperature, humidity):
    if temperature > TEMP_THRESHOLD:
        print(f"Alert: Temperature {temperature:.1f}C exceeds threshold {TEMP_THRESHOLD}C")
    if humidity > HUMIDITY_THRESHOLD:
        print(f"Alert: Humidity {humidity:.1f}% exceeds threshold {HUMIDITY_THRESHOLD}%")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud. Press Ctrl+C to stop.")

        while _running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                temperature, humidity = parse_sensor_data(line)
                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
                    check_thresholds(temperature, humidity)
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
            except ValueError as e:
                print(f"Data format error: {e}")

            time.sleep(READ_INTERVAL)

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

