import RPi.GPIO as GPIO
import time
import sys

LED_PIN = 17

def cleanup_gpio():
    """Ensure the LED pin is driven low and released."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    led_state = False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except (RuntimeError, ValueError) as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on' or 'off': ").strip().lower()
            except EOFError:
                print("\nEnd of input received.")
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
            else:
                print("Invalid input")

            print(f"LED is now: {led_state}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

