import time
import signal
import sys
from gpiozero import InputDevice
from gpiozero.exc import GPIOZeroError

REED_SWITCH_PIN = 22
POLL_INTERVAL_S = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        # pull_up=True  -> internal pull-up enabled (idle HIGH)
        # active_state=None -> let gpiozero auto-detect the active level.
        # For a normally-closed switch wired to GND, the pin reads LOW when
        # the door is closed and HIGH when open.
        reed = InputDevice(REED_SWITCH_PIN, pull_up=True, active_state=None)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO{REED_SWITCH_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error initializing GPIO{REED_SWITCH_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                # .is_active is True when the pin reads HIGH (door open)
                if reed.is_active:
                    print("Door Open")
                else:
                    print("Door Closed")
            except GPIOZeroError as exc:
                print(f"GPIO read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Unexpected error during read: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL_S)
    finally:
        try:
            reed.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

