import requests
from gpiozero import MotionSensor, LED

PIR_PIN = 17
LED_PIN = 18
SERVER_URL = 'http://127.0.0.1:5000/led'
POLL_INTERVAL = 1.0

running = True

def handle_sigint(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_sigint)

    try:
        pir = MotionSensor(PIR_PIN)
        led = LED(LED_PIN)
    except Exception as e:
        print(f'Failed to initialize GPIO: {e}')
        return

    print('Monitoring PIR on GPIO17, LED on GPIO18. Press Ctrl+C to exit.')

    try:
        while running:
            if pir.motion_detected:
                led.on()
                try:
                    requests.post(SERVER_URL, json={'led': 'on'}, timeout=5)
                except requests.exceptions.RequestException as e:
                    print(f'Error sending LED ON: {e}')
            else:
                led.off()
                try:
                    requests.post(SERVER_URL, json={'led': 'off'}, timeout=5)
                except requests.exceptions.RequestException as e:
                    print(f'Error sending LED OFF: {e}')
            time.sleep(POLL_INTERVAL)
    finally:
        led.close()
        pir.close()
        print('GPIO cleanup done.')

if __name__ == '__main__':
    main()

