import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# GPIO pins (BCM numbering) for the three digital input sensors
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL_S = 1.0

# Global list of DigitalInputDevice objects for cleanup
_devices = []
_running = True


def _cleanup():
    """Close every open GPIO device to release resources."""
    for dev in _devices:
        try:
            dev.close()
        except DeviceClosed:
            pass
        except Exception as exc:
            print(f"Warning: error closing GPIO device: {exc}", file=sys.stderr)
    _devices.clear()


def _handle_signal(signum, frame):
    """Set the running flag to False on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize each sensor with pull-up enabled (active-high idle)
    for pin in SENSOR_PINS:
        try:
            dev = DigitalInputDevice(pin, pull_up=True, bounce_time=None)
            _devices.append(dev)
        except GPIOZeroError as exc:
            print(f"Error: failed to initialize GPIO{pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)
        except Exception as exc:
            print(f"Unexpected error initializing GPIO{pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    print(f"Monitoring GPIO pins {SENSOR_PINS} every {POLL_INTERVAL_S}s (Ctrl+C to exit)")

    try:
        while _running:
            for idx, pin in enumerate(SENSOR_PINS, start=1):
                try:
                    dev = _devices[idx - 1]
                    if dev.is_active:
                        print(f"Response for sensor {idx}")
                except DeviceClosed:
                    print(f"Error: GPIO{pin} device closed unexpectedly", file=sys.stderr)
                except Exception as exc:
                    print(f"Error reading GPIO{pin}: {exc}", file=sys.stderr)
            time.sleep(POLL_INTERVAL_S)
    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

