import sys
import time
import threading
import signal
import RPi.GPIO as GPIO

# Assuming this is a module that handles DOG protocol (e.g., sending/receiving data)
import my_dog as DOG

# Constants
DEFAULT_FILENAME = "data.log"
RECEIVE_INTERVAL = 0.1  # seconds

# Global state
server_state = {
    "is_running": False,
    "log_file_path": DEFAULT_FILENAME,
    "receive_thread": None,
    "lock": threading.Lock()
}

def signal_handler(sig, frame):
    """Handles SIGINT/SIGTERM for clean shutdown."""
    print("\nSignal received, shutting down...")
    stop_server()
    GPIO.cleanup()
    sys.exit(0)

def start_server(filename=DEFAULT_FILENAME):
    """Starts the data logging server."""
    global server_state
    with server_state["lock"]:
        if server_state["is_running"]:
            print("Server is already running.")
            return

        try:
            # Initialize GPIO (if not already done)
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)

            server_state["log_file_path"] = filename
            server_state["is_running"] = True

            # Start the receive thread
            server_state["receive_thread"] = threading.Thread(
                target=receive_data, daemon=True
            )
            server_state["receive_thread"].start()

            print(f"Server started. Logging to: {filename}")

        except Exception as e:
            print(f"Error starting server: {e}")
            server_state["is_running"] = False

def stop_server():
    """Stops the data logging server."""
    global server_state
    with server_state["lock"]:
        server_state["is_running"] = False

        if server_state["receive_thread"] and server_state["receive_thread"].is_alive():
            server_state["receive_thread"].join(timeout=2.0)
            if server_state["receive_thread"].is_alive():
                print("Warning: Receive thread did not stop gracefully.")

        print("Server stopped.")

def receive_data():
    """Continuously receives data and logs it to a file."""
    while server_state["is_running"]:
        try:
            # Receive data using DOG protocol
            data = DOG.receive()
            if data:
                with open(server_state["log_file_path"], "a") as f:
                    f.write(data + "\n")
        except Exception as e:
            print(f"Error receiving data: {e}")
            time.sleep(0.1)
        time.sleep(RECEIVE_INTERVAL)

def send_data(data):
    """Sends data using DOG protocol."""
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_to_log(data):
    """Writes data directly to the log file."""
    try:
        with open(server_state["log_file_path"], "a") as f:
            f.write(data + "\n")
        print(f"Written to log: {data}")
    except Exception as e:
        print(f"Error writing to log: {e}")

def display_log():
    """Displays the contents of the log file."""
    try:
        with open(server_state["log_file_path"], "r") as f:
            print(f.read())
    except FileNotFoundError:
        print(f"Log file not found: {server_state['log_file_path']}")
    except Exception as e:
        print(f"Error displaying log: {e}")

def help_command(command=None):
    """Displays help information for commands."""
    if command:
        commands = {
            "help": "Displays help information.",
            "start": "Starts the server.",
            "stop": "Stops the server.",
            "send": "Sends data using DOG protocol.",
            "write": "Writes data directly to the log file.",
            "display": "Displays the contents of the log file.",
            "exit": "Exits the server."
        }
        if command in commands:
            print(commands[command])
        else:
            print(f"No help found for command: {command}")
    else:
        print("Available commands: help, start, stop, send, write, display, exit")

def main():
    """Main function to run the server."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    while True:
        try:
            command = input("JAYES@ROVER53:\t").strip()
            if not command:
                continue

            parts = command.split()
            if not parts:
                continue

            if parts[0] == "help":
                help_command(parts[1] if len(parts) > 1 else None)
            elif parts[0] == "start":
                start_server(parts[1] if len(parts) > 1 else DEFAULT_FILENAME)
            elif parts[0] == "stop":
                stop_server()
            elif parts[0] == "send":
                send_data(" ".join(parts[1:]))
            elif parts[0] == "write":
                write_to_log(" ".join(parts[1:]))
            elif parts[0] == "display":
                display_log()
            elif parts[0] == "exit":
                stop_server()
                GPIO.cleanup()
                break
            else:
                print("Unknown command. Try 'help'")

        except EOFError:
            print("\nEOF received, exiting.")
            stop_server()
            GPIO.cleanup()
            break
        except Exception as e:
            print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

