import asyncio
import json
import logging
import os
import signal
import sys
import time
from pathlib import Path

import sounddevice as sd
from gpiozero import LED
import psutil
import aiohttp
import tflite_runtime.interpreter as tflite

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sampling_rate": 16000,
    "audio_buffer_size": 1024,
    "positive_threshold": 0.5,
    "negative_threshold": 0.5,
    "cloud_endpoint": "http://localhost:5000/api/v1/data",
    "cloud_interval": 60,
    "log_level": "INFO",
    "log_file": "assistant.log",
    "led_pin": 17,
    "config_check_interval": 300,
    "system_monitoring_interval": 60,
    "keywords": ["hello", "bye", "thanks", "what's up"],
    "model_path": "model.tflite"
}

class ConfigManager:
    def __init__(self, config_file=CONFIG_FILE):
        self.config_file = config_file
        self.config = DEFAULT_CONFIG.copy()
        self.load_config()

    def load_config(self):
        try:
            with open(self.config_file, "r") as f:
                loaded = json.load(f)
                self.config.update(loaded)
            logging.info("Configuration loaded successfully.")
        except FileNotFoundError:
            logging.warning("Configuration file not found. Using default configuration.")
        except json.JSONDecodeError:
            logging.error("Error decoding JSON from configuration file. Using default configuration.")
        except Exception as e:
            logging.error(f"Error loading configuration: {e}. Using default configuration.")

    def get(self, key, default=None):
        return self.config.get(key, default)

class AudioProcessor:
    def __init__(self, config_manager):
        self.config = config_manager
        self.sampling_rate = self.config.get("sampling_rate")
        self.audio_buffer_size = self.config.get("audio_buffer_size")
        self.model_path = self.config.get("model_path")
        self.interpreter = None
        self.input_details = None
        self.output_details = None
        self.load_model()

    def load_model(self):
        try:
            self.interpreter = tflite.Interpreter(model_path=self.model_path)
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            logging.info("TFLite model loaded successfully.")
        except Exception as e:
            logging.error(f"Error loading TFLite model: {e}")
            self.interpreter = None

    def preprocess_audio(self, audio_data):
        try:
            import numpy as np
            audio_data = np.frombuffer(audio_data, dtype=np.int16)
            return audio_data / 32768.0
        except Exception as e:
            logging.error(f"Error preprocessing audio: {e}")
            return None

    def run_inference(self, audio_data):
        if not self.interpreter:
            return None
        try:
            import numpy as np
            input_data = self.preprocess_audio(audio_data)
            if input_data is None:
                return None
            input_data = np.expand_dims(input_data, axis=0)
            self.interpreter.set_tensor(self.input_details[0]['index'], input_data)
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(self.output_details[0]['index'])
            return output_data[0]
        except Exception as e:
            logging.error(f"Error running inference: {e}")
            return None

class VoiceActivityDetector:
    def __init__(self, config_manager):
        self.config = config_manager
        self.positive_threshold = self.config.get("positive_threshold")
        self.negative_threshold = self.config.get("negative_threshold")
        self.running_average = 0.0
        self.sample_count = 0

    def update_running_average(self, sentiment_score):
        self.sample_count += 1
        if self.sample_count == 0:
            self.running_average = sentiment_score
        else:
            self.running_average = (self.running_average * (self.sample_count - 1) + sentiment_score) / self.sample_count

    def check_thresholds(self):
        if self.running_average > self.positive_threshold:
            logging.info("Positive sentiment detected!")
            return "positive"
        elif self.running_average < self.negative_threshold:
            logging.info("Negative sentiment detected!")
            return "negative"
        else:
            return "neutral"

