class SystemMonitor:
    def __init__(self, config_manager):
        self.config = config_manager
        self.system_monitoring_interval = self.config.get("system_monitoring_interval")

    async def monitor_system(self):
        while True:
            try:
                cpu_percent = psutil.cpu_percent(interval=None)
                memory_percent = psutil.virtual_memory().percent
                disk_usage = psutil.disk_usage("/").percent
                logging.info(f"CPU: {cpu_percent}%, Memory: {memory_percent}%, Disk: {disk_usage}%")
            except Exception as e:
                logging.error(f"Error monitoring system: {e}")
            await asyncio.sleep(self.system_monitoring_interval)

class RemoteConfigurationManager:
    def __init__(self, config_manager):
        self.config = config_manager
        self.config_check_interval = self.config.get("config_check_interval")

    async def check_for_updates(self):
        while True:
            try:
                async with aiohttp.ClientSession() as session:
                    async with session.get("http://localhost:5000/api/v1/config") as response:
                        if response.status == 200:
                            config_data = await response.json()
                            logging.info("Received remote configuration.")
                            # Update config manager with new config
            except Exception as e:
                logging.error(f"Error checking for remote configuration: {e}")
            await asyncio.sleep(self.config_check_interval)

async def main():
    config_manager = ConfigManager()
    logging.basicConfig(filename=config_manager.get("log_file"), level=config_manager.get("log_level"), format='%(asctime)s - %(levelname)s - %(message)s')
    logging.info("Starting voice assistant...")

    audio_processor = AudioProcessor(config_manager)
    voice_activity_detector = VoiceActivityDetector(config_manager)
    cloud_service = CloudService(config_manager)
    led_controller = LEDController(config_manager)
    system_monitor = SystemMonitor(config_manager)
    remote_config_manager = RemoteConfigurationManager(config_manager)

    stop_event = asyncio.Event()

    def signal_handler():
        logging.info("Shutdown signal received.")
        stop_event.set()

    loop = asyncio.get_running_loop()
    for sig in (signal.SIGINT, signal.SIGTERM):
        loop.add_signal_handler(sig, signal_handler)

    async def audio_capture_task():
        try:
            while not stop_event.is_set():
                try:
                    audio_data = sd.rec(audio_processor.audio_buffer_size, samplerate=audio_processor.sampling_rate, channels=1, dtype='int16')
                    sd.wait()
                    sentiment_score = audio_processor.run_inference(audio_data)
                    if sentiment_score is not None:
                        sentiment_category = voice_activity_detector.check_thresholds()
                        if sentiment_category == "positive":
                            led_controller.activate()
                        elif sentiment_category == "negative":
                            led_controller.deactivate()
                        voice_activity_detector.update_running_average(sentiment_score)
                        await cloud_service.send_data({"sentiment_score": sentiment_score, "sentiment_category": sentiment_category})
                except sd.PortAudioError as e:
                    logging.error(f"Audio device error: {e}")
                    await asyncio.sleep(1)
                except Exception as e:
                    logging.error(f"Error in audio capture task: {e}")
                    await asyncio.sleep(1)
                await asyncio.sleep(0.1)
        except asyncio.CancelledError:
            logging.info("Audio capture task cancelled.")

    async def cloud_task():
        while not stop_event.is_set():
            try:
                await cloud_service.send_data({"cpu_usage": psutil.cpu_percent(interval=None)})
            except Exception as e:
                logging.error(f"Error sending heartbeat to cloud: {e}")
            await asyncio.sleep(config_manager.get("cloud_interval"))

    async def remote_config_task():
        while not stop_event.is_set():
            await remote_config_manager.check_for_updates()

    async def system_monitor_task():
        await system_monitor.monitor_system()

    tasks = [
        asyncio.create_task(audio_capture_task()),
        asyncio.create_task(cloud_task()),
        asyncio.create_task(remote_config_task()),
        asyncio.create_task(system_monitor_task())
    ]

    try:
        await stop_event.wait()
    except asyncio.CancelledError:
        pass
    finally:
        logging.info("Cancelling tasks...")
        for task in tasks:
            task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        logging.info("Cleaning up resources...")
        led_controller.cleanup()
        await cloud_service.close()
        logging.info("Shutdown complete.")

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        logging.info("Exiting...")

