import signal
import sys
import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

LED_PIN = 18
PWM_FREQ = 1000
MIN_LUX = 0.0
MAX_LUX = 1000.0
LOOP_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def lux_to_brightness(lux):
    if lux <= MIN_LUX:
        return 0.0
    if lux >= MAX_LUX:
        return 100.0
    return (lux / MAX_LUX) * 100.0

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c = None
    pwm = None

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Fatal: I2C bus initialization failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        sensor = adafruit_tsl2561.TSL2561(i2c, address=0x39)
        sensor.gain = adafruit_tsl2561.GAIN_AUTO
        sensor.integration_time = adafruit_tsl2561.INTEGRATIONTIME_402MS
    except Exception as e:
        print(f"Fatal: TSL2561 not detected at 0x39: {e}", file=sys.stderr)
        try:
            i2c.deinit()
        except Exception:
            pass
        sys.exit(1)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT)
        pwm = GPIO.PWM(LED_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception as e:
        print(f"Fatal: PWM setup failed on GPIO {LED_PIN}: {e}", file=sys.stderr)
        try:
            i2c.deinit()
        except Exception:
            pass
        sys.exit(1)

    try:
        while _running:
            try:
                lux = sensor.lux
            except Exception as e:
                print(f"Warning: I2C read error: {e}", file=sys.stderr)
                time.sleep(LOOP_INTERVAL)
                continue

            if lux is None:
                print("Warning: sensor returned None (saturation/overflow)", file=sys.stderr)
                time.sleep(LOOP_INTERVAL)
                continue

            brightness = lux_to_brightness(lux)
            try:
                pwm.ChangeDutyCycle(brightness)
            except Exception as e:
                print(f"Warning: PWM update failed: {e}", file=sys.stderr)

