                print(f"Warning: PWM update failed: {e}", file=sys.stderr)

            print(f"Lux: {lux:.2f}, Brightness: {brightness:.1f}%")
            time.sleep(LOOP_INTERVAL)

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        try:
            GPIO.cleanup()
        except Exception:
            pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("Cleanup complete.")

if __name__ == "__main__":
    main()

