    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_IR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_IR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)


def read_sensors():
    """Read both IR sensors and return their digital states (0 or 1).
    Returns (left_state, right_state) or raises RuntimeError on failure."""
    try:
        left_state = GPIO.input(LEFT_IR_PIN)
        right_state = GPIO.input(RIGHT_IR_PIN)
        return left_state, right_state
    except Exception as e:
        raise RuntimeError(f"Sensor read error: {e}")


def decide_direction(left_state, right_state):
    """Decide steering direction based on sensor states.
    Black line (0,0) -> forward, white surface (1,1) -> search,
    one sensor on line (0,1) or (1,0) -> turn in that direction."""
    if left_state == 0 and right_state == 0:
        return "forward"
    if left_state == 1 and right_state == 1:
        return "search"
    if left_state == 0:
        return "turn-left"
    if right_state == 0:
        return "turn-right"
    # Should not happen, but keep it explicit
    return "search"


