import signal
import sys
import time
from gpiozero import DigitalOutputDevice, DigitalInputDevice

# Constants for GPIO pins (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Constants for signaling
START_SIGNAL = "START"
END_SIGNAL = "END"

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def char_to_bits(char):
    """Converts a character to a 7-bit binary string."""
    try:
        ascii_value = ord(char)
        binary_string = bin(ascii_value)[2:].zfill(7)
        return binary_string
    except TypeError:
        raise ValueError("Input must be a single character.")


def bits_to_char(binary_string):
    """Converts a 7-bit binary string to a character."""
    if len(binary_string) != 7:
        raise ValueError("Binary string must be exactly 7 bits long.")
    try:
        ascii_value = int(binary_string, 2)
        return chr(ascii_value)
    except ValueError:
        raise ValueError("Invalid binary string.")


def send_data(data_string):
    """Sends a string of data over the GPIO pins."""
    data_out = None
    timer_out = None
    try:
        data_out = DigitalOutputDevice(DATA_OUT_PIN)
        timer_out = DigitalOutputDevice(TIMER_OUT_PIN)

        # Format the data to send
        data_to_send = START_SIGNAL + data_string + END_SIGNAL

        # Send each bit of the data
        for bit in data_to_send:
            if not _running:
                break
            if bit == '0':
                data_out.off()
            else:
                data_out.on()
            timer_out.on()
            time.sleep(0.0005)
            timer_out.off()

    except Exception as e:
        print(f"Error sending data: {e}", file=sys.stderr)
    finally:
        if data_out is not None:
            data_out.close()
        if timer_out is not None:
            timer_out.close()


def receive_data():
    """Receives data from the GPIO pins."""
    data_in = None
    timer_in = None
    try:
        data_in = DigitalInputDevice(DATA_IN_PIN)
        timer_in = DigitalInputDevice(TIMER_IN_PIN)

        received_data = ""
        current_bit = ""
        start_signal_received = False

        # Timeout for reception
        timeout_start = time.time()

        while _running:
            if time.time() - timeout_start > 1:
                print("Reception timeout.", file=sys.stderr)
                break

            # Wait for timer signal
            while timer_in.value == 1:
                if not _running:
                    break
                pass

            # Read data bit
            bit_value = 1 if data_in.value else 0
            current_bit += str(bit_value)

            if len(current_bit) == 7:
                if current_bit == bin(ord(START_SIGNAL[0]))[2:].zfill(7):
                    start_signal_received = True
                elif start_signal_received:
                    try:
                        received_data += bits_to_char(current_bit)
                    except ValueError:
                        pass  # Ignore invalid bits

                current_bit = ""

        return received_data

    except Exception as e:
        print(f"Error receiving data: {e}", file=sys.stderr)
        return None
    finally:
        if data_in is not None:
            data_in.close()
        if timer_in is not None:
            timer_in.close()


def main():
    """Main function to demonstrate data transmission and reception."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if len(sys.argv) > 1 and sys.argv[1] == "send":
        message = "Hello"
        print(f"Sending: {message}")
        send_data(message)
        print("Sending complete.")
    elif len(sys.argv) > 1 and sys.argv[1] == "receive":
        received = receive_data()
        if received:
            print(f"Received: {received}")
        else:
            print("No data received.")
    else:
        print("Usage: python script.py send | python script.py receive")


if __name__ == "__main__":
    main()

