import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PIN_CONFIG = {
    14: {'name': 'Pin 14', 'initial': 'HIGH'},
    15: {'name': 'Pin 15', 'initial': 'LOW'},
    18: {'name': 'Pin 18', 'initial': 'HIGH'},
    20: {'name': 'Pin 20', 'initial': 'LOW'},
    21: {'name': 'Pin 21', 'initial': 'LOW'},
}

PIN_21_PULSE_COUNT = 1600
PULSE_DURATION = 156.25e-6

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio(pin_config):
    devices = {}
    for pin, cfg in pin_config.items():
        try:
            dev = OutputDevice(pin, active_high=True, initial_value=cfg['initial'] == 'HIGH')
            devices[pin] = dev
            print(f"{cfg['name']} set to {cfg['initial']} (BCM pin {pin})")
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error setting up GPIO pin {pin}: {e}", file=sys.stderr)
            cleanup(devices)
            sys.exit(1)
    return devices

def pulse_pin(device, count, duration):
    for _ in range(count):
        if not _running:
            return
        device.on()
        time.sleep(duration)
        device.off()
        time.sleep(duration)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    devices = setup_gpio(PIN_CONFIG)

    try:
        print("Starting pulse train on Pin 21...")
        pulse_pin(devices[21], PIN_21_PULSE_COUNT, PULSE_DURATION)

        if not _running:
            return

        print("Setting Pin 20 LOW...")
        devices[20].off()

        print("Starting pulse train on Pin 21...")
        pulse_pin(devices[21], PIN_21_PULSE_COUNT, PULSE_DURATION)

    except Exception as e:
        print(f"An error occurred during pulsing: {e}", file=sys.stderr)
    finally:
        cleanup(devices)

def cleanup(devices):
    for pin, dev in devices.items():
        try:
            dev.close()
        except Exception:
            pass
    print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

