    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO setup error on pin {PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}")
        sys.exit(1)

    try:
        while running:
            led.on()
            time.sleep(ON_TIME)
            if not running:
                break
            led.off()
            time.sleep(OFF_TIME)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        try:
            led.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

