import signal
import time
import zmq
import logging
from typing import Callable, Dict, Any, Optional

try:
    from gpiozero import PWMOutputDevice, OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    logging.error("gpiozero library not found. Install with: pip install gpiozero")
    raise


class PIDHandler:
    """
    Manages PID controllers and an error output signal using gpiozero.

    BOARD-compatible physical pin numbering is used throughout.
    PWM mode: physical pin 12 (BCM GPIO 18) -> PWMOutputDevice.
    Digital mode: physical pin 10 (BCM GPIO 15) -> OutputDevice.
    """

    PWM_PIN = 12   # BOARD pin 12 -> BCM GPIO 18
    DIGITAL_PIN = 10  # BOARD pin 10 -> BCM GPIO 15
    PWM_FREQ = 1000   # Hz
    TIMEOUT = 20.0    # seconds

    def __init__(self, config: Dict[str, Any], logger: Optional[logging.Logger] = None):
        self.config = config
        self.logger = logger or logging.getLogger(__name__)
        self.pids: Dict[str, Any] = {}
        self.subscriptions: Dict[str, Callable[[Dict[str, Any]], None]] = {}
        self.last_msg = time.time()
        self.global_err_state = False
        self.error_output: Optional[Any] = None
        self._running = True

        # --- GPIO initialization with error handling ---
        try:
            if config.get('pwm', False):
                self.error_output = PWMOutputDevice(
                    pin=self.PWM_PIN,
                    frequency=self.PWM_FREQ,
                    initial_value=0.0
                )
                self.logger.info(
                    f"PWM error output initialized on physical pin {self.PWM_PIN} "
                    f"at {self.PWM_FREQ} Hz, initial duty 0.0"
                )
            else:
                self.error_output = OutputDevice(
                    pin=self.DIGITAL_PIN,
                    initial_value=False
                )
                self.logger.info(
                    f"Digital error output initialized on physical pin {self.DIGITAL_PIN}"
                )
        except GPIOZeroError as e:
            self.logger.error(f"GPIO initialization failed: {e}")
            raise
        except Exception as e:
            self.logger.error(f"Unexpected error during GPIO init: {e}")
            raise

        # --- Signal handlers for clean shutdown ---
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

    # ------------------------------------------------------------------
    # GPIO helpers
    # ------------------------------------------------------------------
    def update_error_output(self) -> None:
        """Set the error output based on self.global_err_state."""
        if self.error_output is None:
            self.logger.error("Error output device not initialized; cannot update.")
            return
        try:
            if self.config.get('pwm', False):
                duty = 1.0 if self.global_err_state else 0.0
                self.error_output.value = duty
            else:
                self.error_output.on() if self.global_err_state else self.error_output.off()
        except DeviceClosed:
            self.logger.error("Error output device already closed.")
        except GPIOZeroError as e:
            self.logger.error(f"Error updating error output: {e}")
        except Exception as e:
            self.logger.error(f"Unexpected error updating error output: {e}")

    def set_error_output(self, state: bool) -> None:
        """Directly set the error output to the given boolean state."""
        self.global_err_state = state
        self.update_error_output()

    # ------------------------------------------------------------------
    # Watchdog / timeout
    # ------------------------------------------------------------------
    def check_timeout(self) -> None:
        """Trigger error output if no data received within TIMEOUT seconds."""
        if time.time() - self.last_msg > self.TIMEOUT:
            self.logger.warning(
                f"No data received for {self.TIMEOUT:.0f}s. "
                f"Triggering error output (state={self.global_err_state})."
            )
            self.set_error_output(True)

    # ------------------------------------------------------------------
    # ZMQ message handling
    # ------------------------------------------------------------------
    def handle_message(self, sock: zmq.Socket) -> None:
        """Process a single ZMQ message (non-blocking, EAGAIN-safe)."""
        try:
            msg = sock.recv(flags=zmq.NOBLOCK)
            self.last_msg = time.time()
            self.process_message(msg)
        except zmq.Again:
            # No message available without blocking
            self.check_timeout()
        except zmq.ZMQError as e:
            self.logger.error(f"ZMQ error during recv: {e}")
        except Exception as e:
            self.logger.error(f"Unexpected error handling message: {e}")

    def process_message(self, msg: bytes) -> None:
        """Dispatch a received message to the appropriate PID controller or subscription."""
        try:
            data = self.config.get('serializer', json.loads)(msg)
            if data.get('type') == 'pid_update':
                self.update_pid(data['pid'], data['value'])
            elif data.get('type') == 'subscription':
                self.subscribe(data['topic'], data['callback'])
            else:
                self.logger.warning(f"Unknown message type: {data.get('type')}")
        except json.JSONDecodeError as e:
            self.logger.error(f"JSON decode error: {e}")
        except Exception as e:
            self.logger.error(f"Error processing message: {e}")

    # ------------------------------------------------------------------
    # PID controller helpers
    # ------------------------------------------------------------------
    def update_pid(self, pid: str, value: float) -> None:
        """Update the value of a PID controller."""
        if pid not in self.pids:
            self.logger.error(f"PID '{pid}' not found.")
            return
        self.pids[pid].update(value)

    def subscribe(self, topic: str, callback: Callable[[Dict[str, Any]], None]) -> None:
        """Subscribe to a topic and register a callback."""
        self.subscriptions[topic] = callback

    # ------------------------------------------------------------------
    # Cleanup
    # ------------------------------------------------------------------
    def cleanup(self) -> None:
        """Release GPIO resources and stop the error output."""
        self._running = False
        if self.error_output is not None:
            try:
                if self.config.get('pwm', False):
                    self.error_output.value = 0.0
                    self.error_output.close()
                else:
                    self.error_output.off()
                    self.error_output.close()
                self.logger.info("GPIO resources released.")
            except Exception as e:
                self.logger.error(f"Error during GPIO cleanup: {e}")

    def _signal_handler(self, signum, frame) -> None:
        """Handle SIGINT/SIGTERM for graceful shutdown."""
        sig_name = signal.Signals(signum).name
        self.logger.info(f"Received {sig_name}. Initiating cleanup...")
        self.cleanup()
        self.logger.info("Cleanup complete. Exiting.")
        raise SystemExit(0)

