# Raspberry Pi 5 Fingerprint Authentication Script
# Uses an Adafruit Fingerprint sensor over I2C (address 0x26)

import time
import board
import busio
import adafruit_fingerprint

# Constants
FINGERPRINT_SENSOR_ADDRESS = 0x26
AUTHENTICATION_DELAY = 1  # seconds


def initialize_i2c():
    """Initialize the I2C bus on board.SCL (GPIO3) / board.SDA (GPIO2)."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except (ValueError, RuntimeError) as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_sensor(i2c_bus):
    """Initialize the Adafruit fingerprint sensor on the I2C bus."""
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return sensor
    except (ValueError, RuntimeError) as e:
        print(f"Error initializing fingerprint sensor at 0x{FINGERPRINT_SENSOR_ADDRESS:02X}: {e}")
        return None


def capture_fingerprint_image(sensor):
    """Capture a fingerprint image from the sensor.

    Returns the image buffer on success, or None if no finger is detected.
    Handles NOFINGER gracefully without raising.
    """
    try:
        return sensor.get_image()
    except RuntimeError as e:
        # get_image() raises RuntimeError with NOFINGER or other sensor errors
        print(f"Sensor error (NOFINGER or sensor unresponsive): {e}")
        return None
    except Exception as e:
        print(f"Unexpected error capturing image: {e}")
        return None


def create_template(sensor, image):
    """Convert a fingerprint image to a template for comparison."""
    try:
        return sensor.image_2_tz(1)
    except Exception as e:
        print(f"Error creating template: {e}")
        return None


def search_database(sensor, template):
    """Search the fingerprint database for a match."""
    try:
        return sensor.finger_search()
    except Exception as e:
        print(f"Error searching fingerprint database: {e}")
        return None


def authenticate_user(sensor):
    """Perform one full authentication attempt."""
    print("Place your finger on the sensor...")
    image = capture_fingerprint_image(sensor)
    if image is None:
        print("No finger detected. Please try again.")
        return False

    template = create_template(sensor, image)
    if template is None:
        print("Template creation failed.")
        return False

    result = search_database(sensor, template)
    if result is None:
        print("Fingerprint search failed.")
        return False

    if result.found == adafruit_fingerprint.OK:
        print(f"Access Granted, ID: {result.id}, Confidence: {result.confidence}")
        return True
    else:
        print("Access Denied")
        return False


def main():
    """Main entry point for the fingerprint authentication loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            authenticate_user(sensor)
            time.sleep(AUTHENTICATION_DELAY)

    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        # Deinitialize the I2C bus to release the GPIO pins
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Program exited.")


if __name__ == "__main__":
    main()

