import signal
import sys

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, GPIOZeroWarning
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

import warnings

FAN_PIN = 12
PWM_FREQ = 25000  # 25 kHz, standard for 4-wire PWM fans

fan = None


def cleanup(signum=None, frame=None):
    """Stop PWM and release resources on exit."""
    global fan
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None
    if signum is not None:
        sys.exit(0)


def main():
    global fan

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize PWM output device; fall back to software PWM if hardware PWM
    # is unavailable (e.g., mocked or emulated Pi environments).
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except GPIOZeroError as e:
        print(f"Warning: hardware PWM unavailable on GPIO{FAN_PIN} ({e}). "
              "Falling back to software PWM.", file=sys.stderr)
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0,
                                  pwm_software=True)
        except GPIOZeroError as e2:
            print(f"Error: could not initialize PWM on GPIO{FAN_PIN}: {e2}",
                  file=sys.stderr)
            sys.exit(1)
    except Exception as e:
        print(f"Error: unexpected failure initializing PWM on GPIO{FAN_PIN}: {e}",
              file=sys.stderr)
        sys.exit(1)

    print(f"PWM fan control ready on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    print("Enter a speed 0-100 (Ctrl+C or 'q' to quit).\n")

    while True:
        try:
            raw = input("Fan Speed (0-100): ").strip()
        except EOFError:
            print("\nEOF received, exiting.")
            break

        if raw.lower() == 'q':
            break

        try:
            speed = float(raw)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        if not 0.0 <= speed <= 100.0:
            print("Invalid speed. Please enter a value between 0 and 100.")
            continue

        try:
            fan.value = speed / 100.0
            print(f"Duty cycle set to {speed:.1f}%")
        except GPIOZeroError as e:
            print(f"Error setting duty cycle: {e}", file=sys.stderr)


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

