from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

LED_PIN = 18
PORT = 8080

led = None
httpd = None


class LEDRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/led/on':
            try:
                led.on()
                self.send_response(200)
                self.send_header('Content-Type', 'text/plain')
                self.end_headers()
                self.wfile.write(b'LED is ON')
            except GPIOZeroError as e:
                self.send_error(500, f'GPIO error: {e}')
        elif self.path == '/led/off':
            try:
                led.off()
                self.send_response(200)
                self.send_header('Content-Type', 'text/plain')
                self.end_headers()
                self.wfile.write(b'LED is OFF')
            except GPIOZeroError as e:
                self.send_error(500, f'GPIO error: {e}')
        else:
            self.send_error(404, 'Not Found')

    def log_message(self, fmt, *args):
        sys.stderr.write(f"{self.address_string()} - {fmt % args}\n")


def cleanup(signum=None, frame=None):
    global httpd, led
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global led, httpd
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f'Failed to initialize LED on GPIO{LED_PIN}: {e}', file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        httpd = ThreadingHTTPServer(('0.0.0.0', PORT), LEDRequestHandler)
        print(f'Serving at 0.0.0.0:{PORT}')
        httpd.serve_forever()
    except OSError as e:
        print(f'Error: cannot bind to port {PORT}: {e}', file=sys.stderr)
        cleanup()
        sys.exit(1)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
        cleanup()
        sys.exit(1)


if __name__ == '__main__':
    main()

