import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2")
    sys.exit(1)

# BH1750 constants
BH1750_ADDRESS = 0x23
POWER_ON = 0x01
CONTINUOUS_HIGH_RES_MODE = 0x10
MEASUREMENT_DELAY_S = 0.18  # max conversion time for high-res mode
LOOP_DELAY_S = 1.0

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def init_sensor(bus):
    """Initialize the BH1750 sensor."""
    try:
        bus.write_byte(BH1750_ADDRESS, POWER_ON)
        time.sleep(0.01)
        bus.write_byte(BH1750_ADDRESS, CONTINUOUS_HIGH_RES_MODE)
        time.sleep(MEASUREMENT_DELAY_S)
    except OSError as e:
        raise RuntimeError(f"Failed to initialize BH1750 at 0x{BH1750_ADDRESS:02X}: {e}")


def read_lux(bus):
    """Read and convert lux from the BH1750 sensor."""
    try:
        data = bus.read_i2c_block_data(BH1750_ADDRESS, CONTINUOUS_HIGH_RES_MODE, 2)
    except OSError as e:
        raise RuntimeError(f"I2C read error: {e}")

    if len(data) < 2:
        raise RuntimeError(f"Incomplete data read: got {len(data)} bytes, expected 2")

    raw = (data[0] << 8) | data[1]
    return raw / 1.2


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}")
        sys.exit(1)

    try:
        init_sensor(bus)
        print("BH1750 initialized. Reading lux (Ctrl+C to stop)...")

        while _running:
            try:
                lux = read_lux(bus)
                print(f"Light Level: {lux:.2f} lux")
            except RuntimeError as e:
                print(f"Sensor read error: {e}")
            time.sleep(LOOP_DELAY_S)

    except RuntimeError as e:
        print(f"Initialization error: {e}")
        sys.exit(1)
    finally:
        bus.close()
        print("\nProgram terminated by user.")


if __name__ == "__main__":
    main()

