import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

LED_PIN = 17

led = None

def cleanup(signum=None, frame=None):
    """Turn off the LED and release resources on exit."""
    global led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        print("\nExiting gracefully.")
        sys.exit(0)

def main():
    global led

    # Warn if not running on a Raspberry Pi (gpiozero uses lgpio on Pi 3/4/5)
    try:
        import platform
        if platform.machine() not in ('armv7l', 'aarch64'):
            print("Warning: This program is intended for a Raspberry Pi. Running on non-Pi hardware.", file=sys.stderr)
    except Exception:
        pass

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Error: Failed to initialize GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: Unexpected failure initializing GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Blinking LED on GPIO{LED_PIN}. Press Ctrl+C to exit.")

    try:
        while True:
            led.on()
            time.sleep(1)
            led.off()
            time.sleep(1)
    except Exception as e:
        print(f"Error during blink loop: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

