#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpads A (GPIO5), B (GPIO6), C (GPIO12) toggle bits 4, 2, 1 respectively.
Discrete red/green/blue LEDs (GPIO7, GPIO8) reflect bit states.
HT16K33 14-segment display (I2C 0x70) shows the decimal value.
APA102 LED strip (GPIO10, GPIO11) lights a single pixel at the value index
with color derived from the bit states. Piezo buzzer (GPIO13) plays a 0.5 s
tone at MIDI note 60 + the decimal value.

Degrades gracefully when peripherals are absent; on exit all HAT outputs
are turned off.
"""

import signal
import sys
import time

try:
    import board
    import busio
    from adafruit_ht16k33.segments import Seg14x4
    from adafruit_dotstar import DotStar
    from gpiozero import Button, LED, PWMOutputDevice
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    sys.exit(1)

# --- Pin / display constants -------------------------------------------------
TOUCH_PINS = {"A": 5, "B": 6, "C": 12}
LED_PINS = {"red": 7, "green": 8}
BUZZER_PIN = 13
DISPLAY_I2C_ADDR = 0x70
STRIP_DATA_PIN = 10
STRIP_CLOCK_PIN = 11

# --- Globals (populated in setup) --------------------------------------------
display = None
strip = None
leds = {}
touch_buttons = {}
buzzer = None
bit_states = [False, False, False]
running = True


def cleanup(*_):
    """Release all HAT resources on exit."""
    global running
    running = False
    try:
        if display is not None:
            display.fill(0)
            display.show()
    except Exception:
        pass
    try:
        if strip is not None:
            strip.fill((0, 0, 0))
            strip.show()
    except Exception:
        pass
    for led in leds.values():
        try:
            led.off()
        except Exception:
            pass
    try:
        if buzzer is not None:
            buzzer.off()
    except Exception:
        pass


def update_display():
    """Push the current bit states to the 14-segment display."""
    if display is None:
        return
    try:
        value = 0
        for i, bit in enumerate(bit_states):
            value |= (1 if bit else 0) << i
        display.print_hex(value)
        display.show()
    except Exception as exc:
        print(f"Display update error: {exc}", file=sys.stderr)


def update_leds():
    """Drive the discrete red/green/blue LEDs from the bit states."""
    for name, led in leds.items():
        try:
            if name == "red":
                led.on() if bit_states[0] else led.off()
            elif name == "green":
                led.on() if bit_states[1] else led.off()
            elif name == "blue":
                led.on() if bit_states[2] else led.off()
        except Exception as exc:
            print(f"LED '{name}' update error: {exc}", file=sys.stderr)


def update_strip():
    """Light the APA102 LED strip according to the current value."""
    if strip is None:
        return
    try:
        strip.fill((0, 0, 0))
        value = 0
        for i, bit in enumerate(bit_states):
            value |= (1 if bit else 0) << i
        if value == 0:
            strip[0] = (10, 10, 10)
        elif value == 7:
            for i in range(7):
                strip[i] = (10, 10, 10)
        else:
            r = 31 if bit_states[0] else 0
            g = 31 if bit_states[1] else 0
            b = 31 if bit_states[2] else 0
            strip[value] = (r, g, b)
        strip.show()
    except Exception as exc:
        print(f"Strip update error: {exc}", file=sys.stderr)


def play_tone(value):
    """Play a 0.5 s tone on the piezo buzzer at MIDI note 60 + value."""
    if buzzer is None:
        return
    try:
        midi = 60 + value
        freq = 440.0 * (2.0 ** ((midi - 69) / 12.0))
        buzzer.frequency = freq
        buzzer.value = 0.5
        time.sleep(0.5)
        buzzer.value = 0
    except Exception as exc:
        print(f"Buzzer tone error: {exc}", file=sys.stderr)


def handle_touch(channel):
    """Toggle the bit for *channel* and refresh all HAT outputs."""
    try:
        bit_index = {"A": 0, "B": 1, "C": 2}[channel]
        bit_states[bit_index] = not bit_states[bit_index]
        update_display()
        update_leds()
        update_strip()
        value = 0
        for i, bit in enumerate(bit_states):
            value |= (1 if bit else 0) << i
        play_tone(value)
    except Exception as exc:
        print(f"Touch handler error on channel '{channel}': {exc}", file=sys.stderr)


def setup():
    """Initialise all HAT peripherals.  Missing degrades gracefully."""
    global display, strip, leds, touch_buttons, buzzer

    # --- Display -------------------------------------------------------------
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        display = Seg14x4(i2c, address=DISPLAY_I2C_ADDR)
        display.brightness = 0.5
        display.fill(0)
        display.show()
    except Exception as exc:
        print(f"Display init failed: {exc}", file=sys.stderr)
        display = None

    # --- APA102 LED strip ----------------------------------------------------
    try:
        strip = DotStar(
            STRIP_DATA_PIN, STRIP_CLOCK_PIN, 7, brightness=0.5, auto_write=False
        )
        strip.fill((0, 0, 0))
        strip.show()
    except Exception as exc:
        print(f"Strip init failed: {exc}", file=sys.stderr)
        strip = None

    # --- Discrete LEDs -------------------------------------------------------
    for name, pin in LED_PINS.items():
        try:
            leds[name] = LED(pin)
            leds[name].off()
        except Exception as exc:
            print(f"LED '{name}' init failed: {exc}", file=sys.stderr)

    # --- Buzzer --------------------------------------------------------------
    try:
        buzzer = PWMOutputDevice(BUZZER_PIN, frequency=440, initial_value=0)
    except Exception as exc:
        print(f"Buzzer init failed: {exc}", file=sys.stderr)
        buzzer = None

    # --- Touchpads -----------------------------------------------------------
    for name, pin in TOUCH_PINS.items():
        try:
            btn = Button(pin, pull_up=True, bounce_time=0.05)
            btn.when_pressed = lambda ch=name: handle_touch(ch)
            touch_buttons[name] = btn
        except Exception as exc:
            print(f"Touchpad '{name}' init failed: {exc}", file=sys.stderr)


def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    setup()
    print("Rainbow HAT binary counter ready.  Press Ctrl+C to exit.")
    try:
        while running:
            signal.pause()
    except Exception as exc:
        print(f"Main loop error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

