import time
import atexit
import logging
import signal
import sys

try:
    import board
    import busio
    from adafruit_pca9685 import PCA9685
except ImportError:
    logging.error("Required libraries not found. Install with: pip install adafruit-circuitpython-pca9685")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class Fuchikoma:
    """
    Controls a robotic arm using a PCA9685 PWM servo driver.
    """

    SERVO_MIN_PULSE = 150
    SERVO_MAX_PULSE = 600
    PWM_FREQUENCY = 60
    SERVO_RANGE = 77
    DEFAULT_MOVE_DELAY = 0.029

    def __init__(self, i2c_address=0x40):
        self.i2c_address = i2c_address
        self.pwm = None
        self.i2c = None
        self.servos = {
            'claw': {'channel': 0, 'angle_range': self.SERVO_RANGE},
            'lock': {'channel': 1, 'angle_range': self.SERVO_RANGE},
            'water_gun': {'channel': 2, 'angle_range': self.SERVO_RANGE},
        }
        self._initialize_pwm()
        atexit.register(self.cleanup)

    def _initialize_pwm(self):
        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            self.pwm = PCA9685(self.i2c, address=self.i2c_address)
            self.pwm.frequency = self.PWM_FREQUENCY
            logging.info("PCA9685 initialized at address 0x%02X.", self.i2c_address)
        except (ValueError, OSError) as e:
            logging.error("Failed to initialize PCA9685 at 0x%02X: %s", self.i2c_address, e)
            self.cleanup()
            sys.exit(1)

    def _calculate_pulse(self, angle):
        zero_pulse = (self.SERVO_MIN_PULSE + self.SERVO_MAX_PULSE) / 2
        pulse_width = zero_pulse - self.SERVO_MIN_PULSE
        pulse = zero_pulse + (pulse_width * angle / self.SERVO_RANGE)
        return int(pulse)

    def move_servo(self, servo_name, angle, delay=DEFAULT_MOVE_DELAY):
        if servo_name not in self.servos:
            logging.error("Invalid servo name: %s", servo_name)
            return

        if not -self.servos[servo_name]['angle_range'] <= angle <= self.servos[servo_name]['angle_range']:
            logging.error("Angle %d out of range for servo %s", angle, servo_name)
            return

        channel = self.servos[servo_name]['channel']
        try:
            pulse = self._calculate_pulse(angle)
            self.pwm.channels[channel].duty_cycle = pulse
            time.sleep(delay)
            self.pwm.channels[channel].duty_cycle = 0
        except Exception as e:
            logging.error("Error moving servo %s: %s", servo_name, e)

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        logging.info("Cleaning up PCA9685 resources.")
        if self.pwm is not None:
            for channel in self.pwm.channels:
                try:
                    channel.duty_cycle = 0
                except Exception:
                    pass
        if self.i2c is not None:
            try:
                self.i2c.deinit()
            except Exception:
                pass


def main():
    fuchikoma = Fuchikoma()

    def signal_handler(signum, frame):
        logging.info("Signal %d received, exiting.", signum)
        fuchikoma.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fuchikoma.bite()
        time.sleep(1)
        fuchikoma.open_claw()
        time.sleep(1)
        fuchikoma.lock()
        time.sleep(1)
        fuchikoma.unlock()
        time.sleep(1)
        fuchikoma.shoot()
        time.sleep(1)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    finally:
        fuchikoma.cleanup()


if __name__ == '__main__':
    main()

