import smbus2
import time
import datetime
import json
import gzip
import os
import threading
import random
import sys

# Configuration
LOG_FILE_SIZE_LIMIT = 1024 * 1024  # 1 MB
I2C_ADDRESSES = [0x3B, 0x3C, 0x3D]
DATA_ACQUISITION_INTERVAL = 5  # seconds

# Global state
log_file_path = None
log_file_lock = threading.Lock()
running = True


def get_current_date():
    """Returns the current date in YYYY-MM-DD format."""
    return datetime.datetime.now().strftime("%Y-%m-%d")


def get_current_time():
    """Returns the current time in HHMMSS format."""
    return datetime.datetime.now().strftime("%H%M%S")


def get_log_file_path():
    """Returns the current log file path, creating a new file if necessary."""
    global log_file_path
    today = get_current_date()
    if log_file_path is None or today != log_file_path.split(".")[0].split("_")[-1]:
        new_path = f"energy_log_{today}.json"
        if not os.path.exists(new_path):
            try:
                with open(new_path, "w") as f:
                    f.write("[\n")
                os.chmod(new_path, 0o600)
            except OSError as e:
                print(f"Error creating log file {new_path}: {e}")
                return None
        log_file_path = new_path
    return log_file_path


def compress_log_file():
    """Compresses the current log file and rotates to a timestamped file."""
    global log_file_path
    if log_file_path is None:
        return
    try:
        with log_file_lock:
            with open(log_file_path, "r") as f_in:
                data = f_in.read()
            if data.endswith("["):
                data = data[:-1]
            if data.endswith("\n"):
                data = data[:-1]
            data += "\n]"
            timestamp = get_current_time()
            compressed_path = f"energy_log_{timestamp}.json.gz"
            with gzip.open(compressed_path, "wb") as f_out:
                f_out.write(data.encode("utf-8"))
            os.chmod(compressed_path, 0o600)
            os.remove(log_file_path)
            log_file_path = f"energy_log_{today}.json"
            with open(log_file_path, "w") as f:
                f.write("[\n")
            os.chmod(log_file_path, 0o600)
            print(f"Log file compressed and rotated to {compressed_path}")
    except Exception as e:
        print(f"Error compressing log file: {e}")


def log_data(data):
    """Appends a JSON line to the log file, handling file rotation and compression."""
    path = get_log_file_path()
    if path is None:
        return
    try:
        with log_file_lock:
            file_size = os.path.getsize(path) if os.path.exists(path) else 0
            if file_size > LOG_FILE_SIZE_LIMIT:
                compress_log_file()
                path = get_log_file_path()
            with open(path, "a") as f:
                if file_size > 0:
                    f.write(",\n")
                json.dump(data, f)
                f.write("\n")
    except Exception as e:
        print(f"Error logging data: {e}")


def simulate_sensor_data(address):
    """Simulates sensor data for a given I2C address."""
    active_power = random.uniform(50, 200)
    voltage = random.uniform(220, 240)
    current = random.uniform(0.2, 1.0)
    frequency = random.uniform(59.5, 60.5)
    power_factor = random.uniform(0.8, 1.0)
    timestamp = datetime.datetime.now().isoformat()
    return {
        "timestamp": timestamp,
        "address": address,
        "active_power": active_power,
        "voltage": voltage,
        "current": current,
        "frequency": frequency,
        "power_factor": power_factor,
    }


def data_acquisition_thread():
    """Background thread that acquires and logs simulated sensor data."""
    global running
    while running:
        try:
            for address in I2C_ADDRESSES:
                data = simulate_sensor_data(address)
                log_data(data)
            time.sleep(DATA_ACQUISITION_INTERVAL)
        except Exception as e:
            print(f"Error in data acquisition thread: {e}")
            time.sleep(1)


def view_current_readings():
    """Prints the most recent readings from the log file."""
    global log_file_path
    if log_file_path is None:
        print("No log file available.")
        return
    try:
        with open(log_file_path, "r") as f:
            data = json.load(f)
        if not data:
            print("No data available.")
            return
        last_reading = data[-1]
        print(f"Current Readings: {last_reading}")
    except FileNotFoundError:
        print(f"Log file not found: {log_file_path}")
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {log_file_path}")
    except Exception as e:
        print(f"Error viewing current readings: {e}")


def view_data_for_date(date_input):
    """Prints all readings for a given date from the log file."""
    global log_file_path
    if log_file_path is None:
        print("No log file available.")
        return
    try:
        with open(log_file_path, "r") as f:
            data = json.load(f)
        readings = [r for r in data if r.get("timestamp", "").startswith(date_input)]
        if not readings:
            print(f"No data found for date: {date_input}")
            return
        for reading in readings:
            print(f"Reading: {reading}")
    except FileNotFoundError:
        print(f"Log file not found: {log_file_path}")
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {log_file_path}")
    except Exception as e:
        print(f"Error viewing data for date: {e}")


def get_min_max_avg(data, key):
    """Calculates minimum, maximum, and average of a given key in the data."""
    if not data:
        return None, None, None
    values = [r.get(key) for r in data if r.get(key) is not None]
    if not values:
        return None, None, None
    return min(values), max(values), sum(values) / len(values)


def view_stats_for_date(date_input):
    """Prints minimum, maximum, and average active power for a given date and sensor."""
    global log_file_path
    if log_file_path is None:
        print("No log file available.")
        return
    try:
        with open(log_file_path, "r") as f:
            data = json.load(f)
        filtered_data = [r for r in data if r.get("timestamp", "").startswith(date_input)]
        if not filtered_data:
            print(f"No data found for date: {date_input}")
            return
        for address in I2C_ADDRESSES:
            sensor_data = [r for r in filtered_data if r.get("address") == address]
            if not sensor_data:
                continue
            min_power, max_power, avg_power = get_min_max_avg(sensor_data, "active_power")
            print(f"Sensor {address}: Min Power: {min_power}, Max Power: {max_power}, Avg Power: {avg_power}")
    except FileNotFoundError:
        print(f"Log file not found: {log_file_path}")
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {log_file_path}")
    except Exception as e:
        print(f"Error viewing statistics: {e}")


def main():
    """Main function to run the energy monitoring system."""
    global running
    data_thread = threading.Thread(target=data_acquisition_thread, daemon=True)
    data_thread.start()

    while running:
        try:
            print("\nEnergy Monitoring System")
            print("1. View Current Readings")
            print("2. View Data for Date")
            print("3. View Statistics for Date")
            print("4. Quit")
            choice = input("Enter your choice: ").strip()

            if choice == "1":
                view_current_readings()
            elif choice == "2":
                date_input = input("Enter the date (YYYY-MM-DD): ").strip()
                view_data_for_date(date_input)
            elif choice == "3":
                date_input = input("Enter the date (YYYY-MM-DD): ").strip()
                view_stats_for_date(date_input)
            elif choice == "4":
                running = False
                data_thread.join(timeout=2)
                print("Exiting program.")
                break
            else:
                print("Invalid choice. Please try again.")
        except Exception as e:
            print(f"An error occurred: {e}")


if __name__ == "__main__":
    main()

