    """Prints the most recent readings from the log file."""
    global log_file_path
    if log_file_path is None:
        print("No log file available.")
        return
    try:
        with open(log_file_path, "r") as f:
            data = json.load(f)
        if not data:
            print("No data available.")
            return
        last_reading = data[-1]
        print(f"Current Readings: {last_reading}")
    except FileNotFoundError:
        print(f"Log file not found: {log_file_path}")
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {log_file_path}")
    except Exception as e:
        print(f"Error viewing current readings: {e}")


def view_data_for_date(date_input):
    """Prints all readings for a given date from the log file."""
    global log_file_path
    if log_file_path is None:
        print("No log file available.")
        return
    try:
        with open(log_file_path, "r") as f:
            data = json.load(f)
        readings = [r for r in data if r.get("timestamp", "").startswith(date_input)]
        if not readings:
            print(f"No data found for date: {date_input}")
            return
        for reading in readings:
            print(f"Reading: {reading}")
    except FileNotFoundError:
        print(f"Log file not found: {log_file_path}")
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {log_file_path}")
    except Exception as e:
        print(f"Error viewing data for date: {e}")


def get_min_max_avg(data, key):
    """Calculates minimum, maximum, and average of a given key in the data."""
    if not data:
        return None, None, None
    values = [r.get(key) for r in data if r.get(key) is not None]
    if not values:
        return None, None, None
    return min(values), max(values), sum(values) / len(values)


def view_stats_for_date(date_input):
    """Prints minimum, maximum, and average active power for a given date and sensor."""
    global log_file_path
    if log_file_path is None:
        print("No log file available.")
        return
    try:
        with open(log_file_path, "r") as f:
            data = json.load(f)
        filtered_data = [r for r in data if r.get("timestamp", "").startswith(date_input)]
        if not filtered_data:
            print(f"No data found for date: {date_input}")
            return
        for address in I2C_ADDRESSES:
            sensor_data = [r for r in filtered_data if r.get("address") == address]
            if not sensor_data:
