            min_power, max_power, avg_power = get_min_max_avg(sensor_data, "active_power")
            print(f"Sensor {address}: Min Power: {min_power}, Max Power: {max_power}, Avg Power: {avg_power}")
    except FileNotFoundError:
        print(f"Log file not found: {log_file_path}")
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {log_file_path}")
    except Exception as e:
        print(f"Error viewing statistics: {e}")


def main():
    """Main function to run the energy monitoring system."""
    global running
    data_thread = threading.Thread(target=data_acquisition_thread, daemon=True)
    data_thread.start()

