import random
import time
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Configuration
LED_PIN = 18
THRESHOLD = 50
NUM_READINGS = 5
DELAY_SECONDS = 2
RETRY_ON_FAILURE = True

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def simulate_water_quality():
    """Simulates a water quality reading as a percentage (0-100)."""
    return random.randint(0, 100)

def read_water_quality(retry=True):
    """Reads water quality, optionally simulating a failure."""
    if random.random() < 0.1:  # 10% chance of simulated sensor failure
        if retry:
            print("Warning: Simulated sensor failure. Retrying...")
            return read_water_quality(retry=False)
        else:
            print("Error: Simulated sensor failure. Skipping reading.")
            return None
    return simulate_water_quality()

def check_water_quality(led, threshold):
    """Checks water quality and controls the LED."""
    quality = read_water_quality()
    if quality is None:
        print("Skipping quality check due to sensor failure.")
        return

    print(f"Water Quality: {quality}%")

    if quality < threshold:
        led.on()
        print("Water quality is below threshold! Alerting...")
    else:
        led.off()
        print("Water quality is within acceptable range.")

def main():
    """Main function to run the water quality monitoring system."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    led = None
    try:
        # Initialize LED with error handling
        try:
            led = LED(LED_PIN)
            print(f"LED initialized on GPIO{LED_PIN} (BCM).")
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error: Failed to initialize LED on GPIO{LED_PIN}: {e}")
            sys.exit(1)
        except Exception as e:
            print(f"Unexpected error during LED initialization: {e}")
            sys.exit(1)

        print(f"Starting water quality monitoring: {NUM_READINGS} readings, "
              f"{DELAY_SECONDS}s interval, threshold: {THRESHOLD}%")
        print("-" * 50)

        for i in range(NUM_READINGS):
            if not _running:
                print("\nShutdown requested. Stopping readings.")
                break

            check_water_quality(led, THRESHOLD)

            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)

        if _running:
            print("\nWater quality monitoring completed successfully.")
        else:
            print("\nWater quality monitoring stopped early.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean resource release on all exit paths
        if led is not None:
            try:
                led.close()
                print("LED resource released.")
            except Exception as e:
                print(f"Warning: Error during LED cleanup: {e}")
        print("Exiting program.")

if __name__ == "__main__":
    main()

