LED2_PIN = 23

# Global references for cleanup
led1 = None
led2 = None

def cleanup(signum=None, frame=None):
    """Clean up GPIO resources and exit."""
    global led1, led2
    if led1 is not None:
        led1.close()
    if led2 is not None:
        led2.close()
    if signum is not None:
        sys.exit(0)

