    """Turns off both LEDs."""
    try:
        led1.off()
        led2.off()
        print("Both LEDs are OFF")
    except (GPIODeviceError, GPIOZeroError) as e:
        print(f"Error turning off LEDs: {e}", file=sys.stderr)

def toggle_leds(cycles=5):
    """Toggles both LEDs on and off for a specified number of cycles."""
    try:
        for i in range(cycles):
            all_on()
            time.sleep(1)
            all_off()
            time.sleep(1)
    except (GPIODeviceError, GPIOZeroError) as e:
        print(f"Error during LED toggling: {e}", file=sys.stderr)

