import time
import signal
import sys

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2")
    sys.exit(1)

try:
    from gpiozero import LED, Buzzer
except ImportError:
    print("Error: gpiozero library not installed. Install with: pip install gpiozero")
    sys.exit(1)

# Constants
LIS3DH_ADDRESS = 0x18
LIS3DH_WHO_AM_I = 0x0F
LIS3DH_EXPECTED_ID = 0x33
LIS3DH_CTRL_REG1 = 0x20
LIS3DH_CTRL_REG4 = 0x23
LIS3DH_OUT_X_L = 0x28
LIS3DH_SENSITIVITY = 1 / 16384.0  # g/LSB for ±2g full-scale

LED_PIN = 21
BUZZER_PIN = 20

THRESHOLD_LOW = 0.3
THRESHOLD_HIGH = 0.7
SAMPLE_INTERVAL = 0.1

# Global resources for cleanup
led = None
buzzer = None
bus = None
running = True


def cleanup():
    """Turn off outputs and release resources."""
    global led, buzzer, bus
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global running
    running = False


def init_hardware():
    """Initialize GPIO and I2C. Returns (led, buzzer, bus) or raises on failure."""
    global led, buzzer, bus

    # --- GPIO ---
    try:
        led = LED(LED_PIN)
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        raise

    # --- I2C ---
    try:
        bus = SMBus(1)
    except Exception as e:
        print(f"Error opening I2C bus 1: {e}")
        raise

    # --- LIS3DH verification ---
    try:
        who_am_i = bus.read_byte_data(LIS3DH_ADDRESS, LIS3DH_WHO_AM_I)
    except Exception as e:
        print(f"Error reading LIS3DH WHO_AM_I: {e}")
        raise

    if who_am_i != LIS3DH_EXPECTED_ID:
        print(f"LIS3DH not found (WHO_AM_I=0x{who_am_i:02X}, expected 0x{LIS3DH_EXPECTED_ID:02X})")
        raise RuntimeError("LIS3DH not detected")

    # --- Configure LIS3DH ---
    try:
        bus.write_byte_data(LIS3DH_ADDRESS, LIS3DH_CTRL_REG1, 0x57)
        time.sleep(0.01)
        bus.write_byte_data(LIS3DH_ADDRESS, LIS3DH_CTRL_REG4, 0x00)
        time.sleep(0.01)
    except Exception as e:
        print(f"Error configuring LIS3DH: {e}")
        raise


def read_acceleration():
    """Read X-axis acceleration in g. Returns None on I2C error."""
    try:
        data = bus.read_i2c_block_data(LIS3DH_ADDRESS, LIS3DH_OUT_X_L | 0x80, 2)
        raw = (data[1] << 8) | data[0]
        if raw >= 0x8000:
            raw -= 0x10000
        return raw * LIS3DH_SENSITIVITY
    except Exception as e:
        print(f"Error reading acceleration: {e}")
        return None


def main():
    global running

    signal.signal(signal.SIGTERM, signal_handler)

    try:
        init_hardware()
    except Exception:
        cleanup()
        sys.exit(1)

    print("Earthquake Early Warning System started. Press Ctrl+C to exit.")

    try:
        while running:
            accel = read_acceleration()

            if accel is None:
                led.off()
                buzzer.off()
                print("Sensor read failed; outputs off.")
            else:
                print(f"Acceleration: {accel:.3f} g")

                if abs(accel) > THRESHOLD_LOW:
                    led.on()
                    if abs(accel) > THRESHOLD_HIGH:
                        buzzer.on()
                    else:
                        buzzer.off()
                else:
                    led.off()
                    buzzer.off()

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        cleanup()
        print("Program finished.")


if __name__ == "__main__":
    main()

