#!/usr/bin/env python3
"""
Raspberry Pi Arduino Motor Shield (L293D + 74HC595) controller.

Wiring (BCM numbering):
  74HC595  LATCH  -> BCM 11
  74HC595  CLOCK  -> BCM 9
  74HC595  DATA   -> BCM 10
  Motor 1 PWM   -> BCM 13 (direction bits 0b00000010 / 0b00000001)
  Motor 2 PWM   -> BCM 12 (direction bits 0b00001000 / 0b00000100)

Requires: RPi.GPIO, gpiozero
"""

import logging
import signal
import sys
import time

import RPi.GPIO as GPIO
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class Motor:
    """Single DC motor driven through an L293D shift-register channel."""

    def __init__(self, motor_num, direction_bits, pwm_pin, shield):
        self.motor_num = motor_num
        self.direction_bits = direction_bits
        self.pwm_pin = pwm_pin
        self.shield = shield
        self._pwm = None
        self._running = False

    def start(self, direction, speed):
        """Start the motor in *direction* (0=clockwise, 1=counter-clockwise) at *speed* (0-100)."""
        if not 0 <= direction <= 1:
            raise ValueError("direction must be 0 (clockwise) or 1 (counter-clockwise)")
        if not 0 <= speed <= 100:
            raise ValueError("speed must be 0-100")
        if self._running:
            logging.warning("Motor %d already running; changing direction/speed.", self.motor_num)
            self.stop()

        direction_bits = self.direction_bits[direction]
        self.shield._shift_out(direction_bits)
        if self._pwm is None:
            try:
                self._pwm = PWMOutputDevice(self.pwm_pin, frequency=100, initial_value=0)
            except Exception as exc:
                logging.error("Failed to start PWM on pin %s: %s", self.pwm_pin, exc)
                raise
        self._pwm.value = speed / 100.0
        self._running = True
        logging.info(
            "Motor %d started %s at %d%% duty cycle.",
            self.motor_num,
            "clockwise" if direction == 0 else "counter-clockwise",
            speed,
        )

    def change_duty_cycle(self, speed):
        """Change the running motor's duty cycle (0-100)."""
        if not self._running:
            logging.warning("Motor %d not running; cannot change duty cycle.", self.motor_num)
            return
        if not 0 <= speed <= 100:
            raise ValueError("speed must be 0-100")
        self._pwm.value = speed / 100.0
        logging.info("Motor %d duty cycle changed to %d%%.", self.motor_num, speed)

    def stop(self):
        """Stop the motor and release PWM."""
        if self._running:
            if self._pwm is not None:
                try:
                    self._pwm.value = 0
                    self._pwm.close()
                except Exception as exc:
                    logging.error("Error stopping PWM on pin %s: %s", self.pwm_pin, exc)
                finally:
                    self._pwm = None
            self.shield._shift_out(self.direction_bits[2])
            self._running = False
            logging.info("Motor %d stopped.", self.motor_num)

    def close(self):
        self.stop()


class MotorShield:
    """Arduino Motor Shield with 74HC595 shift register and two DC motors."""

    def __init__(self, latch_pin, clock_pin, data_pin, pwm_frequency=100):
        self.latch_pin = latch_pin
        self.clock_pin = clock_pin
        self.data_pin = data_pin
        self.pwm_frequency = pwm_frequency
        self.directions = []
        self._shift_state = 0x00
        self._initialized = False

    def __enter__(self):
        self.setup_gpio()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.cleanup()
        return False

    def setup_gpio(self):
        """Configure RPi.GPIO and shift-register control pins."""
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            for pin in (self.latch_pin, self.clock_pin, self.data_pin):
                GPIO.setup(pin, GPIO.OUT)
                GPIO.output(pin, GPIO.LOW)
            self._initialized = True
            logging.info("GPIO setup complete (BCM, pins %d,%d,%d).", self.latch_pin, self.clock_pin, self.data_pin)
        except Exception as exc:
            logging.error("GPIO setup failed: %s", exc)
            raise

    def _shift_out(self, value):
        """Shift 8 bits MSB-first into the 74HC595 and latch."""
        if not self._initialized:
            raise RuntimeError("MotorShield not initialized")
        GPIO.output(self.latch_pin, GPIO.LOW)
        for bit in range(7, -1, -1):
            GPIO.output(self.clock_pin, GPIO.LOW)
            bit_val = GPIO.HIGH if (value >> bit) & 0x01 else GPIO.LOW
            GPIO.output(self.data_pin, bit_val)
            GPIO.output(self.clock_pin, GPIO.HIGH)
        GPIO.output(self.latch_pin, GPIO.HIGH)
        self._shift_state = value

    def add_motor(self, motor_num, direction_bits, pwm_pin):
        """Add a motor to the shield and return the Motor instance."""
        if motor_num in (m.motor_num for m in self.directions):
            raise ValueError(f"Motor {motor_num} already exists")
        motor = Motor(motor_num, direction_bits, pwm_pin, self)
        self.directions.append(motor)
        return motor

    def start(self, motor_num, direction, speed):
        """Start a motor by number."""
        for m in self.directions:
            if m.motor_num == motor_num:
                m.start(direction, speed)
                return
        raise ValueError(f"Motor {motor_num} not found")

    def change_duty_cycle(self, motor_num, speed):
        """Change duty cycle of a running motor."""
        for m in self.directions:
            if m.motor_num == motor_num:
                m.change_duty_cycle(speed)
                return
        raise ValueError(f"Motor {motor_num} not found")

    def stop(self, motor_num):
        """Stop a motor by number."""
        for m in self.directions:
            if m.motor_num == motor_num:
                m.stop()
                return
        raise ValueError(f"Motor {motor_num} not found")

    def stop_all_motors(self):
        """Stop every motor."""
        for m in self.directions:
            m.stop()

    def cleanup(self):
        """Stop all motors and release GPIO resources."""
        try:
            self.stop_all_motors()
        except Exception as exc:
            logging.error("Error stopping motors during cleanup: %s", exc)
        if self._initialized:
            try:
                GPIO.cleanup()
            except Exception as exc:
                logging.error("GPIO cleanup failed: %s", exc)
            finally:
                self._initialized = False
        logging.info("GPIO cleanup complete.")


def _signal_handler(signum, frame):
    logging.info("Signal %d received; shutting down.", signum)
    if shield is not None:
        shield.cleanup()
    sys.exit(0)


shield = None


def main():
    global shield
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        shield = MotorShield(latch_pin=11, clock_pin=9, data_pin=10, pwm_frequency=100)
    except Exception as exc:
        logging.error("Failed to initialize MotorShield: %s", exc)
        sys.exit(1)

    try:
        motor1 = shield.add_motor(1, [0b00000010, 0b00000001, 0b00000000], pwm_pin=13)
        motor2 = shield.add_motor(2, [0b00001000, 0b00000100, 0b00000000], pwm_pin=12)

        motor1.start(0, 75)   # clockwise at 75%
        motor2.start(1, 50)   # counter-clockwise at 50%
        time.sleep(5)

        motor1.change_duty_cycle(25)
        time.sleep(1)

        shield.stop_all_motors()
    except Exception as exc:
        logging.error("Runtime error: %s", exc)
    finally:
        if shield is not None:
            shield.cleanup()


if __name__ == "__main__":
    main()

