import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the two reflectance sensors and the two motors
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26

def setup_gpio():
    """Configure GPIO pins for the line-following cart."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def read_sensors():
    """Read both reflectance sensors. Returns (left_dark, right_dark)."""
    try:
        left_dark = GPIO.input(LEFT_SENSOR_PIN) == GPIO.LOW
        right_dark = GPIO.input(RIGHT_SENSOR_PIN) == GPIO.LOW
        return left_dark, right_dark
    except Exception as e:
        print(f"Sensor read error: {e}")
        return False, False

def set_motors(left_on, right_on):
    """Drive the left and right motors."""
    try:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH if left_on else GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH if right_on else GPIO.LOW)
    except Exception as e:
        print(f"Motor control error: {e}")

def run_line_following(iterations):
    """Run the line-following loop for a specified number of iterations."""
    for i in range(iterations):
        left_dark, right_dark = read_sensors()
        if left_dark and not right_dark:
            set_motors(right_on=True, left_on=False)
        elif right_dark and not left_dark:
            set_motors(right_on=False, left_on=True)
        elif left_dark and right_dark:
            set_motors(right_on=True, left_on=True)
        else:
            set_motors(right_on=False, left_on=False)
        time.sleep(0.1)

def main():
    """Main entry point for the line-following cart."""
    setup_gpio()
    try:
        run_line_following(20)
    except KeyboardInterrupt:
        print("\nLine-following stopped by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up")

if __name__ == "__main__":
    main()

