    Endian = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Servo:
    """
    Represents a Modbus RTU servo motor connected to a Raspberry Pi.
    Provides methods for controlling the servo and reading status.
    """

    # Register map for the servo controller
    REGISTERS = {
        "STATUS": {"R/W": "R", "Register": 0x3000, "functioncode": 3},
        "CONTROL": {"R/W": "W", "Register": 0x3100, "functioncode": 6, "Value": {"Stop": 0x0006, "Start": 0x000F}},
        "OPMODE": {"R/W": "W", "Register": 0x3500, "functioncode": 6, "Value": {"Position": 1}},
        "VelocityCommand": {"R/W": "W", "Register": 0x6F00, "functioncode": 6},
        "VelocityFeedback": {"R/W": "R", "Register": 0x3B00, "functioncode": 3, "read_length": 2},
        "PositionCommand": {"R/W": "W", "Register": 0x4000, "functioncode": 6},
        "PositionFeedback": {"R/W": "R", "Register": 0x3700, "functioncode": 3, "read_length": 2},
    }

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200, timeout: float = 1.0):
        """
        Initializes the Servo object.

        Args:
            port (str): The serial port to use (default: /dev/serial0).
            baudrate (int): The baud rate for Modbus communication (default: 115200).
            timeout (float): Timeout for Modbus operations in seconds (default: 1.0).
        """
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.client = None
        self._connected = False
        self._connect()

    def _connect(self) -> None:
        """Establishes a connection to the servo via Modbus RTU."""
        if ModbusSerialClient is None:
            logger.warning("pymodbus not available; running in degraded mode.")
            return
        try:
            self.client = ModbusSerialClient(
                port=self.port,
                baudrate=self.baudrate,
                parity="N",
                stopbits=1,
                bytesize=8,
                timeout=self.timeout,
            )
            if not self.client.connect():
                logger.warning(f"Failed to connect to servo on {self.port}.")
                self.client = None
                return
            self._connected = True
            logger.info(f"Connected to servo on {self.port}.")
        except serial.SerialException as e:
            logger.warning(f"Serial port error connecting to servo: {e}")
            self.client = None
            self._connected = False
        except Exception as e:
            logger.warning(f"Unexpected error connecting to servo: {e}")
            self.client = None
            self._connected = False

    def _read_register(self, register_name: str, decoder: Any = None) -> Optional[int]:
        """
        Reads a value from a Modbus register.

        Args:
            register_name (str): The name of the register to read.
            decoder (Any): The decoder object for the register.

        Returns:
            int: The value read from the register, or None if an error occurs.
        """
        if not self._connected or self.client is None:
            logger.warning("Not connected to servo. Cannot read register.")
            return None

        register = self.REGISTERS.get(register_name)
        if not register or register.get("R/W") != "R":
            logger.error(f"Register '{register_name}' is not configured for reading.")
            return None

        try:
            address = register["Register"]
            count = register.get("read_length", 1)
            response = self.client.read_holding_registers(address, count=count, slave=1)
            if response.isError():
                raise ModbusException(f"Modbus error reading {register_name}: {response}")

            if decoder is None:
                decoder = BinaryPayloadDecoder.fromRegisters(response.registers, byteorder=Endian.BIG, wordorder=Endian.LITTLE)
            return decoder.decode_16bit_uint()
        except ModbusException as e:
            logger.error(f"Modbus error reading {register_name}: {e}")
            return None
        except Exception as e:
            logger.error(f"Error reading {register_name}: {e}")
            return None

    def _write_register(self, register_name: str, value: int) -> bool:
        """
        Writes a value to a Modbus register.

        Args:
            register_name (str): The name of the register to write.
            value (int): The value to write.

        Returns:
            bool: True if the write was successful, False otherwise.
        """
        if not self._connected or self.client is None:
            logger.warning("Not connected to servo. Cannot write register.")
            return False

        register = self.REGISTERS.get(register_name)
        if not register or register.get("R/W") != "W":
            logger.error(f"Register '{register_name}' is not configured for writing.")
            return False

        try:
            address = register["Register"]
            if isinstance(value, bool):
                value = 1 if value else 0
            count = 1
            if register_name == "OPMODE":
                value = register["Value"]["Position"]
            elif register_name == "CONTROL":
                value = register["Value"]["Start"] if value else register["Value"]["Stop"]
            elif register_name == "VelocityCommand" or register_name == "PositionCommand":
                count = 2

            if count == 1:
                response = self.client.write_single_register(address, value, slave=1)
            else:
                response = self.client.write_multiple_registers(address, count, [value] * count, slave=1)

            if response.isError():
                raise ModbusException(f"Modbus error writing to {register_name}: {response}")
            return True
        except ModbusException as e:
            logger.error(f"Modbus error writing to {register_name}: {e}")
            return False
        except Exception as e:
            logger.error(f"Error writing to {register_name}: {e}")
            return False

    def read_status(self) -> Optional[int]:
        """Reads the servo status."""
        return self._read_register("STATUS")

    def read_velocity_feedback(self) -> Optional[int]:
        """Reads the current velocity feedback."""
        decoder = BinaryPayloadDecoder.fromRegisters([0x0000, 0x0000], byteorder=Endian.BIG, wordorder=Endian.LITTLE)
        return self._read_register("VelocityFeedback", decoder)

    def read_position_feedback(self) -> Optional[int]:
        """Reads the current position feedback."""
        decoder = BinaryPayloadDecoder.fromRegisters([0x0000, 0x0000], byteorder=Endian.BIG, wordorder=Endian.LITTLE)
        return self._read_register("PositionFeedback", decoder)

    def write_control(self, start: bool = True) -> bool:
        """Writes to the CONTROL register."""
        return self._write_register("CONTROL", start)

    def write_opmode(self, position: bool = True) -> bool:
        """Writes to the OPMODE register."""
        return self._write_register("OPMODE", position)

    def write_velocity_command(self, value: int) -> bool:
        """Writes to the VelocityCommand register."""
        return self._write_register("VelocityCommand", value)

    def write_position_command(self, value: int) -> bool:
        """Writes to the PositionCommand register."""
        return self._write_register("PositionCommand", value)

    def close(self) -> None:
        """Closes the Modbus connection."""
        if self.client is not None:
            try:
                self.client.close()
                self._connected = False
                logger.info("Modbus connection closed.")
            except Exception as e:
                logger.error(f"Error closing Modbus connection: {e}")


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    logger.info(f"Received signal {signum}, shutting down.")
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    servo = Servo(port="/dev/serial0", baudrate=115200, timeout=1.0)
    try:
        if servo._connected:
            status = servo.read_status()
            if status is not None:
                logger.info(f"Servo status: 0x{status:04X}")
            else:
                logger.warning("Failed to read servo status.")
        else:
            logger.warning("Servo not connected. Check wiring and serial port.")
    finally:
        servo.close()


if __name__ == "__main__":
    main()

