#!/usr/bin/env python3
"""
Soil Moisture Monitoring and Automated Watering System for Raspberry Pi Zero W.

Reads soil moisture from an Adafruit Seesaw sensor (I2C address 0x36) and
controls a 12V water pump via a relay on GPIO17.  Prints readings every 10 s
and ensures the pump is off on exit.
"""

import signal
import sys
import time
import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_S = 10

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_i2c_bus = None
_soil_sensor = None
_pump = None
_running = True


def _cleanup() -> None:
    """Turn the pump off and release GPIO/I2C resources."""
    global _pump, _i2c_bus
    if _pump is not None:
        try:
            _pump.off()
        except Exception:
            pass
        try:
            _pump.close()
        except Exception:
            pass
        _pump = None

    if _i2c_bus is not None:
        try:
            _i2c_bus.deinit()
        except Exception:
            pass
        _i2c_bus = None


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_hardware() -> None:
    """Initialise I2C bus, sensor, and pump GPIO."""
    global _i2c_bus, _soil_sensor, _pump

    # I2C bus
    try:
        _i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[FATAL] Failed to initialise I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    # Soil moisture sensor
    try:
        _soil_sensor = adafruit_seesaw.seesaw.Seesaw(_i2c_bus, addr=I2C_ADDRESS)
    except Exception as exc:
        print(
            f"[FATAL] Seesaw soil moisture sensor not found at 0x{I2C_ADDRESS:02X}: {exc}",
            file=sys.stderr,
        )
        _cleanup()
        sys.exit(1)

    # Pump GPIO
    try:
        _pump = OutputDevice(PUMP_GPIO_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        print(f"[FATAL] Failed to initialise GPIO {PUMP_GPIO_PIN}: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)


def _read_moisture() -> int | None:
    """Return the current soil moisture reading, or None on error."""
    try:
        return _soil_sensor.moisture_read()
    except Exception as exc:
        print(f"[WARN] Moisture read failed: {exc}", file=sys.stderr)
        return None


def _set_pump(state: bool) -> None:
    """Drive the pump GPIO HIGH (on) or LOW (off)."""
    try:
        if state:
            _pump.on()
        else:
            _pump.off()
    except Exception as exc:
        print(f"[WARN] Pump control failed: {exc}", file=sys.stderr)


def main() -> None:
    """Main monitoring loop."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_hardware()
    print("Soil moisture monitoring started. Press Ctrl+C to exit.")

    try:
        while _running:
            moisture = _read_moisture()

            if moisture is not None:
                pump_on = moisture < MOISTURE_THRESHOLD
                _set_pump(pump_on)
                print(
                    f"Soil Moisture: {moisture} | Pump: {'ON' if pump_on else 'OFF'}"
                )
            else:
                print("Sensor read failed; pump state unchanged.")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < READ_INTERVAL_S:
                time.sleep(0.5)
                slept += 0.5

    finally:
        _cleanup()
        print("Program terminated. Pump ensured OFF. Resources released.")


if __name__ == "__main__":
    main()

