            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < READ_INTERVAL_S:
                time.sleep(0.5)
                slept += 0.5

    finally:
        _cleanup()
        print("Program terminated. Pump ensured OFF. Resources released.")


