import signal
import sys
import logging
from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

RELAY_PIN = 23
relay = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)


def init_relay():
    global relay
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
        logger.info('Relay initialized on GPIO%d', RELAY_PIN)
    except GPIOZeroError as e:
        logger.error('Failed to initialize relay on GPIO%d: %s', RELAY_PIN, e)
        sys.exit(1)


def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
            logger.info('Relay GPIO released')
        except Exception as e:
            logger.error('Error releasing relay GPIO: %s', e)
        relay = None
    if signum is not None:
        logger.info('Received signal %d, exiting', signum)
        sys.exit(0)


@app.route('/relay', methods=['POST'])
def handle_relay():
    try:
        data = request.get_json(silent=True)
        if data is None:
            return jsonify({'error': 'Invalid request: JSON payload expected'}), 400

        if 'state' not in data:
            return jsonify({'error': 'Invalid request: "state" key missing'}), 400

        state = data['state']
        if state == 'on':
            relay.on()
        elif state == 'off':
            relay.off()
        else:
            return jsonify({'error': 'Invalid request: "state" must be "on" or "off"'}), 400

        return jsonify({'status': 'Relay state changed'}), 200

    except GPIOZeroError as e:
        logger.error('GPIO error while handling relay: %s', e)
        return jsonify({'error': 'GPIO error'}), 500
    except Exception as e:
        logger.error('Unexpected error: %s', e)
        return jsonify({'error': 'Internal server error'}), 500


if __name__ == '__main__':
    init_relay()
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    finally:
        cleanup()

