import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit_servokit library not found. Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants
SERVO_CHANNELS = 16
DEFAULT_SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
MOVEMENT_DELAY = 0.04
STEP_SIZE = 5

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_servokit(channels=SERVO_CHANNELS, i2c_address=0x40, i2c_busnum=1):
    """Initializes the ServoKit object with error handling."""
    try:
        kit = ServoKit(channels=channels, address=i2c_address, i2c=None)
        return kit
    except OSError as e:
        print(f"Error initializing ServoKit (I2C address 0x{i2c_address:02X} on bus {i2c_busnum}): {e}")
        print("Check wiring and I2C configuration. Run 'i2cdetect -y 1' to verify the device is present.")
        return None
    except ValueError as e:
        print(f"Invalid ServoKit configuration: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        return None


def move_servo(kit, servo_num, target_angle):
    """Moves a servo to a target angle with error handling."""
    if not isinstance(servo_num, int) or not (0 <= servo_num < kit.servo.channels):
        print(f"Error: Invalid servo number {servo_num}. Must be an integer between 0 and {kit.servo.channels - 1}.")
        return False

    if not isinstance(target_angle, (int, float)) or not (0 <= target_angle <= 180):
        print(f"Error: Invalid target angle {target_angle}. Must be a number between 0 and 180 degrees.")
        return False

    try:
        current_angle = kit.servo[servo_num].angle
        if current_angle is None:
            current_angle = 0

        step = STEP_SIZE if target_angle > current_angle else -STEP_SIZE
        angle = int(current_angle)

        while (step > 0 and angle < target_angle) or (step < 0 and angle > target_angle):
            angle += step
            kit.servo[servo_num].angle = float(angle)
            time.sleep(MOVEMENT_DELAY)

        kit.servo[servo_num].angle = float(target_angle)
        return True

    except OSError as e:
        print(f"I2C bus error moving servo {servo_num}: {e}")
        return False
    except ValueError as e:
        print(f"Value error moving servo {servo_num}: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")
        return False


def grab_object(kit, servo_num=DEFAULT_SERVO_CHANNEL):
    """Grabs an object by moving the servo to the grab position."""
    print(f"Grabbing object with servo {servo_num}...")
    return move_servo(kit, servo_num, GRAB_ANGLE)


def release_object(kit, servo_num=DEFAULT_SERVO_CHANNEL):
    """Releases an object by moving the servo to the release position."""
    print(f"Releasing object with servo {servo_num}...")
    return move_servo(kit, servo_num, RELEASE_ANGLE)


def main():
    """Main function to demonstrate servo control."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        if not grab_object(kit):
            print("Grab failed. Continuing to release for demonstration.")
        if not release_object(kit):
            print("Release failed.")
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        print("Program finished.")


if __name__ == "__main__":
    main()

