import signal
import sys
import logging
from gpiozero import OutputDevice

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")

PUMP_PIN = 20
LIGHT_PIN = 21

pump = None
light = None


def apply_intent(phrase):
    """Return the intent name (pump_on, pump_off, light_toggle) or None."""
    lowered = phrase.lower()
    if "pump on" in lowered:
        return "pump_on"
    if "pump off" in lowered:
        return "pump_off"
    if "light" in lowered:
        return "light_toggle"
    return None


def handle_intent(intent):
    """Drive the pump or light based on the recognized intent."""
    if intent == "pump_on":
        pump.on()
        logging.info("Pump ON")
    elif intent == "pump_off":
        pump.off()
        logging.info("Pump OFF")
    elif intent == "light_toggle":
        light.toggle()
        logging.info("Light toggled")
    else:
        logging.warning("Unknown intent: %s", intent)


def cleanup(signum=None, frame=None):
    """Turn off actuators and release resources on exit."""
    global pump, light
    for dev in (pump, light):
        if dev is not None:
            try:
                dev.off()
                dev.close()
            except Exception:
                pass
    if signum is not None:
        logging.info("Received signal %d, exiting.", signum)
        sys.exit(0)


def main():
    global pump, light
    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
    except Exception as e:
        logging.error("Failed to initialize GPIO devices: %s", e)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]

    for phrase in test_phrases:
        intent = apply_intent(phrase)
        if intent:
            handle_intent(intent)
        else:
            logging.info("No intent recognized in: %s", phrase)

    cleanup()


if __name__ == "__main__":
    main()

