import signal
import sys
from datetime import datetime
from smbus2 import SMBus


class DS1338:
    """Driver for the Maxim DS1338 I2C RTC (24-hour, BCD format)."""

    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06

    def __init__(self, i2c_bus=1, address=0x68):
        self.address = address
        self.bus = None
        self._closed = False
        try:
            self.bus = SMBus(i2c_bus)
        except OSError as exc:
            raise RuntimeError(
                f"Cannot open I2C bus {i2c_bus}: {exc}"
            ) from exc

        # Probe the device with a zero-length write.
        try:
            self.bus.write_quick(self.address)
        except OSError as exc:
            self._close()
            raise RuntimeError(
                f"No DS1338 found at 0x{address:02X} on bus {i2c_bus}: {exc}"
            ) from exc

        # Install signal handlers for clean shutdown.
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

    # ------------------------------------------------------------------
    # BCD helpers
    # ------------------------------------------------------------------
    @staticmethod
    def _bcd_to_int(bcd):
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(n):
        return ((n // 10) << 4) | (n % 10)

    # ------------------------------------------------------------------
    # Per-register helpers
    # ------------------------------------------------------------------
    def _read_register(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as exc:
            raise RuntimeError(
                f"I2C read from register 0x{register:02X} failed: {exc}"
            ) from exc

    def _write_register(self, register, value):
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as exc:
            raise RuntimeError(
                f"I2C write to register 0x{register:02X} failed: {exc}"
            ) from exc

    # ------------------------------------------------------------------
    # Public read API
    # ------------------------------------------------------------------
    def read_seconds(self):
        return self._bcd_to_int(self._read_register(self.REG_SECONDS) & 0x7F)

    def read_minutes(self):
        return self._bcd_to_int(self._read_register(self.REG_MINUTES))

    def read_hours(self):
