    # BCD helpers
    # ------------------------------------------------------------------
    @staticmethod
    def _bcd_to_int(bcd):
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(n):
        return ((n // 10) << 4) | (n % 10)

