import serial
import time
import signal
import sys

ESP_OK = b"OK"
ESP_ERROR = b"ERROR"
ESP_FAIL = b"FAIL"
ESP_READY = b"ready"


class ESP8266:
    def __init__(self, port="/dev/serial0", baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None
        try:
            self.ser = serial.Serial(
                port=port,
                baudrate=baud_rate,
                timeout=timeout,
                write_timeout=timeout
            )
        except serial.SerialException as e:
            print(f"Error opening serial port {port}: {e}")
            raise

    def _send_command(self, command, timeout=1.0, wait_for=ESP_OK):
        if not self.ser or not self.ser.is_open:
            print("Serial port is not open.")
            return None
        try:
            self.ser.reset_input_buffer()
            self.ser.write(command)
            self.ser.flush()
            response = b""
            start_time = time.time()
            while (time.time() - start_time) < timeout:
                if self.ser.in_waiting > 0:
                    response += self.ser.read(self.ser.in_waiting)
                    if wait_for in response:
                        return response
                else:
                    time.sleep(0.01)
            return response if response else None
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None

    def test_connection(self):
        response = self._send_command(b"AT\r\n", timeout=1.0, wait_for=ESP_OK)
        return response is not None and ESP_OK in response

    def restart(self):
        response = self._send_command(b"AT+RST\r\n", timeout=2.0, wait_for=ESP_READY)
        if response is None:
            return False
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"\r\n'.encode()
        response = self._send_command(command, timeout=10.0, wait_for=ESP_OK)
        return response is not None and ESP_OK in response

    def disconnect_wifi(self):
        response = self._send_command(b"AT+CWQAP\r\n", timeout=1.0, wait_for=ESP_OK)
        return response is not None and ESP_OK in response

    def get_ip(self):
        response = self._send_command(b"AT+CIFSR\r\n", timeout=1.0)
        if response:
            try:
                ip_address = response.split(b"+CIFSR:STAIP,")[1].split(b'"')[1].decode()
                return ip_address
            except IndexError:
                return None
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if headers is None:
            headers = []
        if data:
            headers.append(f"Content-Length: {len(data)}\r\n")
        request = (
            f"{method} {url} HTTP/1.1\r\n"
            f"Host: {host}\r\n"
            f"{headers}\r\n"
        ).encode()
        if data:
            request += data.encode()
        response = self._send_command(
            f'AT+CIPSTART="TCP","{host}",{port}\r\n'.encode(),
            timeout=2.0,
            wait_for=ESP_OK
        )
        if response is None or ESP_OK not in response:
            return None
        response = self._send_command(
            b"AT+CIPSEND\r\n",
            timeout=1.0,
            wait_for=b">"
        )
        if response is None or b">" not in response:
            return None
        response = self._send_command(request, timeout=5.0)
        if response is None:
            return None
        return response

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        response = b""
        while (time.time() - start_time) < timeout:
            if self.ser.in_waiting > 0:
                response += self.ser.read(self.ser.in_waiting)
                if b"+IPD," in response:
                    break
            else:
                time.sleep(0.01)
        if b"+IPD," in response:
            try:
                _, _, length_str, payload = response.split(b"+IPD,")[1].split(b":")
                length = int(length_str)
                remaining = length - (len(response) - response.find(b":") - 1)
                while remaining > 0:
                    chunk = self.ser.read(min(remaining, 1024))
                    if not chunk:
                        break
                    response += chunk
                    remaining -= len(chunk)
                return response
            except ValueError:
                return None
        return None

    def close(self):
        if self.ser and self.ser.is_open:
            self.ser.close()


def main():
    esp = None
    def signal_handler(sig, frame):
        if esp:
            esp.close()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        esp = ESP8266(port="/dev/serial0", baud_rate=115200, timeout=1.0)
        if not esp.test_connection():
            print("Failed to connect to ESP8266.")
            return
        print("ESP8266 connected.")
        esp.restart()
        esp.connect_wifi("SSID", "PASSWORD")
        ip = esp.get_ip()
        print(f"IP Address: {ip}")
        esp.disconnect_wifi()
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if esp:
            esp.close()


if __name__ == "__main__":
    main()

