import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

running = True
serial_connection = None
alarm = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global serial_connection, alarm
    if alarm is not None:
        try:
            alarm.off()
            alarm.close()
        except Exception:
            pass
        alarm = None
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
        except Exception:
            pass
        serial_connection = None


def main():
    global serial_connection, alarm

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        from gpiozero import OutputDevice
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Failed to initialize GPIO pin {ALARM_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_INTERVAL,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    alarm_active = False

    try:
        while running:
            try:
                raw_data = serial_connection.readline()
            except serial.SerialException as e:
                print(f"Serial I/O error: {e}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            if not raw_data:
                continue

            try:
                data = raw_data.decode('ascii', errors='replace').strip()
            except Exception:
                continue

            if not data:
                continue

            try:
                radiation_level = float(data)
            except ValueError:
                print(f"Invalid data received (not numeric): {data!r}")
                continue

            print(f"Radiation Level: {radiation_level:.2f} uSv/h")

            if radiation_level > RADIATION_THRESHOLD:
                if not alarm_active:
                    alarm.on()
                    alarm_active = True
                    print("Alarm triggered!")
            else:
                if alarm_active:
                    alarm.off()
                    alarm_active = False
                    print("Alarm cleared.")

            time.sleep(READ_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

