import serial
import time
import signal
import sys

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

running = True

def signal_handler(sig, frame):
    global running
    running = False

def nmea_to_decimal(raw_value, direction):
    if not raw_value or not direction:
        return None
    try:
        dot_pos = raw_value.find('.')
        if dot_pos == -1:
            return None
        degrees_len = dot_pos - 2
        if degrees_len <= 0:
            return None
        degrees = float(raw_value[:degrees_len])
        minutes = float(raw_value[degrees_len:])
        decimal = degrees + (minutes / 60.0)
        if direction in ('S', 'W'):
            decimal = -decimal
        return decimal
    except (ValueError, IndexError):
        return None

def parse_gprmc(data):
    if not data.startswith('$GPRMC'):
        return None, None
    parts = data.split(',')
    if len(parts) < 7:
        return None, None
    status = parts[2]
    if status != 'A':
        return None, None
    lat = nmea_to_decimal(parts[3], parts[4])
    lon = nmea_to_decimal(parts[5], parts[6])
    return lat, lon

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                lat, lon = parse_gprmc(line)
                if lat is not None and lon is not None:
                    print(f"Latitude: {lat:.6f}, Longitude: {lon:.6f}")
                time.sleep(1)
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                time.sleep(1)
            except Exception as e:
                print(f"Unexpected error: {e}")
                time.sleep(1)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

