            self.serial_port = None
            self.is_connected = False
            return False
        except OSError as e:
            logging.error(f"OS error opening serial port {self.port}: {e}")
            self.serial_port = None
            self.is_connected = False
            return False

    def disconnect(self) -> None:
        """Close the serial port if open. Guaranteed to not raise."""
        if not self.is_connected and self.serial_port is None:
            return

        try:
            if self.serial_port is not None and self.serial_port.is_open:
                self.serial_port.close()
                logging.info("Serial port closed.")
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")
        finally:
            self.serial_port = None
            self.is_connected = False

    def _nmea_to_decimal(self, value: str, direction: str) -> Optional[float]:
        """Convert NMEA ddmm.mmmm to decimal degrees, applying sign from direction."""
        if not value or not direction:
            return None
        try:
            dot = value.index(".")
            deg_len = dot - 2
            degrees = float(value[:deg_len])
            minutes = float(value[deg_len:])
            decimal = degrees + minutes / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError) as e:
            logging.error(f"NMEA conversion error for value '{value}': {e}")
            return None

    def _verify_checksum(self, sentence: str) -> bool:
        """Validate NMEA checksum: *XX where XX is the two-digit XOR of the body."""
        if "*" not in sentence:
            return False
        body, _, csum = sentence.partition("*")
        if len(csum) < 2:
            return False
        try:
            expected = int(csum[:2], 16)
        except ValueError:
            return False
        computed = 0
        for ch in body:
            computed ^= ord(ch)
        return computed == expected

    def read_gps_data(self) -> Optional[GPS_readings]:
        """Read one line and parse GPGGA. Returns GPS_readings or None."""
        if not self.is_connected or self.serial_port is None:
            logging.warning("Not connected to GPS. Call connect() first.")
            return None

        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None
        except OSError as e:
            logging.error(f"OS read error: {e}")
            return None

        if not raw:
            logging.warning("Read timeout: no data received.")
            return None

        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as e:
            logging.error(f"Decode error: {e}")
            return None

        if not line.startswith("$GPGGA"):
            return None

        if not self._verify_checksum(line):
            logging.warning(f"Checksum mismatch or invalid format: {line}")
            return None

        parts = line.split(",")
        if len(parts) < 15:
            logging.warning(f"Incomplete GPGGA sentence: {line}")
            return None

        try:
            fix_quality = int(parts[6])
            if fix_quality == 0:
                logging.debug("No GPS fix (fix quality 0).")
                return GPS_readings()
        except ValueError:
            logging.warning(f"Invalid fix quality field: {parts[6]}")
            return None

        lat_raw = parts[2]
        lat_dir = parts[3]
        lon_raw = parts[4]
        lon_dir = parts[5]

        readings = GPS_readings()
        readings.latitude = self._nmea_to_decimal(lat_raw, lat_dir)
        readings.longitude = self._nmea_to_decimal(lon_raw, lon_dir)

        try:
            readings.altitude = float(parts[9]) if parts[9] else None
            readings.num_satellites = int(parts[7]) if parts[7] else None
        except (ValueError, IndexError) as e:
            logging.error(f"Numeric conversion error in GPGGA: {e}")
            return None

        return readings


def main() -> None:
    gps = GPSReader()

    def _signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        gps.disconnect()
        sys.exit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not gps.connect():
        logging.error("Failed to connect to GPS. Exiting.")
        sys.exit(1)

    try:
        while True:
            data = gps.read_gps_data()
            if data is not None:
                lat = data.latitude
                lon = data.longitude
                alt = data.altitude
                n_sat = data.num_satellites
                logging.info(
                    f"GPS: lat={lat}, lon={lon}, alt={alt}, sat={n_sat}"
                )
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        gps.disconnect()


if __name__ == "__main__":
    main()

