        decoded_data = raw_data.decode('ascii', errors='replace').strip()
        if not decoded_data:
            return None
        return decoded_data
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def process_pulse_oximeter_data(data):
    try:
        parts = data.split(',')
        if len(parts) != 2:
            raise ValueError(f"Expected 2 fields, got {len(parts)}")
