        spo2 = int(parts[1])
        return heart_rate, spo2
    except ValueError as e:
        print(f"Invalid data format (expected '<hr>,<spo2>'): {e} | raw='{data}'", file=sys.stderr)
        return None

def display_pulse_oximeter_readings(heart_rate, spo2):
