import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'


def log_power_data(power_value: float) -> None:
    """Append a timestamped power-consumption entry to the log file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power_value} W\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(log_entry)
    except OSError as exc:
        print(f'Error writing to log file: {exc}', file=sys.stderr)


def main() -> None:
    """Open the serial port, read meter data, and log it until interrupted."""
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f'Error opening serial port {SERIAL_PORT}: {exc}', file=sys.stderr)
        sys.exit(1)
    except OSError as exc:
        print(f'OS error opening {SERIAL_PORT}: {exc}', file=sys.stderr)
        sys.exit(1)

    print(f'Listening on {SERIAL_PORT} @ {BAUD_RATE} baud (Ctrl+C to stop)')

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f'Serial read error: {exc}', file=sys.stderr)
                break

            if not raw:
                continue  # timeout — no data within 1 s

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                power = float(line)
            except ValueError:
                print(f'Warning: non-numeric data received: {line!r}', file=sys.stderr)
                continue

            log_power_data(power)
            print(f'Power: {power} W')

    except KeyboardInterrupt:
        print('\nInterrupted by user.')
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print('Serial port closed.')


if __name__ == '__main__':
    main()

