import signal
import sys
import time
from typing import List, Dict, Any, Optional

from flask import Flask, Response, request, jsonify, abort

try:
    import serial
except ImportError:
    serial = None

app = Flask(__name__)

store: List[Dict[str, Any]] = [
    {"id": 1, "name": "Existing Item 1", "done": False},
    {"id": 2, "name": "Existing Item 2", "done": False},
]

serial_port: Optional[serial.Serial] = None


def _close_serial() -> None:
    global serial_port
    if serial_port is not None:
        try:
            if serial_port.is_open:
                serial_port.close()
        except Exception:
            pass
        serial_port = None


def _signal_handler(signum, frame):
    _close_serial()
    sys.exit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def _next_id() -> int:
    return (store[-1]["id"] + 1) if store else 1


def _get_item(item_id: int) -> Optional[Dict[str, Any]]:
    for item in store:
        if item["id"] == item_id:
            return item
    return None


@app.route("/version", methods=["GET"])
def version() -> Response:
    if serial is None:
        return Response("pyserial not installed", status=503, mimetype="text/plain")
    ser = None
    try:
        ser = serial.Serial("/dev/ttyUSB0", 9600, timeout=1)
        ser.write(b"*IDN?\n")
        time.sleep(0.1)
        raw = ser.read(4096)
        if not raw:
            return Response("No response from instrument", status=503, mimetype="text/plain")
        text = raw.decode("utf-8", errors="replace")
        html = text.replace("\n", "<br>")
        return Response(html, mimetype="text/html")
    except serial.SerialException as exc:
        return Response(f"Serial error: {exc}", status=503, mimetype="text/plain")
    except Exception as exc:
        return Response(f"Unexpected error: {exc}", status=503, mimetype="text/plain")
    finally:
        if ser is not None:
            try:
                if ser.is_open:
                    ser.close()
            except Exception:
                pass


@app.route("/getdata", methods=["GET"])
def get_data() -> Response:
    return jsonify(store)


@app.route("/getset/<int:item_id>", methods=["GET"])
def get_set(item_id: int) -> Response:
    item = _get_item(item_id)
    if item is None:
        abort(404, description="Item not found")
    return jsonify(item)


@app.route("/getpost/<int:item_id>/<name>", methods=["GET"])
def get_post(item_id: int, name: str) -> Response:
    new_item = {
        "id": item_id,
        "name": name,
        "done": False,
    }
    store.append(new_item)
    return jsonify(store)


@app.route("/postjson", methods=["POST"])
def post_json() -> Response:
    ct = request.headers.get("Content-Type", "")
    if ct == "application/json":
        try:
            data = request.get_json(silent=False)
        except Exception:
            abort(400, description="Invalid JSON body")
    else:
        data = request.form.to_dict()

    if not isinstance(data, dict):
        abort(400, description="Invalid or missing JSON/form data")

    new_item: Dict[str, Any] = {
        "id": _next_id(),
        "name": data.get("name", ""),
        "done": bool(data.get("done", False)),
    }
    store.append(new_item)
    return jsonify(store)


@app.route("/getjson", methods=["GET"])
def get_json() -> Response:
    return jsonify(store)


if __name__ == "__main__":
    try:
        app.run(host="0.0.0.0", port=5000)
    finally:
        _close_serial()

