import serial
import time
import sys

BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400
COMMAND_PREFIX = "X"
TERMINATOR = "\n"
SEND_DELAY = 0.1


def send_command(bluetooth_connection, command):
    """Sends a formatted command to the Bluetooth device."""
    try:
        full_command = COMMAND_PREFIX + command + TERMINATOR
        bytes_written = bluetooth_connection.write(full_command.encode("utf-8"))
        if bytes_written != len(full_command):
            raise RuntimeError(
                f"Incomplete write: expected {len(full_command)} bytes, wrote {bytes_written}"
            )
        bluetooth_connection.flush()
    except serial.SerialException as e:
        raise RuntimeError(f"Serial communication error: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to send command: {e}") from e


def main():
    bluetooth_connection = None
    try:
        bluetooth_connection = serial.Serial(
            port=BLUETOOTH_PORT,
            baudrate=BLUETOOTH_BAUD_RATE,
            timeout=1
        )
        print(f"Connected to Bluetooth device on {BLUETOOTH_PORT} at {BLUETOOTH_BAUD_RATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                break

            try:
                send_command(bluetooth_connection, user_command)
                print(f"Sent: {user_command}")
            except RuntimeError as e:
                print(f"Error: {e}", file=sys.stderr)

            time.sleep(SEND_DELAY)

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {BLUETOOTH_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received. Exiting...")
    finally:
        if bluetooth_connection is not None and bluetooth_connection.is_open:
            bluetooth_connection.close()
            print("Bluetooth connection closed.")


if __name__ == "__main__":
    main()

